-- 0264 turismo_rural_expand (inventario_turismo_rural_pdf) — entidades + puntuaciones
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33056','rural','Oferta de turismo rural','Alojamientos rurales: Palacetes indianos a pie de playa, casonas rurales señoriales con hórreos tradicionales en las parroquias interiores de su término y apartamentos rústicos de costa. Entorno y actividades: Desembocadura del río Sella y Cuevas del agua de Tito Bustillo (Patrimonio de la Humanidad). Destaca por la espectacular ruta de senderismo costero de los Acantilados de Guadamía (donde se encuentran los bufones o chimeneas de roca que expulsan agua marina a presión), las huellas de dinosaurio en los acantilados de la playa de Vega, y rutas fluviales en kayak.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33076','rural','Oferta de turismo rural','Alojamientos rurales: Casas de aldea tradicionales con hórreo, hoteles rurales integrados en pomaradas (campos de manzanos) y casonas de piedra mariñanas. Entorno y actividades: Reserva Natural Parcial de la Ría de Villaviciosa. Ofrece rutas de observación de aves acuáticas, la Senda del río Profundo entre antiguos molinos, y playas salvajes rodeadas de acantilados como Rodiles.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90682','rural','Oferta de turismo rural','Alojamientos rurales: Casas de piedra y pizarra tradicionales del suroccidente asturiano en valles recónditos, hostales rurales con chimeneas de leña orientados a peregrinos del Camino Primitivo y apartamentos de montaña. Entorno y actividades: Sierras del Suroccidente y paso clave del Camino de Santiago Primitivo. Destaca por las rutas de senderismo de alta montaña que ascienden al Puerto del Palo y la Senda del Teixo (visita al tejo milenario de Santa Coloma, Monumento Natural protegido). Ofrece caminatas por el Valle del Oro entre antiguos restos de explotaciones mineras romanas, bosques autóctonos vírgenes de robles y quejigos, y territorio de avistamiento de fauna cantábrica.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90015','rural','Oferta de turismo rural','Alojamientos rurales: Casonas montañesas tradicionales con corredores de madera tallada, apartamentos rurales con vistas al mar Cantábrico y a la montaña, y hoteles de campo íntimos rodeados de prados. Entorno y actividades: Faldas del Paisaje Protegido de la Sierra del Sueve. Ofrece la espectacular y exigente ruta de senderismo de ascensión al Pico Pienzu (vistas de pájaro inigualables que combinan la alta montaña caliza y la costa marina a la vez). Caminatas para observar los caballos asturcones salvajes en libertad, senderos botánicos de hayedos costeros y micología otoñal. 📂 PROVINCIA: TOLEDO (Castilla-La Mancha Datos Curados).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90641','rural','Oferta de turismo rural','Alojamientos rurales: Casas de aldea típicas del Alto Nalón, apartamentos rústicos con chimenea de leña y cabañas de montaña rehabilitadas. Entorno y actividades: Corazón del Parque Natural de Redes (Reserva de la Biosfera). Destaca por la famosa Ruta del Alba (desfiladero fluvial), el Monumento Natural de la Cascada del Tabayón del Mongallu y bosques de hayas centenarios.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33067','rural','Oferta de turismo rural','Alojamientos rurales: Alojamientos rurales con encanto en núcleos rurales compactos y premiados, casas de piedra recuperadas con techos de madera. Entorno y actividades: Integrado en el Parque Natural de Redes. Ofrece la Ruta de los Arrudos (uno de los desfiladeros más bellos y boscosos de Asturias), el embalse de Tanes y senderos de montaña adaptados para familias.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90639','rural','Oferta de turismo rural','Alojamientos rurales: Casonas señoriales de indianos, apartamentos rurales familiares con jardín y barbacoa independientes, y alojamientos rurales integrados en aldeas apícolas. Entorno y actividades: Cuenca media del río Navia. Destaca por la ruta de senderismo de las Albarregas (recorrido etnográfico que muestra los antiguos amurallamientos circulares de piedra construidos en el monte para proteger las colmenas de los ataques del oso pardo). Ofrece caminatas que bordean el Embalse de Doiras, piragüismo, senderos forestales de pinos y castaños, y miradores fluviales espectaculares.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33074','rural','Oferta de turismo rural','Alojamientos rurales: Casas de aldea en el valle interior, hoteles rurales con fincas agrarias y antiguos molinos harineros reconvertidos. Entorno y actividades: Reserva de la Biosfera del Río Eo, Oscos y Terras de Burón. Rutas de senderismo por la Senda Verde de la antigua vía del tren, actividades de remo en la ría del Eo y paseos por bosques autóctonos atlánticos.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33034','rural','Oferta de turismo rural','Alojamientos rurales: Fincas agro-rurales aisladas, hoteles boutique de costa, y casas rurales rodeadas de prados verdes y ganado. Entorno y actividades: Paisaje Protegido de la Costa Occidental. Destaca por las rutas fluviales del río Esva (Hoces del Esva), senderismo por el Cabo Busto y sus playas de cantos rodados y calas ocultas.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90013','rural','Oferta de turismo rural','Alojamientos rurales: Casas palacio rurales de gran porte, palacetes de indianos con amplios jardines históricos, y apartamentos rurales con vistas directas al estuario de la ría. Entorno y actividades: Ribera asturiana de la Reserva de la Biosfera de la Ría del Eo. Ofrece una combinación perfecta de turismo forestal de interior y ría. Destaca por la espectacular ruta de senderismo de la Cascada de Cioyo (un desfiladero angosto con saltos de agua y pozas naturales turquesas ocultas en la fronda). Ofrece observación ornitológica de primer nivel de aves acuáticas migratorias en las marismas, rutas en kayak y paseos botánicos.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33027','rural','Oferta de turismo rural','Alojamientos rurales: Albergues y casas de aldea construidas con la característica mampostería oscura y losas de pizarra, hostales rurales junto a la vía del Camino de Santiago y casonas rústicas de montaña. Entorno y actividades: Entorno alto del gran Embalse de Salime y cuenca del río Navia. Destaca por las rutas de senderismo fluvial y de media montaña que bordean el embalse, paseos de interpretación histórica y etnográfica (conectando con el Museo Etnográfico de Grandas), caminatas bajo bosques de castaños milenarios y quejigos, piragüismo de interior y rutas cicloturistas de carretera sin tráfico.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33033','rural','Oferta de turismo rural','Alojamientos rurales: Casas de montaña de piedra, hostales rurales especializados en ciclismo de carretera y alojamientos de esquí. Entorno y actividades: Parque Natural de Las Ubiñas-La Mesa. Destaca por las rutas de senderismo de alta montaña hacia el Macizo de las Ubiñas, senderos de la Vía Romana de la Carisa y rutas ciclistas en puertos míticos (Cuitu Negru).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33053','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales de pastores restauradas, apartamentos rústicos al pie de paredes de escalada. Entorno y actividades: Parque Natural de Las Ubiñas-La Mesa y Senda del Oso. Destaca por las rutas cicloturistas de la Senda del Oso, la escuela internacional de escalada en roca de El Llano y senderos de montaña boscosos.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33049','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles rurales con encanto rodeados de avellanos, antiguas casonas agrícolas y casas de aldea independientes. Entorno y actividades: Sierra del Sueve y valles del río Piloña. Ofrece rutas ecuestres para ver los caballos asturcones en libertad, el sendero de las Hoces del río Espinaredo y áreas recreativas boscosas como La Pesanca.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90637','rural','Oferta de turismo rural','Alojamientos rurales: Chalets de montaña de madera y piedra, albergues de senderistas y apartamentos de turismo de nieve. Entorno y actividades: Valle del Aller y entorno de San Isidro. Destaca por las rutas senderistas al Monumento Natural de las Foces del Pino (desfiladero calizo), senderos hacia el Puerto de San Isidro y rutas de raquetas.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33041','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales mariñanas, hoteles de campo con amplios jardines y apartamentos turísticos de costa. Entorno y actividades: Desembocadura del río Navia. Ofrece la Senda Costera Naviega (ruta senderista por acantilados y playas salvajes como Barayo), descensos fluviales en canoa y paseos por bosques de ribera.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33052','rural','Oferta de turismo rural','Alojamientos rurales: Casas de pueblo de alquiler íntegro de arquitectura tradicional, pequeños hostales rurales con encanto. Entorno y actividades: Eje central de la Senda del Oso. Ofrece cicloturismo por la antigua vía minera reconvertida, senderismo por el Desfiladero de Peñas Juntas y rutas al hermoso pueblo colgado de Bandujo (conjunto histórico).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33061','rural','Oferta de turismo rural','Alojamientos rurales: Antiguas casas rectorales recuperadas, casas de aldea unifamiliares con huerto e instalaciones que conservan los hornos tradicionales de piedra y los tejados de pizarra negra. Entorno y actividades: Integrado en la Reserva de la Biosfera de Los Oscos. Ofrece paseos etnográficos de aislamiento absoluto, rutas de senderismo de la Senda Verde del río Agüeira, caminatas boscosas por los robledales de Mon, rutas micológicas otoñales extremas en sus laderas umbrías y senderos de herradura históricos totalmente aislados del ruido urbano.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33062','rural','Oferta de turismo rural','Alojamientos rurales: Casonas e hidalguías tradicionales de piedra integradas en conjuntos etnográficos de pizarra, apartamentos rurales eco-bioclimáticos y casas de aldea unifamiliares con porches de madera. Entorno y actividades: En el corazón de la comarca de Los Oscos. Entorno de aislamiento geográfico y naturaleza atlántica virgen. Sede de la célebre ruta de senderismo de la Cascada de Seimeira (un espectacular salto de agua de más de 15 metros en caída libre escondido en un bosque cerrado). Ofrece caminatas que visitan el mazo de Mazonovo, dehesas e itinerarios micológicos otoñales, talleres de forja artesana tradicional de navajas y senderos pastoriles. 📂 PROVINCIA: LANZAROTE (Canarias - Datos Curados).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33075','rural','Oferta de turismo rural','Alojamientos rurales: Casas de turismo de aldea con muros anchos aislantes, apartamentos rústicos pequeños en pequeños núcleos de montaña y alojamientos vinculados al Monasterio de Santa María. Entorno y actividades: Los Oscos orientales, alta montaña asturiana. Destaca por la espectacular ruta de senderismo de la Senda de la Bobia (itinerario de media-alta montaña salpicado de túmulos y monumentos megalíticos prehistóricos integrados en las dehesas altas). Caminatas por el denso bosque atlántico de la Carballeira de Santa Eufemia, senderos micológicos en temporada de otoño y rutas ganaderas. PROVINCIA: HUESCA - COMPLEMENTO DE PIRINEOS (Texto Plano Limpio).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33028','rural','Oferta de turismo rural','Alojamientos rurales: Casas de turismo rural con bodegas tradicionales de viñedo heroico, construcciones de piedra aisladas. Entorno y actividades: Frontera con el Parque de Fuentes del Narcea. Ofrece rutas de senderismo entre viñedos escarpados de montaña, visitas a los "cortines" (colmenas circulares de piedra contra osos) y senderos fluviales vírgenes.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33022','rural','Oferta de turismo rural','Alojamientos rurales: Cabañas forestales de montaña, apartamentos rústicos de madera para observadores de fauna. Entorno y actividades: Parque Natural de las Fuentes del Narcea, Degaña e Ibias. Uno de los mejores enclaves para el rastreo guiado del oso pardo, rutas senderistas por las lagunas glaciares de Fasgueo y senderos entre abedulares.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05003','rural','Oferta de turismo rural','Alojamientos rurales: Casonas de campo tradicionales asturianas, apartamentos rurales junto al río Pigüeña. Entorno y actividades: Valles del Oso. Destaca por la Ruta del Oro (senderismo hacia antiguas minas romanas), senderos que conectan con los pastizales de montaña del Parque de Somiedo y ríos trucheros de aguas cristalinas.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33059','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles rurales en torres medievales, palacetes agrícolas, albergues de peregrinos del Camino de Santiago. Entorno y actividades: Destaca por la ruta de senderismo del ríofiel a la Cascada de Nonaya, valles boscosos interiores, rutas micológicas y ríos salmoneros como el Narcea.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33051','rural','Oferta de turismo rural','Alojamientos rurales: Casonas rurales hidalgas, apartamentos rústicos en antiguas vegas agrícolas fluviales. Entorno y actividades: Bajo Nalón. Rutas de senderismo de los miradores del Nalón, paseos en piragua por el tramo bajo del río Nalón, senderos llanos entre plantaciones de kiwis y masas forestales.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33070','rural','Oferta de turismo rural','Alojamientos rurales: Apartamentos rurales de playa, hoteles boutique costeros, casas de aldea en el entorno costero. Entorno y actividades: Costa occidental extrema. Ofrece la ruta senderista de los acantilados de Tapia, senderos costeros hacia las playas de Penarronda y paseos marineros integrados en el paisaje atlántico.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90014','rural','Oferta de turismo rural','Alojamientos rurales: Casas de labor rehabilitadas, apartamentos rústicos con amplias fincas verdes para familias. Entorno y actividades: Ofrece la ruta senderista del río Navia, paseos hacia el Cabo Blanco, y senderos rodeados de densos bosques de castaños combinados con visitas al Castro celta de Coaña.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33023','rural','Oferta de turismo rural','Alojamientos rurales: Casas de campo tradicionales occidentales, pequeños apartamentos rurales tranquilos de costa. Entorno y actividades: Destaca por la ruta senderista de las Cuevas de Andina (Monumento Natural de formaciones kársticas en bosque), playas salvajes como Pormenande y sendas litorales.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33072','rural','Oferta de turismo rural','Alojamientos rurales: Alojamientos rurales enfocados al turismo activo, apartamentos de montaña de piedra caliza con chimenea. Entorno y actividades: Parque Natural de Las Ubiñas-La Mesa y Senda del Oso. Ofrece rutas al Monumento Natural de Cueva Huerta, senderismo por el Camín Real de la Mesa (antigua calzada) y puertos de montaña alpinos (San Lorenzo).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33038','rural','Oferta de turismo rural','Alojamientos rurales: Casas de aldea rústicas en la falda de la montaña, hostales rurales tradicionales. Entorno y actividades: Macizo del Monsacro. Destaca por las rutas de senderismo de ascensión a las capillas medievales del Monsacro, senderos entre praderías ganaderas y rutas de escalada deportiva.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33058','rural','Oferta de turismo rural','Alojamientos rurales: Casas de alta montaña de piedra caliza, apartamentos orientados a ciclistas extremos. Entorno y actividades: Falda del mítico Puerto de L''Angliru. Rutas de senderismo hacia la Sierra del Aramo, ascensión a pie o en bicicleta al Angliru (rampas del 23.5%), y senderos de pastores entre lagunas de montaña.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05001','rural','Oferta de turismo rural','Alojamientos rurales: Cabañas rurales colgadas de valles profundos, casas de piedra de montaña tradicionales de alquiler íntegro. Entorno y actividades: Pre-Picos de Europa. Ofrece la espectacular ruta del Camín de la Reina, senderismo vertical por el Desfiladero de los Beyos, barranquismo en el río Dobra y rutas de aguas bravas.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05004','rural','Oferta de turismo rural','Alojamientos rurales: Casas de turismo rural ecológicas, complejos de apartamentos rústicos con hórreo y actividades de huerto. Entorno y actividades: Comarca de la Sidra de interior. Rutas de senderismo llanas entre bosques mixtos de castaños y eucaliptos, sendas fluviales tranquilas y valles de colinas suaves ideales para cicloturismo de relax.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33065','rural','Oferta de turismo rural','Alojamientos rurales: Casas de aldea tradicionales restauradas en valles llanos agrícolas y ganaderos. Entorno y actividades: Destaca por la Ruta de las Fuentes del río Seco, caminatas tranquilas de baja dificultad entre caseríos tradicionales, llagares de sidra artesanos y praderías. PROVINCIA: CANTABRIA (Texto Plano Limpio).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39055','rural','Oferta de turismo rural','Alojamientos rurales: Casonas de piedra tradicionales lebaniegas con escudos heráldicos, hosterías de montaña con acabados en madera de roble y castaño, posadas rurales con chimenea y apartamentos rústicos. Entorno y actividades: Centro geográfico y nexo logístico del Valle de Liébana y del acceso oriental al Parque Nacional de los Picos de Europa. Destaca por el senderismo histórico del Camino Lebaniego hacia el Monasterio de Santo Toribio de Liébana, dehesas y senderos micológicos de montaña, y proximidad directa al Teleférico de Fuente Dé (ascenso vertical al circo glaciar y alta montaña).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39076','rural','Oferta de turismo rural','Alojamientos rurales: Posadas cántabras con balconadas de madera señoriales y escudos heráldicos, hoteles palacio barrocos e históricas casonas montañesas con corraladas de sillería. Entorno y actividades: Entorno litoral mixto y praderas verdes. Rutas de senderismo suave por los acantilados de Ubiarco, paseos cicloturistas costeros, senderos de interpretación botánica en el entorno rupestre de Altamira y rutas a caballo en dehesas rurales linderas.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39015','rural','Oferta de turismo rural','Alojamientos rurales: Cabañas de madera forestales mimetizadas en la montaña, apartamentos alpinos rústicos para montañeros y hoteles de montaña con vistas a las cumbres calizas. Entorno y actividades: Alberga el circo glaciar de Fuente Dé dentro del Parque Nacional de los Picos de Europa. Rutas de senderismo de alta dificultad como la Canal de la Jenduda, el ascenso a los prados altos de Áliva, senderos bajo hayedos y robledales centenarios y rutas invernales con raquetas de nieve.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39091','rural','Oferta de turismo rural','Alojamientos rurales: Casonas montañesas de piedra tradicionales, palacetes agrícolas señoriales y posadas rurales integradas en valles de prados verdes siempre llanos. Entorno y actividades: Incluye gran parte del Parque Natural de Oyambre y el monte Corona. Destaca por el sendero forestal entre Secuoyas Gigantes del monte Cabezón (Monumento Natural), paseos fluviales por el estuario, rutas ornitológicas en marismas y senderos entre robledales antiguos.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39080','rural','Oferta de turismo rural','Alojamientos rurales: Posadas de costa con encanto cántabro, apartamentos rurales con vistas a las marismas y la ría, y casas de aldea tradicionales mariñanas. Entorno y actividades: Corazón del Parque Natural de Oyambre. Ofrece tramos del Camino de Santiago del Norte, rutas de observación de aves acuáticas en las marismas de Rubín y Pombo, paseos por las dunas protegidas de Oyambre y Merón, y surf en playas salvajes rodeadas de acantilados.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39066','rural','Oferta de turismo rural','Alojamientos rurales: Casas de turismo de interior típicas de la comarca caliza, posadas de piedra tradicionales montañesas con grandes arcos rústicos de acceso de sillería y apartamentos con porche. Entorno y actividades: Parque Natural de Saja-Besaya. Destaca por el Monumento Natural de La Fuentona de Ruente (espectacular e inexplicable surgencia kárstica intermitente de la que nace un río de la nada), la Senda de los Puentes, senderos fluviales, caminatas bajo frondosos cajigales (robles) y avistamiento de fauna ibérica (berrea del ciervo).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39097','rural','Oferta de turismo rural','Alojamientos rurales: Cabañas pasiegas auténticas rehabilitadas (antiguos establos unifamiliares de piedra caliza, vigas de roble y pradera vallada independiente), posadas rústicas de valle y hostales de montaña. Entorno y actividades: Comarca de los Valles Pasiegos. Ofrece un paisaje etnográfico único modelado por la ganadería tradicional en laderas verdes de gran pendiente. Rutas de senderismo de media montaña siguiendo el curso alto del río Pas, túneles ferroviarios abandonados de la Engaña integrados en la naturaleza, dehesas agrarias y senderos micológicos.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39047','rural','Oferta de turismo rural','Alojamientos rurales: Apartamentos rurales litorales, hoteles boutique rurales con encanto junto al mar y pequeñas villas rústicas con fincas verdes. Entorno y actividades: Parque Natural de las Marismas de Santoña, Victoria y Joyel. Es un punto clave del norte de España para el turismo ornitológico de aves acuáticas migratorias. Rutas por el sendero costero de la Punta del Brusco y acantilados vírgenes de caliza.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39014','rural','Oferta de turismo rural','Alojamientos rurales: Posadas rurales protegidas, casonas montañesas con solanas orientadas al sur y casas integradas en conjuntos históricos tradicionales. Entorno y actividades: Reserva Nacional de Caza del Saja. Incluye la joya medieval de Bárcena Mayor. Rutas de senderismo por la Senda de los Senderos, caminatas fluviales junto al río Argoza, bosques de hayas primigenios y observación de fauna ibérica.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39057','rural','Oferta de turismo rural','Alojamientos rurales: Casas de piedra y madera para turismo activo, apartamentos de interior con vistas a colosales moles calizas y dehesas. Entorno y actividades: Valle del Asón. Capital de la espeleología y del turismo de aventura en Cantabria por su colosal subsuelo kárstico. Rutas de senderismo a cuevas con arte rupestre (Covalanas), vías ferratas de montaña con puentes colgantes y escalada deportiva vertical.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39083','rural','Oferta de turismo rural','Alojamientos rurales: Cabañas rurales integradas en verdes laderas escarpadas, casonas señoriales del valle, apartamentos con estufa de leña y posadas de alta montaña aisladas de la civilización urbana. Entorno y actividades: Alberga el Parque Natural de los Collados de Asón. Rutas senderistas espectaculares hacia el Nacimiento del Río Asón (colosal cascada en forma de cola de caballo de más de 70 metros brotando del risco), senderismo de alta montaña caliza, exploración de grandes simas kársticas, lapiaces y prados alpinos altos de ganado extensivo. PROVINCIA: LUGO (Galicia - Datos Curados).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39024','rural','Oferta de turismo rural','Alojamientos rurales: Casonas de indianos singulares del modernismo, hoteles rurales burgueses con amplios jardines históricos y posadas de costa. Entorno y actividades: Costa occidental cántabra. Paseos por el Parque de la Estatua, rutas a pie hacia el monte Corona, senderos litorales que cruzan acantilados de caliza y la ría de la Rabia, hábitat protegido de aves palustres y acuáticas.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39037','rural','Oferta de turismo rural','Alojamientos rurales: Posadas reales neoclásicas vinculadas al termalismo histórico de su balneario, casas rurales de piedra junto al río Miera. Entorno y actividades: Comarca de Trasmiera, falda de las "Tetas de Liérganes". Senderismo fluvial junto al río Miera, rutas botánicas, paseos ecológicos hacia el Balneario y caminatas de media montaña a picos calizos limítrofes.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39022','rural','Oferta de turismo rural','Alojamientos rurales: Apartamentos rústicos de madera de castaño, casas rurales con porche integradas en dehesas y viñedos lebaniegos de colina. Entorno y actividades: Entrada norte al Valle de Liébana a través del espectacular Desfiladero de la Hermida. Senderismo por la canal de Urdón hacia el pueblo colgado de Tresviso, rutas cicloturistas de montaña y castañares centenarios protegidos.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39061','rural','Oferta de turismo rural','Alojamientos rurales: Posadas de diseño surfero y ecológico, apartamentos rurales costeros rodeados de amplias praderas verdes siempre ganaderas. Entorno y actividades: Primera Reserva de Surf de España. Destaca por el espectacular sendero costero de los acantilados que conecta Loredo con Langre, rutas litorales a pie por las dunas del Puntal e islas protegidas de la Bahía de Santander.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39092','rural','Oferta de turismo rural','Alojamientos rurales: Antiguas casas de labranza castellano-cántabras de sillería gruesa, posadas rurales de interior con chimenea y fragua rústica. Entorno y actividades: Sur de Cantabria (valles altos del río Camesa). Posee la mayor concentración de menhires prehistóricos del país. Rutas de senderismo de la Senda de los Menhires, senderos por formaciones kársticas y valles de llanura cerealista.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90246','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales de piedra de mampostería, apartamentos rústicos pequeños para familias y senderistas de paso. Entorno y actividades: Valle del Besaya. Alberga el tramo mejor conservado de la Calzada Romana de los Blendios. Senderismo histórico empedrado bajo robles y castaños entre Pie de Concha y Pesquera, y rutas fluviales de montaña. PROVINCIA: HUESCA (Texto Plano Limpio).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39025','rural','Oferta de turismo rural','Alojamientos rurales: Grandes casonas señoriales hidalgas reconvertidas en hoteles rurales, apartamentos rústicos de valle. Entorno y actividades: Valle de Buelna. Senderismo por las cumbres del Monte Tejas, rutas botánicas por el pinar de Coo, sendas hacia el Parque de Saja-Besaya y caminatas arqueológicas para ver las estelas gigantes cántabras.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39072','rural','Oferta de turismo rural','Alojamientos rurales: Cabañas pasiegas aisladas en laderas escarpadas, apartamentos rústicos tradicionales de alta montaña de piedra caliza y pizarra. Entorno y actividades: El valle pasiego más agreste y de origen glaciar. Senderismo de alta dificultad por los lapiaces y rasos calcáreos, rutas junto al nacimiento del río Miera, y ascensión a pie hacia el Portillo de Lunada.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39098','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles rurales en palacios barrocos con grandes fincas arboladas, posadas de turismo rural con solanas. Entorno y actividades: Valle de Carriedo (Valles Pasiegos). Rutas de senderismo suave entre praderías siempre verdes delimitadas por muros de piedra seca (muga), paseos de interpretación botánica junto al río Pisueña y cicloturismo de carretera.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39032','rural','Oferta de turismo rural','Alojamientos rurales: Alojamientos rurales de alta montaña de piedra de sillería, casas rurales con hórreo y apartamentos de esquí. Entorno y actividades: Valle de Campoo y vertiente de Alto Campoo. Destaca por el Nacimiento del Río Ebro en Fontibre (surgencia boscosa espectacular), rutas de senderismo alpino al pico Tres Mares y laderas del macizo de Peña Labra.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39082','rural','Oferta de turismo rural','Alojamientos rurales: Casas de turismo rural familiares, posadas cántabras con escudos heráldicos y alojamientos de agroturismo ganadero. Entorno y actividades: Valle del Pisueña. Rutas de senderismo hacia el alto de la Braguía, paseos por hayedos aislados, senderos de herradura de montaña y turismo gastronómico-rural enfocado en la elaboración de quesos y sobaos.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90245','rural','Oferta de turismo rural','Alojamientos rurales: Palacetes rurales de indianos, posadas tradicionales montañesas dentro de pequeños valles cerrados. Entorno y actividades: Parque Natural Saja-Besaya. Senderismo por la canal de las Tejeras, rutas botánicas por el monte de Obios, paseos de interpretación fluvial junto al río Los Llares y senderos micológicos de otoño.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90243','rural','Oferta de turismo rural','Alojamientos rurales: Apartamentos rurales con huerto y barbacoa, casas de piedra de labranza tradicionales de la cuenca oriental. Entorno y actividades: Comarca del Asón. Destaca por la pesca del salmón y trucha en el río Asón, rutas de senderismo hacia el Santuario de la Bien Aparecida, piragüismo fluvial y paseos por bosques de ribera.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39045','rural','Oferta de turismo rural','Alojamientos rurales: Apartamentos rústicos en antiguas escuelas de piedra rehabilitadas, casas de turismo rural con chimenea. Entorno y actividades: Valle alto del Miera. Destaca por las rutas de senderismo kárstico entre lapiaces calcáreos gigantes, paseos a la Cueva del Salitre, senderos fluviales de ribera y observación de geología pura.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39039','rural','Oferta de turismo rural','Alojamientos rurales: Cabañas pasiegas de montaña aisladas rodeadas de bosque autóctono, hostales rurales sencillos. Entorno y actividades: Valle del río Luena, vertiente del Puerto del Escudo. Rutas de senderismo exigente hacia el embalse del Mediajo, caminatas por los hayedos de la Magdalena, senderos ganaderos de alta montaña y avistamiento de aves rapaces.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39058','rural','Oferta de turismo rural','Alojamientos rurales: Posadas rústicas acogedoras de interior, casas rurales con grandes fincas verdes para familias. Entorno y actividades: Valle del Asón-Gándara. Cuenta con el Parque de la Cueva del Valle (surgencia de río subterráneo gigante). Rutas de senderismo geológico, vías ferratas, senderos botánicos de encinares cantábricos e itinerarios mineros abandonados.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90636','rural','Oferta de turismo rural','Alojamientos rurales: Apartamentos rústicos orientados a montañeros y espeleólogos, casas de piedra de montaña unifamiliares. Entorno y actividades: Conocido como "La capital del mundo" de la espeleología por la cantidad de simas del macizo de peña Lavalle. Rutas de senderismo al nacimiento del río Asón por el sendero bajo, y escalada clásica.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39020','rural','Oferta de turismo rural','Alojamientos rurales: Apartamentos rurales en pedanías del interior, chalets rústicos reformados rodeados de eucaliptales. Entorno y actividades: Litoral extremo oriental. Rutas por la Senda Real del antiguo ferrocarril minero de Alén, senderismo por los acantilados de Mioño y playas salvajes de cantos rodados como Sonabia (avistamiento de buitres de costa).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39086','rural','Oferta de turismo rural','Alojamientos rurales: Alojamientos rurales integrados en conjuntos de arquitectura tradicional cántabra pura, casas de piedra con techos de roble. Entorno y actividades: Valle de Cabuérniga alto (incluye Correpoco y El Tojo). Rutas de senderismo directo bajo los bosques del Parque de Saja-Besaya, paseos micológicos y accesos a brañas ganaderas altas de montaña.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39088','rural','Oferta de turismo rural','Alojamientos rurales: Casas de aldea tradicionales de alta montaña de piedra caliza compacta y tejado de teja curva. Entorno y actividades: Municipio más aislado de Cantabria, colgado a 900 metros sobre el río Deva dentro de los Picos de Europa. Espectacular y exigente ruta senderista de la Subida a Tresviso (zig-zag por desfiladero calizo), senderos pastoriles y queserías de montaña.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39036','rural','Oferta de turismo rural','Alojamientos rurales: Posadas singulares en un hermoso valle verde cerrado, casas rurales rodeadas de frutales y eucaliptos. Entorno y actividades: Valle ciego costero único (Poljé de Liendo). Rutas de senderismo que conectan con la recóndita Playa de San Julián, paseos hacia el Monte Candina (única colonia europea de buitres leonados que anida frente al mar Cantábrico).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39033','rural','Oferta de turismo rural','Alojamientos rurales: Casonas de piedra tradicionales restauradas, posadas rurales rurales junto al río Nansa. Entorno y actividades: Valle del Nansa. Rutas de senderismo por la Senda Fluvial del Nansa, caminatas hacia la Cueva de El Soplao, bosques de robles y castaños, y miradores de montaña hacia los Picos de Europa orientales.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39102','rural','Oferta de turismo rural','Alojamientos rurales: Casas de labranza trasmeranas aisladas, apartamentos rurales familiares con jardín y frutales. Entorno y actividades: Junta de Voto, cuenca de la ría de Treto. Rutas de senderismo por el Valle de Aras, paseos micológicos, senderos botánicos de encinares en zonas calizas rústicas y observación de aves en marismas interiores.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39094','rural','Oferta de turismo rural','Alojamientos rurales: Alojamientos rurales integrados en antiguas casas de piedra castellana con patio, posadas de interior rústicas. Entorno y actividades: Extremo sur de Cantabria, cañón del Alto Ebro. Posee un patrimonio único de iglesias rupestres excavadas en la roca arenisca. Rutas de senderismo por la Hoz del Ebro, senderos botánicos entre robles rebollos y cascadas fluviales.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39090','rural','Oferta de turismo rural','Alojamientos rurales: Apartamentos rurales pequeños y posadas sencillas integradas en barrios agrícolas verdes y tranquilos. Entorno y actividades: Cerca de Comillas. Destaca por las rutas de senderismo histórico por los antiguos pozos mineros calizos de Udías, caminatas por el hayedo de Monte Cobandón y senderos agrícolas vecinales.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39041','rural','Oferta de turismo rural','Alojamientos rurales: Casonas montañesas cuidadas de piedra, posadas literarias tradicionales rodeadas de floridos jardines rústicos. Entorno y actividades: Valle del Saja bajo. Rutas de senderismo por la Senda de los Molinos, paseos llanos fluviales a orillas del río Saja, cicloturismo de carretera familiar entre pueblos con arquitectura protegida y robledales.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39056','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles de campo y posadas reales articulados en torno al turismo balneario y de río, apartamentos rurales. Entorno y actividades: Valle del Pas medio. Destaca por las rutas de senderismo de ascensión al Monte Castillo (visita a cuevas prehistóricas patrimonio mundial), la Vía Verde del Pas para cicloturismo y pesca de salmón en pozos fluviales.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39063','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales de montaña unifamiliares con muros anchos de piedra caliza, apartamentos rústicos pequeños. Entorno y actividades: Valle del Nansa alto. Punto de acceso directo a la Cueva de El Soplao (joya geológica mundial por sus formaciones excéntricas). Rutas por el desfiladero de la Hermida meridional, y senderos pastoriles de montaña.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39028','rural','Oferta de turismo rural','Alojamientos rurales: Posadas rurales de la comarca de Trasmiera, apartamentos integrados en antiguas moles molineras de río. Entorno y actividades: Ofrece la ruta de senderismo del Nacimiento del Río Aguanaz (bello entorno boscoso kárstico), paseos entre encinares sobre rocas calizas y senderos agrícolas llanos aptos para cicloturismo familiar.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39050','rural','Oferta de turismo rural','Alojamientos rurales: Apartamentos rurales de alta montaña de Liébana, casas de aldea tradicionales rodeadas de avellanos y castaños. Entorno y actividades: Valle de Valdeprado (sur de Liébana). Rutas de senderismo hacia el Puerto de Piedrasluengas (mirador espectacular hacia la Cordillera Cantábrica), bosques autóctonos de hayas y robles, y territorio del oso pardo.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39030','rural','Oferta de turismo rural','Alojamientos rurales: Casonas de labranza orientales, apartamentos rurales rodeados de densos bosques forestales de interior. Entorno y actividades: Valle del río Agüera. Destaca por las rutas de senderismo hacia el Embalse de el Juncal bajo el macizo de las Nieves, paseos de interpretación fluvial, y senderos rodeados de robles y plantaciones forestales.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39084','rural','Oferta de turismo rural','Alojamientos rurales: Posadas trasmeranas rurales con amplias praderías para familias, apartamentos rústicos de interior. Entorno y actividades: Valles interiores de Trasmiera. Caminatas tranquilas de baja dificultad por el valle del río Campiazo, senderos vecinales entre dehesas praderas y colinas boscosas de eucaliptos y encinas.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39026','rural','Oferta de turismo rural','Alojamientos rurales: Palacios de indianos rústicos con jardines vallados, posadas de turismo rural junto a ríos. Entorno y actividades: Valle de Toranzo (río Pas). Rutas de senderismo de los antiguos bosques flotantes, paseos fluviales entre plátanos de sombra centenarios, cicloturismo de carretera y rutas micológicas otoñales.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90244','rural','Oferta de turismo rural','Alojamientos rurales: Casas de aldea rústicas independientes en pequeños pueblos rurales compactos de montaña. Entorno y actividades: Centro geográfico de Cantabria. Rutas de senderismo por la Senda de los Mitológicos (figuras de la mitología cántabra talladas en madera en el bosque), senderos pastoriles hacia el monte Espina y valles ganaderos.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39070','rural','Oferta de turismo rural','Alojamientos rurales: Casas de montaña tradicionales de mampostería gruesa y chimenea central rústica. Entorno y actividades: Entorno alto de los embalses de Mediajo y Alsa. Rutas de senderismo por bosques de hayas bien conservados en las laderas de los valles interiores, senderos ganaderos de altura y avistamiento de aves de montaña. PROVINCIA: MADRID (Texto Plano Limpio).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28120','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles boutique de alta montaña, antiguas casas de postas restauradas y chalets de madera y piedra caliza. Entorno y actividades: Ubicado en el corazón del Parque Nacional de Guadarrama y el Valle del Lozoya. Destaca por las rutas de senderismo a las Cascadas del Purgatorio, los paseos por el Bosque de Finlandia, el disfrute de las piscinas naturales de Las Presillas y rutas de raquetas de nieve hacia el Macizo de Peñalara.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28038','rural','Oferta de turismo rural','Alojamientos rurales: Hostales históricos de montaña para senderistas, chalets de piedra tradicionales guadarramistas y albergues de naturaleza integrados en el pinar. Entorno y actividades: Eje del Valle de la Fuenfría. Ofrece rutas por la Calzada Romana mejor conservada de la región, senderismo vertical hacia los Siete Picos y la Peñota, zonas recreativas de Las Dehesas con piscinas integradas en el río y rutas micológicas otoñales.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28131','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles señoriales decimonónicos de fachada histórica, fincas rurales exclusivas a las faldas del monte y casonas de piedra. Entorno y actividades: Entorno natural protegido del Monte Abantos y el Bosque de La Herrería. Rutas de senderismo botánico hacia el Arboreto Luis Ceballos, caminatas históricas a la Silla de Felipe II bajo castaños milenarios y ascensiones alpinas a los altos de Abantos.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28107','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles rurales exclusivos de arquitectura de pizarra negra, apartamentos íntimos rehabilitados para escapadas de descanso. Entorno y actividades: Máximo exponente de la Arquitectura Negra en Madrid, al pie de la Sierra Norte. Ofrece rutas de senderismo geológico por los barrancos calizos del arroyo de Patones, sendas hacia el Pontón de la Oliva (epicentro de la escalada en roca de la región) y cuevas kársticas protegidas.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28082','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles de montaña de carácter familiar, apartamentos optimizados para escaladores y hostales rurales tradicionales. Entorno y actividades: Entrada principal al Parque Nacional de Guadarrama por el laberinto granítico de La Pedriza. Destaca por el senderismo vertical entre riscos como El Yelmo, rutas fluviales siguiendo el río Manzanares joven, paseos ornitológicos por el Embalse de Santillana y rutas a caballo.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28027','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales intramuros de mampostería antigua, apartamentos rústicos con vistas al río y posadas con encanto medieval. Entorno y actividades: Rodeado por el meandro del río Lozoya en la Sierra Norte. Ofrece la gran ruta de senderismo de la Senda del Genaro (GR-300), piragüismo, kayak y paddle surf fluvial en sus aguas calmadas, y cicloturismo de montaña por los pinares linderos.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28085','rural','Oferta de turismo rural','Alojamientos rurales: Casonas burguesas de veraneo del siglo XIX reconvertidas en hoteles rurales, casas de campo con jardín e hilos de agua naturales. Entorno y actividades: Ubicado entre el Puerto de la Morcuera y el Puerto de Canencia. Destaca por las rutas al abedular de Canencia (bosque de reliquia glaciar con cascadas), senderos entre robledales centenarios, recolección de setas en temporada y rutas ciclistas de carretera de gran exigencia.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28093','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles de alta montaña clásicos con instalaciones de bienestar (spa), villas de piedra exclusivas y alojamientos rústicos de puerto. Entorno y actividades: Entorno alpino del Sistema Central. Rutas de senderismo por el Valle de la Barranca (senderos rodeados de inmensos pinos silvestres), ascensiones a la Bola del Mundo, rutas invernales con raquetas de nieve y actividades deportivas de montaña alta.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28021','rural','Oferta de turismo rural','Alojamientos rurales: Casas de piedra de grano tradicional, apartamentos de turismo rural familiares con huerto y corrales recuperados. Entorno y actividades: Asentado en la ribera del Embalse de El Atazar. Rutas de senderismo náutico costero de interior, paseos geológicos interpretativos entre formaciones de granito y pizarras, senderos cicloturistas y miradores paisajísticos del macizo del Atazar.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28133','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles enológicos integrados en bodegas de montaña, casas de campo independientes rodeadas de viñedos viejos. Entorno y actividades: Suroeste de Madrid, entorno del Embalse de San Juan. Rutas de senderismo bajo pinares piñoneros y encinares rústicos, deportes náuticos en playas continentales con bandera azul, senderos hacia las ruinas del Castillo de la Coracera y visitas a formaciones de jardín botánico.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28109','rural','Oferta de turismo rural','Alojamientos rurales: Chalets rurales de alquiler íntegro con grandes parcelas forestales, apartamentos rústicos de pinar con piscina. Entorno y actividades: Cuenca del río Alberche. Ofrece senderos de baja montaña que conectan con el Monasterio de Santa María de Valdeiglesias, rutas de piragüismo de río, escalada en bloques de granito menores y cicloturismo de montaña por dehesas.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28039','rural','Oferta de turismo rural','Alojamientos rurales: Apartamentos y casas rurales orientadas al deportista náutico y de aventura, casas tradicionales de pescadores de embalse. Entorno y actividades: Estación náutica del Embalse de El Atazar. Práctica de vela, windsurf, kayak de travesía y paddle surf. Rutas a pie que bordean los entrantes de agua en la montaña y senderos de media montaña por canchales de pizarra.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28159','rural','Oferta de turismo rural','Alojamientos rurales: Casas de pueblo rústicas de construcción tradicional en piedra vista, complejos de cabañas de pinar protegidas. Entorno y actividades: Zona ZEPA (Protección de Aves) de la Sierra Oeste. Espectaculares rutas fluviales del río Cofio cruzando el histórico Puente Mocho, senderismo entre bosques de pino piñonero virgen y avistamiento de buitre negro y águila imperial.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28028','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales unifamiliares con chimenea, alojamientos ecosostenibles de diseño bioclimático integrados en prados. Entorno y actividades: Valle de Bustarviejo, faldas del pico de El Pendón. Rutas de senderismo e interpretación histórica hacia la antigua mina de plata de la localidad, caminos tradicionales ganaderos, escalada en roca de media montaña y senderos micológicos de robledal.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28071','rural','Oferta de turismo rural','Alojamientos rurales: Alojamientos de turismo rural fielmente restaurados con piedra volcánica, vigas de roble vistas y cubiertas de pizarra negra. Entorno y actividades: Integrado en la Reserva de la Biosfera de la Sierra del Rincón. Senderismo de alta protección ecológica entre bosques mixtos, paseos etnográficos urbanos que mantienen la fisonomía serrana intacta del siglo XVII y rutas de fuentes de montaña.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28118','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales de aislamiento total en un valle profundo de montaña, antiguos pajares rehabilitados en mampostería oscura. Entorno y actividades: Entorno aislado del Valle de los Sueños (ruta senderista artística que fusiona esculturas de autores contemporáneos al aire libre con el entorno serrano), senderos que suben a cumbres de más de 1800 metros y densos robledales.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28088','rural','Oferta de turismo rural','Alojamientos rurales: Posadas rurales tradicionales de la Sierra Norte, casas de aldea unifamiliares con corredores rústicos. Entorno y actividades: Custodia el Hayedo de Montejo (Patrimonio de la Humanidad por la UNESCO). Rutas senderistas de acceso controlado y guiado por las riberas del río Jarama bajo hayas centenarios, senderos de herradura de montaña y turismo micológico.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28030','rural','Oferta de turismo rural','Alojamientos rurales: Casas de piedra berroqueña, chalets rústicos de montaña independientes y apartamentos turísticos de escalada. Entorno y actividades: Macizo granítico de la Sierra de La Cabrera. Ofrece rutas de escalada clásica de primer nivel en el Pico de la Miel, senderismo hacia el antiguo Convento de San Antonio (románico rodeado de naturaleza), y paseos entre canchales de piedra tallada por la erosión.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28052','rural','Oferta de turismo rural','Alojamientos rurales: Posadas históricas castellanas estructuradas en torno a patios de columnas de madera, parador nacional en convento del siglo XVII. Entorno y actividades: Turismo rural de vega e interior meridional. Senderismo entre extensos olivares centenarios y viñedos, rutas llanas que siguen las vegas agrícolas de los ríos Tajuña y Jarama, y cercanía al entorno palustre protegido de las Lagunas de San Juan.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28076','rural','Oferta de turismo rural','Alojamientos rurales: Apartamentos rústicos con chimenea de leña, cabañas de madera de montaña y casas rurales unifamiliares. Entorno y actividades: Ribera del Embalse de Pinilla. Rutas de senderismo que bordean el lago de interior, caminatas hacia los sabinares y robledales de la vertiente norte, cicloturismo de montaña por pistas forestales que ganan altura hacia los puertos linderos.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90066','rural','Oferta de turismo rural','Alojamientos rurales: Casas de labranza tradicionales del Valle del Lozoya adaptadas para alquiler íntegro con chimenea y pequeños huertos. Entorno y actividades: Valle Alto del Lozoya. Rutas de senderismo plano de baja dificultad a lo largo del corredor del río, caminatas de interpretación botánica por las alamedas y praderías ganaderas, y senderos micológicos en sus zonas boscosas.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28034','rural','Oferta de turismo rural','Alojamientos rurales: Casas de piedra tradicionales de montaña con muros gruesos aislantes, apartamentos rústicos pequeños. Entorno y actividades: Falda norte del Puerto de Canencia. Destaca por sus puentes medievales de piedra (Puente Canto), rutas senderistas hacia cascadas ocultas (Chorrera de Mojonavalle) y senderos botánicos rodeados de pinos e hileras de tejos singulares.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28112','rural','Oferta de turismo rural','Alojamientos rurales: Casas de piedra y madera tradicionales del valle pirenaico-madrileño, apartamentos turísticos de naturaleza. Entorno y actividades: Valle del Lozoya. Entorno del parque arqueológico del Valle de los Neandertales. Rutas de senderismo suave junto al embalse, senderos botánicos fluviales entre sauces y chopos, y paseos fotográficos de naturaleza invernal.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28125','rural','Oferta de turismo rural','Alojamientos rurales: Casas de campo con fincas amplias integradas en zonas de monte bajo, chalets rústicos tradicionales con chimenea. Entorno y actividades: Transición de la Sierra de Guadarrama a la Sierra Oeste. Rutas de senderismo hacia el Monte de la Almenara, caminatas de observación de avifauna (zonas protegidas de águila perdicera), y senderos llanos aptos para cicloturismo familiar entre pinares.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28031','rural','Oferta de turismo rural','Alojamientos rurales: Casas de campo rústicas unifamiliares, alojamientos rurales boutique vinculados al enoturismo de la Sierra Oeste. Entorno y actividades: Paisaje granítico peculiar de la Peña Muñana. Rutas de senderismo arqueológico e histórico entre tumbas antropomorfas, caminatas por pinares y encinares viejos, y rutas cicloturistas entre campos de cepas de vid de uva garnacha.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28099','rural','Oferta de turismo rural','Alojamientos rurales: Fincas agrarias y casas rurales de campo aisladas en zonas adehesadas bajas, apartamentos tradicionales sencillos. Entorno y actividades: Entorno del embalse de Picadas y del río Alberche. Rutas de senderismo de la Vía Verde del río Alberche (antiguo trazado ferroviario plano ideal para familias y cicloturismo de paseo), encinares compactos y observación de grandes rapaces de bosque.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28043','rural','Oferta de turismo rural','Alojamientos rurales: Casas de labranza castellanas tradicionales con tinajas de piedra gigantescas en patios interiores rústicos. Entorno y actividades: Comarca de Las Vegas. Rutas que conectan con la Vía Verde del Tajuña para caminantes y ciclistas, senderos que bajan hacia las canteras históricas de piedra caliza blanca de Colmenar y paseos fotográficos entre campos llanos cerealistas y vides. PROVINCIA: HUESCA (Texto Plano Limpio).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22230','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles de montaña de piedra y madera, antiguas bordas ganaderas reconvertidas en viviendas turísticas rústicas y albergues pirenaicos. Entorno y actividades: Puerta de acceso principal al Parque Nacional de Ordesa y Monte Perdido (Patrimonio de la Humanidad). Destaca por la emblemática ruta de senderismo a la cascada de la Cola de Caballo, las Gradas de Soaso, las ascensiones de alta montaña, el barranquismo en el valle de Bujaruelo y las rutas de raquetas de nieve.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23001','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales de piedra medieval rehabilitada, hoteles boutique en el casco histórico amurallado y apartamentos rurales con huerto. Entorno y actividades: Confluencia de los ríos Cinca y Ara, en la Comarca del Sobrarbe. Sede mundial del ciclismo de montaña (Centro BTT Zona Zero). Ofrece rutas de senderismo hacia el Cañón de Añisclo, piragüismo y kayak en el Embalse de Mediano (con su famoso campanario sumergido) y senderos micológicos.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22054','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles de montaña premium con instalaciones de spa alpino, refugios de alta montaña, apartamentos rústicos e históricos palacios aragoneses rehabilitados. Entorno y actividades: Corazón del Parque Natural de Posets-Maladeta. Punto de partida para la ascensión al Pico Aneto (techo de los Pirineos) y al Posets. Destaca por el senderismo al Forau de Aigualluts (espectacular sumidero kárstico), esquí de fondo en los Llanos de Hospital y escalada clásica.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90272','rural','Oferta de turismo rural','Alojamientos rurales: Casas de turismo rural empotradas en callejones de trazado islámico, hostales con encanto rústico y alojamientos especializados en deportes de aventura. Entorno y actividades: Ubicado en el Parque Natural de la Sierra y Cañones de Guara. Meca internacional del barranquismo y descenso de cañones. Destaca por la espectacular ruta de senderismo de las Pasarelas del Río Vero, la observación de aves rapaces calcícolas y el senderismo fotográfico entre olivares viejos.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22204','rural','Oferta de turismo rural','Alojamientos rurales: Chalets de montaña independientes, apartamentos rústicos a pie de pista invernal y hoteles pirenaicos con chimenea. Entorno y actividades: Cabecera del Valle de Tena, bajo la imponente Peña Foratata. Rutas de senderismo de alta dificultad hacia los ibones (lagos glaciares) de Anayet y Respomuso, paseos náuticos en el Embalse de Lanuza, deportes de nieve en FormigalPanticosa y senderos transfronterizos.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22170','rural','Oferta de turismo rural','Alojamientos rurales: Grandes hoteles balneario de montaña decimonónicos, apartamentos de turismo alpino y casas rurales tradicionales pirenaicas. Entorno y actividades: Entorno del Balneario de Panticosa a 1.630 metros de altitud. Destaca por la vertiginosa ruta de senderismo de las Pasarelas de Panticosa sobre el río Caldarés, excursiones de montaña hacia el Ibón de Baños, esquí alpino y escalada en vías ferratas calizas.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22057','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales de piedra maciza y pizarra, parador de turismo de montaña en el valle, y albergues para excursionistas. Entorno y actividades: Acceso directo al Valle de Pineta dentro del Parque Nacional de Ordesa. Ofrece las rutas de senderismo de ascensión al Balcón de Pineta y al Lago de Marboré, caminatas bajo cascadas espectaculares, senderos forestales alpinos y conexión a Francia mediante túnel.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22069','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales familiares integradas en el núcleo del pueblo, apartamentos rústicos con vistas fluviales y posadas pirenaicas. Entorno y actividades: Bañado por el río Ara (único gran río virgen sin presas del Pirineo). Ofrece la espectacular ruta de la Cascada de Sorrosal, su famosa vía ferrata vertical apta para escaladores, senderismo por el Valle de Ordesa meridional y rafting fluvial en aguas bravas.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22059','rural','Oferta de turismo rural','Alojamientos rurales: Casonas infanzonas de sillería convertidas en hoteles rurales, complejos de apartamentos rústicos con jardín y casas de pueblo de alquiler íntegro. Entorno y actividades: Nudo estratégico entre el Valle de Tena y el Serrablo. Rutas de senderismo hacia el recóndito Ermita de Santa Elena en un estrecho desfiladero, parques de aventura forestal en tirolinas, cicloturismo de carretera y senderos de interpretación botánica.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22028','rural','Oferta de turismo rural','Alojamientos rurales: Casas de turismo rural con una de las arquitecturas de piedra mejor conservadas del Pirineo, alojamientos con suelos de losa tradicional. Entorno y actividades: Parque Natural de los Valles Occidentales. Destaca por la ruta senderista del Valle de Zuriza, caminatas de alta montaña en el entorno kárstico de Linza, senderos botánicos entre abetales salvajes y territorio histórico de los últimos osos autóctonos.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22130','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles rurales en las pedanías y pueblos rurales de su término, apartamentos de montaña tradicionales y pensiones para peregrinos. Entorno y actividades: Valle del Aragón y pie de monte del Pirineo. Camino de Santiago Aragonés. Ofrece senderismo de ascensión a la Peña Oroel (símbolo del valle), rutas geológicas integradas, cicloturismo de montaña por los antiguos caminos tradicionales y turismo de nieve cercano en Astún y Candanchú.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22117','rural','Oferta de turismo rural','Alojamientos rurales: Palacetes rurales aragoneses con patios porticados rústicos, casas rurales familiares independientes de interior y apartamentos en el casco histórico de la Ribagorza. Entorno y actividades: Confluencia de los ríos Ésera e Isábena. Rutas de senderismo por los espectaculares estrechos del Congost de Olvena, caminatas hacia los lapiaces de la Sierra de la Puebla, dehesas y senderos micológicos en otoño, piragüismo, vela y deportes de remo en el Embalse de Barasona, y rutas cicloturistas de media montaña.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22066','rural','Oferta de turismo rural','Alojamientos rurales: Hotel rural de lujo en un antiguo monasterio rehabilitado del siglo XVII, casas de turismo rural de mampostería antigua a la sombra del castillo y apartamentos rústicos de cara al río Ara. Entorno y actividades: Valle del río Ara medio, en la comarca del Sobrarbe. Destaca por las pozas naturales de La Gorga de Boltaña (ideales para el baño estival en aguas limpias de montaña), rutas senderistas que exploran los pueblos abandonados del viejo Sobrarbe y el pirineo meridional, y senderos micológicos otoñales.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22078','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles históricos vinculados a la majestuosa estación internacional ferroviaria, apartamentos de montaña e instalaciones rústicas pirenaicas con estufas de leña. Entorno y actividades: Valle del Aragón alto, frontera con Francia y paso del Camino de Santiago Aragonés. Rutas de senderismo alpino de alta exigencia hacia el espectacular Ibón de Estanés, paseos de interpretación histórica por los búnkeres de la Línea P ocultos bajo los pinares silvestres, raquetas de nieve invernales y esquí en Astún y Candanchú.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22084','rural','Oferta de turismo rural','Alojamientos rurales: Apartamentos rústicos orientados al deportista de montaña y aventura, y casas de piedra tradicionales con balcones volados sobre el valle del Ésera. Entorno y actividades: Valle de Benasque bajo. Capital nacional de los deportes de vuelo libre (parapente y ala delta) por sus corrientes térmicas. Rutas de senderismo por el Congosto de Ventamillo, senderos cicloturistas de montaña de descenso extremo (Enduro BTT), rafting y piragüismo fluvial de aguas bravas en el río Ésera, y senderos micológicos.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22182','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales tradicionales chistabinas de aislamiento de montaña con tejados empinados de pizarra, pequeñas bordas ganaderas independientes y apartamentos rústicos con chimenea. Entorno y actividades: Valle de Gistaín (Chistau), uno de los valles más puros y resguardados del Pirineo Aragonés. Rutas senderistas de alta montaña hacia el Ibón de Plan (o Basa de la Mora, espectacular lago glaciar legendario rodeado de colosales acantilados calizos verticales), senderos pastoriles de dehesas altas, caminatas micológicas y observación astronómica Starlight.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22149','rural','Oferta de turismo rural','Alojamientos rurales: Casas de labranza tradicionales de la Hoya de Huesca, apartamentos rústicos pequeños con vistas a las llanuras de la dehesa baja y posadas. Entorno y actividades: Faldas de la Sierra de Loarre. Destaca por las rutas de senderismo de corte medieval que rodean el colosal Castillo de Loarre (la fortaleza románica mejor conservada de Europa), senderos micológicos entre pinares silvestres de repoblación viejos, caminatas geológicas en los riscos y observación de aves rapaces.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50185','rural','Oferta de turismo rural','Alojamientos rurales: Casas de turismo rural orientadas al turismo activo, centros de ecoturismo rural y apartamentos rústicos al pie de la roca caliza. Entorno y actividades: Al pie de los impresionantes Mallos de Riglos. El mayor hub de aguas bravas y turismo de aventura de Huesca occidental; destaca por el rafting, hidrospeed y kayak fluvial en el río Gállego. Rutas de senderismo vertical que rodean los mallos calizos caliciformes, escalada en vía ferrata y avistamiento de buitres.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22144','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales tradicionales con hileras de piedra caliza dorada, apartamentos rústicos adaptados con balcones sobre el valle del río Cinca. Entorno y actividades: Falda de la mítica peña de Monte Perdido meridional. Famoso por mantener la tradición etnográfica de las nabatas (antiguas almadías de transporte de madera por el río). Rutas de senderismo de media montaña, caminatas por el fondo del valle boscoso y senderos micológicos de pinar y encinar mixtos.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22227','rural','Oferta de turismo rural','Alojamientos rurales: Pequeñas casas de aldea pirenaicas aisladas de la civilización urbana, y apartamentos rústicos de alta montaña con chimeneas de piedra. Entorno y actividades: Municipio colgado sobre riscos calizos del Sobrarbe alto. Destaca por la legendaria Ruta de las Ermitas de Tella (tres pequeños templos colgados sobre el vacío en un entorno de dehesas mágicas y misterios de brujería), senderos que ascienden a la Cueva del Oso de las Cavernas y caminatas por cañones calizos.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22200','rural','Oferta de turismo rural','Alojamientos rurales: Casas de piedra tradicionales de mampostería pirenaica compacta con cubiertas inclinadas de pizarra, y apartamentos rústicos de montaña. Entorno y actividades: Valle de Benasque medio. Acceso directo al espectacular Valle de Estós. Rutas senderistas de alta montaña que cruzan prados alpinos altos repletos de ganado, senderos que ascienden hacia el Ibón de Batisielles, caminatas micológicas y cascadas de deshielo de invierno. PROVINCIA: ALMERÍA (Texto Plano Limpio).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22109','rural','Oferta de turismo rural','Alojamientos rurales: Casas infanzonas rurales de piedra con grandes arcos de entrada, apartamentos rústicos a orillas del río. Entorno y actividades: Valle del Ara medio. Senderismo tranquilo y familiar por las riberas del Ara, rutas cicloturistas de montaña que exploran los pueblos de la Solana despoblada y caminos antiguos forestales de pinos y quejigos.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22114','rural','Oferta de turismo rural','Alojamientos rurales: Casas de turismo rural típicas chistabinas con techados inclinados de pizarra, bordas tradicionales aisladas. Entorno y actividades: El municipio más alto del Valle de Chistau. Rutas senderistas exigentes de alta montaña hacia los picos fronterizos con Francia (Culfreda y Bachimala), paseos tradicionales entre campos de pasto alpino alto y turismo botánico de montaña.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22223','rural','Oferta de turismo rural','Alojamientos rurales: Alojamientos rústicos tranquilos de mampostería de río, pequeños apartamentos rurales de valle. Entorno y actividades: Valle del río Noguera Ribagorzana. Destaca por la ruta senderista que rodea el espectacular Monasterio de Santa María de Alaón (románico enclavado entre paredes calizas), senderos fluviales por el desfiladero de Escales y escalada de pared.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22074','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales de piedra tradicionales del prepirineo, hostales rurales especializados en turismo activo. Entorno y actividades: Al pie del colosal macizo del Turbón. Rutas de senderismo hacia las laderas mágicas del Turbón, paseos etnográficos fluviales en el río Ésera bajo cañones estrechos, y punto intermedio para el rafting alpino.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22107','rural','Oferta de turismo rural','Alojamientos rurales: Pequeñas bordas de alta montaña aisladas, casas de turismo rural construidas con piedra gruesa oscura. Entorno y actividades: Valle de Vió, uno de los accesos altos al Cañón de Añisclo de Ordesa. Rutas de senderismo espectaculares por los miradores superiores de Ordesa, caminatas boscosas por el Hayedo de la Pardina del Señor (uno de los hayedos otoñales más fotogénicos del Pirineo) y raquetas.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22048','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles y casas de turismo de interior vinculados al enoturismo del Somontano de Huesca, fincas de campo. Entorno y actividades: Comarca del Somontano. Rutas de senderismo suave que conectan con los senderos fluviales del río Vero bajo, paseos cicloturistas llanos entre viñedos, turismo gastronómico de naturaleza y rutas de observación de geología pre-pirenaica.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22214','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales rehabilitadas con patios castellano-aragoneses, pequeños alojamientos con encanto rústico de olivares. Entorno y actividades: Entorno de las sierras de la Ribagorza. Rutas de senderismo hacia el Santuario de Torreciudad, caminatas que miran al cañón del río Cinca, paseos entre campos de viñedos viejos de altura y senderos de olivares.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22157','rural','Oferta de turismo rural','Alojamientos rurales: Casas tradicionales de labranza ribagorzana de alta montaña con chimeneas cónicas, apartamentos rústicos. Entorno y actividades: Valle de Barrabés, lindando con Cataluña. Rutas de senderismo de alta montaña que acceden a los ibones de Angliós, senderos ganaderos que suben a prados de altura bajo cumbres alpinas y rutas de raquetas de nieve invernales.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22122','rural','Oferta de turismo rural','Alojamientos rurales: Apartamentos turísticos de montaña colgados literalmente sobre riscos calizos del Valle de Tena. Entorno y actividades: Cuenta con el mirador colgado sobre el Embalse de Búbal y la tirolina doble más larga de Europa sobre un lago. Rutas de senderismo a los ibones del valle, senderos boscosos de pinos y cicloturismo exigente de puertos.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22035','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales de piedra tradicionales del extremo oriental de la provincia, apartamentos rústicos sencillos. Entorno y actividades: Destaca por las rutas de senderismo arqueológico y paleontológico (yacimientos con huellas reales de dinosaurios y dólmenes prehistóricos), caminatas por canchales calizos y valles de matorral mediterráneo de interior.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22067','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles de naturaleza e interior construidos bajo criterios bioclimáticos de madera y piedra, casas rurales íntimas. Entorno y actividades: Bosque de Bonansa. Espectaculares rutas de senderismo adaptado y accesible bajo densos y mágicos bosques de robles y pinos silvestres, caminatas hacia la ermita de San Roque y rutas de observación astronómica de cielos negros.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90750','rural','Oferta de turismo rural','Alojamientos rurales: Casas de piedra tradicionales del Sobrarbe meridional con bodegas subterráneas, alojamientos rurales pequeños. Entorno y actividades: Entrada al Sobrarbe alto. Rutas de senderismo histórico que rodean su torre fortificada del siglo XI, caminatas hacia los estrechos del río Cinca y el Embalse de El Grado, ornitología y paseos botánicos rústicos.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22188','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales de paso tradicionales de piedra caliza de río, albergues de excursionistas. Entorno y actividades: Nudo de acceso principal al colosal Congost de Mont-rebei. Rutas de senderismo vertical extremo cruzando pasarelas excavadas en acantilados de roca sobre el río Noguera Ribagorzana, rutas de kayak fluvial de cañón y pasarelas colgadas. PROVINCIA: CÁDIZ (Texto Plano Limpio).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11019','rural','Oferta de turismo rural','Alojamientos rurales: Cortijos andaluces tradicionales de cal blanca y teja curva, hoteles de montaña rústicos con chimenea de leña y apartamentos integrados en el casco histórico de su pueblo blanco serrano. Entorno y actividades: En el corazón del Parque Natural Sierra de Grazalema (Reserva de la Biosfera). El municipio ostenta el índice pluviométrico más alto de la península ibérica. Destaca por la emblemática y protegida ruta de senderismo del Pinsapar (colosal bosque relicto de abetos de la era glaciar), la Senda de la Garganta Verde (un desfiladero vertical calizo brutal), ascensiones al pico El Torreón (techo de la provincia con 1.648 metros) y avistamiento de buitre leonado.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11035','rural','Oferta de turismo rural','Alojamientos rurales: Eco-lodges integrados en la dehesa, cortijos fortificados tradicionales, tiendas glamping safari de diseño y casas de campo costeras. Entorno y actividades: Confluencia del Parque Natural del Estrecho y Los Alcornocales. Destaca por las rutas de senderismo por los acantilados del Parque del Estrecho, avistamiento ornitológico masivo de aves migratorias, avistamiento de cetáceos en libertad, dunas salvajes de Bolonia y windsurf/kitesurf.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90739','rural','Oferta de turismo rural','Alojamientos rurales: Villas rurales con vistas panorámicas al lago, casas tradicionales encaladas de alquiler íntegro y fincas olivareras de agroturismo. Entorno y actividades: Falda de la Sierra de Líjar y bañado por el Embalse de Zahara-El Gastor. Ofrece senderismo costero de interior bordeando el embalse, deportes náuticos sin motor (kayak, paddle surf), la ruta de la Garganta Verde (cañón kárstico calizo gigantesco) y playas fluviales de interior en "Arroyomolinos".','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11034','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales cueva auténticas (viviendas integradas bajo un colosal saliente de roca natural), hostales rústicos de arquitectura singular. Entorno y actividades: Cañón fluvial del río Guadalporcún. Rutas de senderismo de los Bandoleros, paseos de interpretación geológica por los tajos de roca que cubren las calles del municipio, rutas cicloturistas entre campos de olivares y cañadas reales.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16006','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales integradas intramuros en el interior de un alcázar medieval fortificado, y fincas de montería rústicas. Entorno y actividades: Pleno Parque Natural de Los Alcornocales. Rutas de senderismo bajo la densa selva mediterránea de alcornoques y quejigos húmedos, senderos hacia el embalse de Guadarranque, observación de la "berrea" del ciervo y senderismo etnográfico por antiguos canutos (valles fluviales de reliquia subtropical).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90031','rural','Oferta de turismo rural','Alojamientos rurales: Haciendas agrícolas señoriales andaluzas, apartamentos rurales de costa rodeados de pinares y cortijos marineros. Entorno y actividades: Parque Natural de la Breña y Marismas del Barbate. Ofrece la ruta de senderismo del acantilado de la Breña (un recorrido sobre paredes verticales de más de 100 metros sobre el Atlántico), paseos por el pinar piñonero protegido, rutas en kayak por las marismas y ornitología costera.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11021','rural','Oferta de turismo rural','Alojamientos rurales: Casas de campo de piedra con grandes patios andaluces rústicos, antiguas casas de labranza rehabilitadas con chimenea de leña. Entorno y actividades: Parque Natural de Los Alcornocales. Destaca por el Sendero del Río Hozgarganta (último río virgen sin regular de Andalucía), caminatas bajo la fronda de los bosques de niebla locales, rutas micológicas enfocadas en el hongo "chantarela" y senderos ecuestres.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11039','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles boutique rurales en antiguas casas de vecinos fortificadas con patios de azulejos, fincas ecuestres y cortijos aislados. Entorno y actividades: Entorno de las marismas del río Barbate y colinas litorales. Rutas de senderismo suave por el núcleo de los molinos de agua de Santa Lucía (paraje natural con cascadas rústicas y acueducto romano), senderos ecuestres hacia playas vírgenes cercanas de El Palmar y cicloturismo de llanura.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11038','rural','Oferta de turismo rural','Alojamientos rurales: Casonas rurales amplias para grupos a las faldas de grandes farallones calcáreos, apartamentos turísticos de montaña. Entorno y actividades: Frontera natural entre Grazalema y Los Alcornocales. Rutas de senderismo por la histórica Calzada Romana de Ubrique a Benaocaz, senderos de escalada deportiva en las paredes rocosas de la Cruz del Tajo, y senderos micológicos de alcornocal.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16016','rural','Oferta de turismo rural','Alojamientos rurales: Grandes cortijos ganaderos y agrícolas con encanto andaluz, hoteles de naturaleza con fincas arboladas y picadero. Entorno y actividades: Centro geográfico de Los Alcornocales (Ruta del Toro). Destaca por la ruta del sendero de Valdeinfierno (con pasarelas adaptadas en un canuto subtropical denso), rutas de cicloturismo de montaña exigentes (BTT), kayak de interior en el embalse de Charco Redondo y observación de la berrea.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11024','rural','Oferta de turismo rural','Alojamientos rurales: Casas de pueblo andaluzas independientes vinculadas al agroturismo olivarero, apartamentos rústicos con porches de piedra caliza y posadas rurales a los pies de su imponente silueta fortificada y su iglesia neoclásica alta. Entorno y actividades: Comarca de la Sierra de Cádiz alta. El principal punto de inicio y nexo de la Vía Verde de la Sierra (antiguo trazado de tren acondicionado ideal para familias y cicloturistas). Ofrece la espectacular ruta de senderismo hacia el paraje natural del Peñón de Zaframagón (un colosal farallón de roca caliza cortado que alberga una de las mayores colonias de buitres leonados de Europa), paseos agrícolas y rutas ecuestres de dehesa. 📂 PROVINCIA: VALENCIA (Comunidad Valenciana - Datos Curados).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16001','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales rústicas, antiguos molinos de trigo rehabilitados junto a arroyos forestales y dehesas de ganado. Entorno y actividades: Parque Natural de Los Alcornocales alto. Destaca por las rutas de senderismo de ascensión al pico Aljibe (techo de la comarca con vistas de dos mares), paseos fluviales por el sendero de la Garganta de Puerto Oscuro y observación micológica de otoño.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11033','rural','Oferta de turismo rural','Alojamientos rurales: Villas exclusivas de campo e interior lindando con estuarios marinos, apartamentos rurales en pedanías forestales. Entorno y actividades: Estuario del río Guadiaro y Pinar del Rey. Rutas de senderismo familiar plano por el Pinar del Rey (bosque público maduro de pinos, alcornoques y acebuches con arroyos), paseos de avistamiento de aves acuáticas en las lagunas de Torreguadiaro y kayak fluvial de baja dificultad.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16008','rural','Oferta de turismo rural','Alojamientos rurales: Cortijillos costeros con huerto, chalets rurales de campo rodeados de pinares junto a la costa atlántica. Entorno y actividades: Entorno litoral de los Pinares de Roche. Espectaculares rutas de senderismo plano por los senderos de los acantilados de Roche y sus calas escondidas vírgenes, caminatas entre retamas protegidas y avistamiento costero de aves rapaces menores.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11023','rural','Oferta de turismo rural','Alojamientos rurales: Casas palacio señoriales rústicas con patios de arcadas de piedra, hostales rurales con encanto andaluz medieval. Entorno y actividades: Balcón de la Janda, elevación de campiña alta. Rutas que conectan con senderos de cañadas reales ganaderas, paseos fotográficos de naturaleza por el entorno adehesado del cuaternario donde pasta el toro bravo y dehesas de encinas viejas.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90470','rural','Oferta de turismo rural','Alojamientos rurales: Casas de labranza tradicionales de campiña con huerto mudéjar, apartamentos rústicos pequeños con vistas al embalse. Entorno y actividades: Bañado por el Embalse de Bornos (Paraje Natural Protegido). Destaca por la ruta del Sendero de la Ribera, avistamiento ornitológico de aves palustres y acuáticas (somormujos, garzas), rutas cicloturistas familiares llanas y kayak náutico.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90737','rural','Oferta de turismo rural','Alojamientos rurales: Complejos de cabañas y casas de piedra blanca rústica con techos de vigas de madera rústica de olivo, fincas de montaña. Entorno y actividades: Conocido como el Balcón de los Pueblos Blancos. Rutas de senderismo hacia el Dolmen del Gigante (megalito prehistórico espectacular integrado en la dehesa), caminatas de ascensión al pico Tajo de Algarín y senderos entre olivares de pendiente extrema.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16004','rural','Oferta de turismo rural','Alojamientos rurales: Parador nacional en palacio monumental, casas de turismo rural colgadas en el desfiladero calizo e históricas haciendas. Entorno y actividades: Asentado sobre una monumental peña caliza tallada por el río Guadalete. Rutas de senderismo que bordean el Paraje Natural de la Cola del Embalse de Arcos (ornitología de primer nivel de aves acuáticas), paseos en piragua por el río y senderos agrícolas de campiña.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11026','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales de pueblo tradicionales de interior, apartamentos rústicos acogedores y fincas rurales de colina con frutales. Entorno y actividades: Transición a la Sierra de Grazalema alta. Rutas de senderismo arqueológico hacia las ruinas de la ciudad romana de Iptuci, caminatas por colinas de monte bajo mediterráneo aromático (tomillo, romero) y rutas gastronómicorurales vinculadas a la apicultura tradicional (rutas de la miel).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16003','rural','Oferta de turismo rural','Alojamientos rurales: Casas de pueblo andaluzas de cal blanca adaptadas con patios interiores llenos de fuentes y limoneros, hostales rústicos. Entorno y actividades: Falda de la Sierra de Líjar. Capital andaluza del vuelo libre (parapente y ala delta) gracias a sus corrientes térmicas de montaña. Rutas de senderismo técnico que suben al macizo de la Sierra de Líjar por la canal, senderos forestales de acebuches y pinares, y rutas cicloturistas.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11040','rural','Oferta de turismo rural','Alojamientos rurales: Casas tradicionales de alta montaña caliza de la serranía, apartamentos rústicos con techos bajos y chimeneas de piedra. Entorno y actividades: Municipio más alto de la provincia de Cádiz (850 metros), encajonado en un poljé kárstico estrecho. Meca de la espeleología por albergar grandes simas de la región (Sima de Villaluenga). Rutas senderistas de montaña por los lapiaces calizos secos, rutas del queso payoyo y senderos pastoriles.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90738','rural','Oferta de turismo rural','Alojamientos rurales: Casas de labranza bajas de campiña cerealista tradicional, alojamientos rurales sencillos con patios andaluces. Entorno y actividades: Custodia la Reserva Natural de las Lagunas de Espera (Lagunas Hondilla, Salada y Dulce). Rutas de senderismo llano de observación ornitológica de aves palustres raras (malvasía cabeciblanca, focha cornuda), paseos rurales hacia las ruinas del Castillo de Fatetar y dehesas agrarias.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16007','rural','Oferta de turismo rural','Alojamientos rurales: Fincas de viñedo de interior con casas de campo rústicas alejadas de las zonas hoteleras masivas de costa. Entorno y actividades: Entorno del Parque Natural de la Bahía de Cádiz y pinares interiores. Rutas de senderismo plano por los Pinares de la Barrosa y de Claverán, paseos botánicos por salinas tradicionales recuperadas para el ecoturismo, ornitología de flamencos y kayak de mar.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11028','rural','Oferta de turismo rural','Alojamientos rurales: Casas de campo agrícolas y de dehesa bajas independientes, apartamentos rústicos sencillos en entornos de pinar. Entorno y actividades: Custodia el Complejo Endorreico de Puerto Real (Lagunas de Taraje, Comisario y San Antonio). Rutas de senderismo plano de alta protección ecológica entre marismas de interior y lagunas, paseos por el pinar de Las Canteras (bosque maduro) y rutas cicloturistas de llanura.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11902','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales de campo aisladas en llanuras adehesadas de monte bajo, cortijos agrícolas tradicionales. Entorno y actividades: Entorno de las faldas de la Sierra de las Cabras y cercanía al Embalse de Guadalcacín II. Rutas de senderismo hacia el nacimiento del manantial de Tempul, senderos cicloturistas de montaña que bordean el gran embalse de interior, pesca de agua dulce y paseos entre encinares de campiña alta.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11032','rural','Oferta de turismo rural','Alojamientos rurales: Casas de campo tradicionales vinculadas a las huertas navaceras (cultivos en arena de playa), alojamientos de interior de viñedo. Entorno y actividades: Margen izquierda de la desembocadura del río Guadalquivir, frente al Parque Nacional de Doñana. Rutas que conectan con el Espacio Natural Protegido de Doñana mediante barcazas fluviales, paseos por el Sendero del Pinar de la Algaida (bosque de pinos con restos arqueológicos), ornitología en las marismas de Bonanza y rutas cicloturistas llanas. PROVINCIA: TERUEL (Texto Plano Limpio).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43001','rural','Oferta de turismo rural','Alojamientos rurales: Posadas medievales integradas en murallas de yeso rojizo, casonas tradicionales de la serranía con entramados de madera de enebro y galerías de forja, hoteles boutique de naturaleza con vistas al cañón y apartamentos rústicos. Entorno y actividades: Capital de la Sierra de Albarracín. Custodia el Paisaje Protegido de los Pinares de Rodeno. Destaca por las rutas de senderismo hacia las pinturas rupestres prehistóricas levantinas, el sendero fluvial adaptado de las riberas del río Guadalaviar que rodea el casco monumental, una de las mayores mecas mundiales de la escalada en bloque (búlder) bajo el bosque y senderos micológicos de primer nivel (boletus).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44246','rural','Oferta de turismo rural','Alojamientos rurales: Antiguas masías agrícolas fortificadas de piedra dorada aisladas entre olivares y almendros, hoteles de campo boutique con criterios de diseño eco-sostenible y casas rurales de piedra gótica rehabilitadas en el casco viejo amurallado. Entorno y actividades: Capital de la Comarca del Matarraña (bautizada como la Toscana española). Ofrece paseos fotográficos y rutas cicloturistas a lo largo de las riberas del río Matarraña, conexiones directas con la Vía Verde de la Val de Zafán (cicloturismo de túneles y viaductos espectaculares), caminatas botánicas por valles mediterráneos de colinas suaves y senderos micológicos de encinar.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44037','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales rústicas ligadas a antiguos molinos papeleros del siglo XVIII junto al río, hostales con encanto de montaña y fincas de agroturismo. Entorno y actividades: Estribaciones del Parque Natural de los Puertos de Beceite. Sede de la espectacular ruta senderista de El Parrizal (pasarelas de madera colgadas sobre un angosto cañón fluvial de aguas turquesas), pozas naturales aptas para el baño como L''Assut y la Pesquera, y rutas cicloturistas de montaña (BTT) de alto nivel.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44059','rural','Oferta de turismo rural','Alojamientos rurales: Casonas de piedra señoriales del Maestrazgo, antiguos cuarteles y hosterías carlistas rehabilitadas con grandes chimeneas rústicas de campana, y apartamentos rurales familiares orientados al montañismo de aislamiento. Entorno y actividades: Encaramado de forma vertiginosa a un impresionante risco calizo a 1.300 metros de altitud en el Maestrazgo salvaje. Rutas de senderismo de los Miradores del Maestrazgo, caminatas por las hoces y muelas calcáreas talladas por el río Cantavieja, senderos de interpretación de la arquitectura tradicional de piedra seca (Patrimonio de la Humanidad por la UNESCO) y avistamiento de buitres leonados y cabra montés.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44049','rural','Oferta de turismo rural','Alojamientos rurales: Palacetes rurales renacentistas de sillería dorada con balcones de forja tradicional en un casco urbano de piedra protegido, casas de turismo rural independientes y apartamentos boutique de interior. Entorno y actividades: Comarca del Matarraña alto, rodeado de lomas olivareras. Destaca por las rutas de senderismo arqueológico hacia el poblado íbero de San Antonio integrado de forma virgen en el monte, caminatas tranquilas entre campos de olivos milenarios y viñedos, cicloturismo de carretera familiar sin tráfico y paseos botánicos por bosques mediterráneos de pino carrasco.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44158','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles rurales de montaña de carácter familiar orientados al turismo de nieve, casas rurales de alquiler íntegro con chimeneas de piedra caliza y antiguos caseríos ganaderos mimetizados en la falda de la sierra. Entorno y actividades: Comarca de Gúdar-Javalambre. Rutas senderistas bajo frondosos bosques boreales de pino negro de alta montaña, turismo micológico de primer nivel mundial (epicentro de la recolección regulada de la Trufa Negra de Teruel y robellones en otoño), cercanía inmediata a la estación de esquí de Valdelinares y cicloturismo de montaña por los Altos de Gúdar.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44201','rural','Oferta de turismo rural','Alojamientos rurales: Casas de labranza tradicionales con espectaculares aleros de madera tallada a mano, hoteles boutique rurales con patios interiores ajardinados y posadas medievales de piedra (Premio Europa Nostra por su conservación). Entorno y actividades: Piedemonte de la Sierra de Gúdar. Ofrece la ruta senderista del río Mijares, senderos de interpretación botánica por dehesas mixtas de sabinas y encinas viejas, rutas ecuestres de montaña y es una de las zonas de máxima nitidez nacional para la observación de estrellas al contar con certificación Starlight de cielos negros limpios.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44149','rural','Oferta de turismo rural','Alojamientos rurales: Casas de turismo rural intramuros integradas en un conjunto arquitectónico medieval gótico intacto y protegido, y palacetes de la Orden del Temple habilitados para pernocta rústica. Entorno y actividades: Corazón del Maestrazgo profundo. Ofrece paseos etnográficos de aislamiento absoluto, rutas de senderismo hacia el cercano Monumento Natural de las Cuevas de Cañart, caminos tradicionales de herradura delimitados por interminables muros de piedra seca y caminatas por riberas de montaña calizas secas.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44193','rural','Oferta de turismo rural','Alojamientos rurales: Apartamentos rústicos de alta montaña aislados, casas de piedra de cantería con ventanas saeteras tradicionales y chimeneas de campana bajo las murallas de su castillo. Entorno y actividades: Enclavado en el Parque Cultural del Maestrazgo, a las faldas de la Sierra de Gúdar. Impresionantes rutas de senderismo hacia el cañón salvaje del río Monleón, caminatas exigentes entre pinares silvestres alpinos, senderos de interpretación micológica otoñal (níscalos) y cascadas ocultas de deshielo.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44154','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles de naturaleza de lujo orientados al ecoturismo y la gastronomía micológica de kilómetro cero, masías unifamiliares rodeadas de pinares. Entorno y actividades: Matarraña montañoso occidental, lindando con la provincia de Castellón. Destaca por las rutas de senderismo que ascienden a las Peñas de Masmut (colosales farallones verticales de roca caliza rosada), avistamiento ornitológico de buitres leonados, rutas de recolección de setas en sus pinares húmedos de altura y circuitos BTT.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43002','rural','Oferta de turismo rural','Alojamientos rurales: Parador nacional emplazado en un castillo calatravo medieval alto que corona el cerro, fincas de campo de labranza y casas rurales de vega agrícola. Entorno y actividades: Entorno del río Guadalope y la Estanca de Alcañiz. Ofrece el sendero fluvial de los Azudes, observación ornitológica de primer nivel en el humedal protegido de la Estanca (ánades, garzas reales), rutas cicloturistas llanas y punto de partida de los tramos bajo de la Vía Verde del Matarraña.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44071','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales unifamiliares con porches de roca, apartamentos rústicos al pie de imponentes peñascos calizos y castillos templarios enriscados. Entorno y actividades: Maestrazgo septentrional. Alberga el Monumento Natural del Puente de Fonseca (espectacular formación kárstica natural con tobas calizas y túneles de musgo sobre el río Guadalope). Destaca por la ruta senderista que cruza las hoces y el túnel excavado en la roca del embalse de Santolea y senderos micológicos de monte bajo.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90874','rural','Oferta de turismo rural','Alojamientos rurales: Apartamentos tradicionales de montaña con acabados en madera de pino de Gúdar, casas rurales familiares independientes junto al río y cabañas forestales. Entorno y actividades: Sierra de Gúdar alta. Rutas de senderismo de ascensión al pico Peñarroya (el techo de la provincia de Teruel con 2.019 metros de altitud), paseos fluviales por el sendero del río Alfambra, deportes de nieve de invierno en la estación de Valdelinares y turismo micológico de otoño.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44086','rural','Oferta de turismo rural','Alojamientos rurales: Alojamientos rurales de gran nivel integrados en antiguas casas señoriales medievales con bodegas de vino antiguas, masías rurales con encanto en los campos linderos del llano. Entorno y actividades: Comarca del Matarraña. Cruce de caminos central de la Vía Verde de la Val de Zafán (cicloturismo de túneles y viaductos espectaculares). Rutas senderistas de arte rupestre en el barranco del Calapatá, paseos llanos fotográficos y senderos agrícolas de olivares y almendros.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44151','rural','Oferta de turismo rural','Alojamientos rurales: Casas de pueblo tradicionales de mampostería estrecha de piedra, apartamentos rurales acogedores para familias y espeleólogos a pie de montaña. Entorno y actividades: Maestrazgo kárstico. Alberga el Monumento Natural de las Grutas de Cristal (colosal e imponente joya espeleológica mundial de estalactitas y estalagmitas excéntricas). Rutas de senderismo por el espectacular cañón del río Guadalopillo, caminatas geológicas interpretativas y senderos entre huertos tradicionales.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44045','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales de alta montaña de piedra caliza con aislamiento reforzado, apartamentos rústicos forestales pegados a la espesura del bosque. Entorno y actividades: Sierra de Albarracín, a más de 1.500 metros de altitud. Uno de los mayores pulmones continuos de pinares de pino silvestre de España. Destaca por el senderismo micológico extremo (paraíso de la recolección del hongo boletus), rutas botánicas de las fuentes de Bronchales, avistamiento de ciervos y corzos en libertad y aire puro de altitud.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44244','rural','Oferta de turismo rural','Alojamientos rurales: Chalets alpinos rústicos de alta montaña tradicionales, apartamentos de turismo de nieve a pie de laderas forestales y pinadas. Entorno y actividades: El municipio situado a mayor altitud de la península ibérica considerando su núcleo urbano (1.692 metros), en la Sierra de Gúdar alta. Rutas de senderismo de alta montaña entre pinares boreales de pino negro autóctono, caminatas hacia los cortados de las umbrías, raquetas de nieve invernales y esquí alpino.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44137','rural','Oferta de turismo rural','Alojamientos rurales: Casas de piedra tradicionales de montaña con muros anchos aislantes, apartamentos rústicos en valles cerrados de frutales de montaña junto a arroyos trucheros. Entorno y actividades: Valle del río Pau, Sierra de Gúdar. Rutas de senderismo hacia el Monumento Natural del Pino del Escbón (abeto-pino monumental centenario protegido), paseos de interpretación fluvial, senderos ganaderos que suben a brañas de altura y turismo micológico.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44114','rural','Oferta de turismo rural','Alojamientos rurales: Palacetes rurales de piedra caliza con espectaculares arcos, posadas de turismo de interior con encanto del Matarraña y masías. Entorno y actividades: Cuenta con la tirolina en posición tumbada más larga de Europa (casi 2 km cruzando un valle de montaña). Rutas de senderismo hacia el Covavina, caminatas que miran a los Puertos de Beceite, senderos botánicos entre encinas y olivares rústicos de ladera.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44174','rural','Oferta de turismo rural','Alojamientos rurales: Casonas rurales serranas de piedra con forja tradicional, apartamentos de montaña independientes rodeados de dehesas ganaderas. Entorno y actividades: Extremo norte de la Sierra de Albarracín. Destaca por los singulares "Ríos de Piedra" (colosales acumulaciones geológicas de bloques de cuarcita de origen periglaciar únicos en Europa). Rutas de senderismo hacia el pico Caimodorro, paseos por melojares (robledales) y recolección de setas.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44120','rural','Oferta de turismo rural','Alojamientos rurales: Casas de pastores de la alta sierra tradicionales, apartamentos rústicos orientados al turismo etnográfico y de aislamiento. Entorno y actividades: Muela de San Juan, nacimiento del río Guadalaviar/Turia. Capital histórica de la transhumancia ganadera. Rutas de senderismo hacia los nacimientos fluviales, paseos por inmensos pastizales alpinos de alta montaña, senderos micológicos de otoño y avistamiento de fauna ibérica de monte alto.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44119','rural','Oferta de turismo rural','Alojamientos rurales: Alojamientos rurales unifamiliares con chimenea central, apartamentos de montaña construidos en mampostería de roca y albergues alpinos. Entorno y actividades: El segundo pueblo más alto de España, en la falda de la Muela de San Juan. Rutas de senderismo arqueológico hacia las dehesas celtíberas del llano, caminatas de invierno con raquetas de nieve, pistas de esquí de fondo forestales de naturaleza y miradores hacia valles de origen glaciar.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44115','rural','Oferta de turismo rural','Alojamientos rurales: Casas de campo tradicionales de la cuenca minera y agrícola del río Alfambra, pequeños hostales rurales sencillos. Entorno y actividades: Uno de los yacimientos paleontológicos de dinosaurios más importantes de Europa. Rutas de senderismo e interpretación al aire libre que siguen reproducciones de dinosaurios a escala real integradas en riberas fluviales arcillosas, y senderos geológicos singulares de badlands aragonesas. PROVINCIA: GUADALAJARA (Texto Plano Limpio).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16219','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales de piedra de mampostería con espectaculares terrazas y miradores a la laguna, chalets de madera serranos independientes y apartamentos rústicos. Entorno y actividades: Ubicado plenamente en el Parque Natural de la Serranía de Cuenca. Destaca por la emblemática Senda del Escalerón a la Raya (ruta que transita sobre colosales cortados calizos que vigilan el valle), el sendero circular llano que bordea la Laguna de Uña (paraíso de la observación de aves acuáticas y rapaces), y barranquismo técnico en el arroyo de la Madera.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16078','rural','Oferta de turismo rural','Alojamientos rurales: Casonas señoriales del siglo XVI y XVII reconvertidas en hoteles boutique sobre el precipicio, posadas rústicas integradas en las hoces fluviales y casas de campo tradicionales en las aldeas serranas de su término municipal (como Valdecabras o Valloera). Entorno y actividades: Nudo logístico monumental flanqueado por el Parque Natural. Alberga el Monumento Natural de la Ciudad Encantada (recorrido senderista geológico entre colosales figuras de roca calcárea modeladas por la erosión). Destaca por las rutas de senderismo de la Hoz del Júcar y del río Huécar, escalada deportiva vertical en caliza de fama internacional y piragüismo fluvial.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16170','rural','Oferta de turismo rural','Alojamientos rurales: Casonas rurales con portadas de sillería dorada y balcones de forja tradicional, apartamentos rústicos acogedores y fincas rurales ligadas a la producción artesana de mimbre. Entorno y actividades: Puerta natural a la comarca de la Alcarria conquense y la Serranía. Sede de la espectacular ruta senderista del Estrecho de Priego (un angosto y profundo desfiladero calizo tallado por el río Escabas con paredes verticales de más de 80 metros), vías ferratas de montaña con puentes colgantes extremas para escaladores y senderos micológicos.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16215','rural','Oferta de turismo rural','Alojamientos rurales: Hostales de alta montaña especializados en senderistas, complejos de cabañas forestales de madera rodeadas de inmensos pinares silvestres y casas rurales con chimenea de campana. Entorno y actividades: Zona norte de la Serranía alta. Punto de partida directo de la ruta de senderismo hacia el Nacimiento del Río Cuervo (Monumento Natural célebre por sus saltos de agua y espectaculares formaciones de cascadas de toba caliza cubiertas de musgo mágico), senderos micológicos otoñales y avistamiento de ciervos y gamos en la umbría.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16053','rural','Oferta de turismo rural','Alojamientos rurales: Casonas de labranza tradicionales serranas unifamiliares con corrales recuperados, apartamentos rurales de interior y alojamientos de montaña junto a pinares. Entorno y actividades: Entorno de la alta serranía y del balneario de Solán de Cabras. Ofrece la ruta de senderismo de la Hoz de Beteta, caminatas de interpretación botánica por el desfiladero fluvial rodeado de tilos centenarios (un oasis húmedo único), pasarelas sobre el río Guadiela, y rutas cicloturistas de montaña (BTT).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16035','rural','Oferta de turismo rural','Alojamientos rurales: Casas de turismo rural con mampostería antigua de piedra a la sombra del castillo de Rochafrida, posadas serranas tradicionales con amplios porches de leña y apartamentos para montañeros. Entorno y actividades: Entorno de lapiaces y cañones calizos extremos. Destaca por la ruta senderista del Monumento Natural de las Torcas de Lagunaseca (espectaculares depresiones circulares del terreno en roca kárstica), senderos que cruzan la Hoz de Beteta bajo densos bosques de quejigos y pinos laricios, y recolección de setas en otoño.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16239','rural','Oferta de turismo rural','Alojamientos rurales: Alojamientos rurales distribuidos en pequeños barrios o "hazas" de montaña tradicionales, casas de aldea de piedra caliza con aislamiento reforzado para el invierno. Entorno y actividades: Custodia la cabecera del cañón del río Cuervo. Espectaculares rutas de senderismo hacia los altos de la muela, senderos pastoriles que acceden a prados alpinos altos donde pasta el ganado, observación de cielos limpios nocturnos (zona integrada en el Parque con certificación Starlight) y raquetas de nieve invernales.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16165','rural','Oferta de turismo rural','Alojamientos rurales: Casas de piedra medievales de alquiler íntegro integradas dentro de un pequeño casco histórico amurallado serrano, apartamentos rústicos pequeños. Entorno y actividades: Bañado por el río Escabas alto. Ofrece paseos de aislamiento absoluto, rutas de senderismo exigentes hacia la dehesa de Poyatos, caminos tradicionales forestales entre avellanos, tejos y densas masas de pinos silvestres, y pesca deportiva truchera sin muerte de alta montaña.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16040','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales de piedra berroqueña unifamiliares con amplias parcelas forestales, apartamentos de turismo de montaña rústicos. Entorno y actividades: Entorno de las muelas de Cuenca. Alberga el paraje natural de Tierra Muerta y los Callejones de Las Majadas (espectacular laberinto de callejones, arcos y monolitos kársticos calcáreos esculpidos por el viento y el agua). Rutas senderistas geológicas e interpretativas y senderos micológicos para la recolección de hongos boletus y níscalos.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16048','rural','Oferta de turismo rural','Alojamientos rurales: Apartamentos tradicionales rurales con chimeneas rústicas junto al río, casas de pueblo de alquiler íntegro optimizadas para grupos familiares. Entorno y actividades: Ribera del río Escabas. El mayor hub de turismo estival de agua dulce de la provincia; destaca por sus famosas playas fluviales naturales de aguas cristalinas ideales para el baño y el descanso veraniego. Rutas de senderismo plano de ribera bajo túneles vegetales de mimbreras doradas, alisos y sauces, y paseos fotográficos.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16107','rural','Oferta de turismo rural','Alojamientos rurales: Casas de montaña enriscadas en una colina cónica escarpada con arquitectura tradicional serrana de yeso y madera caliza, apartamentos rústicos. Entorno y actividades: Valle del río Júcar alto. Rutas de senderismo de ascensión al pico de la Mogorrita (el techo de la provincia de Cuenca con 1.864 metros de altitud), paseos fluviales por el sendero alto del Júcar, observación ornitológica de buitres leonados y rutas de micología de pinar.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14001','rural','Oferta de turismo rural','Alojamientos rurales: Parador nacional emplazado en un imponente castillo medieval encaramado al risco, casas de turismo rural intramuros de piedra, y posadas con encanto manchego. Entorno y actividades: Ubicado sobre un espectacular meandro encajonado del río Júcar inferior. Ofrece la famosa ruta senderista de la Hoz de Alarcón (sendero circular homologado que bordea el profundo cañón fluvial bajo las torres fortificadas medievales), piragüismo, vela y kayak náutico de interior en el cercano Embalse de Alarcón.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16202','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales de piedra tradicionales del extremo oriental de la provincia (influencia valenciana y serrana), apartamentos rústicos con jardín y barbacoa. Entorno y actividades: Entorno de las serranías bajas de cuarcita. Destaca por la ruta del Sendero de las Torcas de Talayuelas, caminatas hacia los Callejones de Talayuelas (formaciones geológicas de roca de arenisca rojiza espectaculares que simulan murallas), senderos boscosos de pinos y dehesas agrícolas.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16082','rural','Oferta de turismo rural','Alojamientos rurales: Complejos de turismo de interior y aventura, casas de cal de pueblo andalusí-manchego con chimeneas y apartamentos rurales sobre el río. Entorno y actividades: Confluencia de cinco ríos (destacando el Cabriel). Alberga el Monumento Natural de las Chorreras del Cabriel (colosal tramo fluvial de saltos de agua, cascadas, pozas naturales turquesas y tobas calcáreas). Rutas de senderismo acuático, barranquismo, rafting fluvial, kayak y sendas de media montaña.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16033','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles rurales integrados en antiguas casas palacio manchegas con patios de columnas de madera, posadas rurales e históricas fincas de labranza de llanura cerealista. Entorno y actividades: Turismo rural de llanura manchega y molinos de viento. Rutas senderistas de interpretación histórica y natural rodeando las faldas de la colina que custodia su imponente y fotogénico castillo del siglo XV, caminatas tranquilas por cañadas y senderos rodeados de viñedos viejos de llanura alta.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16100','rural','Oferta de turismo rural','Alojamientos rurales: Casas de labranza tradicionales de la Mancha conquense de anchos muros de tapial y fachadas blancas de cal con bodegas subterráneas, alojamientos rurales pequeños. Entorno y actividades: Entorno de la llanura de viñedos y monte bajo mediterráneo. Rutas que conectan con senderos de cañadas reales ganaderas de largo recorrido, caminatas llanas ideales para cicloturismo familiar entre dehesas agrarias de encinas centenarias aisladas y observación ornitológica de aves esteparias raras.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16133','rural','Oferta de turismo rural','Alojamientos rurales: Casas de pueblo tradicionales manchegas adaptadas rústicamente para alquiler íntegro con patios interiores y barbacoas, hostales rurales de interior. Entorno y actividades: Conocido como El Balcón de la Mancha por su monumental cerro repleto de molinos de viento tradicionales. Alberga el Complejo Lagunar de Mota del Cuervo (Reserva de la Biosfera). Rutas de senderismo plano de alta observación ornitológica de aves palustres (flamencos, avetoros), senderos llanos de cicloturismo de campiña y paseos de interpretación agraria.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16121','rural','Oferta de turismo rural','Alojamientos rurales: Complejos de cabañas forestales de madera integradas bajo densas pinadas, casas tradicionales serranas de mampostería gruesa caliza. Entorno y actividades: Corazón de la Serranía de Cuenca alta. Destaca por el paraje natural de Los Callejones de Las Majadas, rutas de senderismo exigentes de montaña, paseos hacia el Hosquillo (parque zoológico natural en un cañón cerrado donde se observa oso pardo, lobo ibérico y ciervos en semilibertad, con acceso controlado), y senderos de pastores.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16041','rural','Oferta de turismo rural','Alojamientos rurales: Casas de campo agrícolas y de monte bajo independientes de interior, apartamentos rústicos sencillos en el casco fortificado. Entorno y actividades: Entorno del gran Embalse de Buendía y riberas del río Guadiela. Sede de la famosa Ruta de las Caras (recorrido de senderismo plano mágico bajo un bosque de pinos carrascos donde se encuentran colosales esculturas y rostros esculpidos directamente en las paredes de roca arenisca naturales). Senderos náuticos de embalse (kayak, piragüismo) y paseos ornitológicos en cortados de caliza. PROVINCIA: BURGOS (Texto Plano Limpio).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09007','rural','Oferta de turismo rural','Alojamientos rurales: Casas de turismo rural colgadas en el desfiladero, posadas medievales intramuros con entramados de madera y balconadas rústicas, y apartamentos con vistas al río Ebro. Entorno y actividades: Ubicado plenamente en el Parque Natural de Montes Obarenes-San Zadornil. Destaca por la ruta de senderismo del Desfiladero del río Purón (estrecho cañón fluvial espectacular), la senda del cañón del Ebro, paseos botánicos por el hayedo de San Zadornil ("la Nueva York de los bosques"), paseos fluviales por el puente románico fortificado y piragüismo de interior.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09018','rural','Oferta de turismo rural','Alojamientos rurales: Posadas reales castellanas de anchos muros de sillería dorada, hoteles rurales con encanto histórico dentro de la villa y casas de pueblo independientes para grupos familiares. Entorno y actividades: Espacio Natural Protegido de Sabinares del Arlanza y de la Yecla. Alberga el Desfiladero de la Yecla (espectacular y angosta garganta kárstica transitable a pie mediante pasarelas colgantes sobre el río). Ofrece la ruta del Cementerio de Sad Hill (escenario cinematográfico de dehesa integrado en la naturaleza), y el sendero de los sabinares albares más antiguos de la península.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09005','rural','Oferta de turismo rural','Alojamientos rurales: Palacetes rurales rústicos con fachadas de cal y vigas de madera vista, apartamentos rústicos acogedores y alojamientos de ribera junto al Arlanza. Entorno y actividades: Valle del río Arlanza. Ofrece la ruta senderista del Sendero del Buen Conde, caminatas hacia las ruinas del Monasterio de San Pedro de Arlanza (rodeado de inmensos bosques de encinas y sabinas de roca), senderos cicloturistas de llanura alta y paseos de interpretación del valle fluvial.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09006','rural','Oferta de turismo rural','Alojamientos rurales: Casonas hidalgas fortificadas y palacios rurales de sillería gruesa, posadas de montaña orientadas a montañeros y cabañas pasiegas-burgalesas rehabilitadas en las pedanías del norte. Entorno y actividades: Comarca de Las Merindades, frontera con los Valles Pasiegos. Destaca por el Monumento Natural de Ojo Guareña (colosal complejo de cuevas kársticas con ermita rupestre y galerías subterráneas). Ofrece rutas de alta montaña hacia el macizo de Castro Valnera, senderos bajo frondosos hayedos de las faldas cantábricas, y raquetas de nieve en invierno.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09266','rural','Oferta de turismo rural','Alojamientos rurales: Casas de montaña de piedra roja caliza y teja curva tradicionales de la sierra alta, apartamentos rústicos con chimenea de leña y albergues de naturaleza forestal. Entorno y actividades: Corazón de la Sierra de la Demanda. Nudo de la Vía Verde de la Demanda (antiguo trazado ferroviario minero ideal para senderistas y cicloturistas). Rutas de ascensión alpina al Pico Mencilla y al San Millán (techo de la provincia con 2.131 metros), senderos rodeados de acebales protegidos, robledales centenarios y el embalse del Arlanzón.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09011','rural','Oferta de turismo rural','Alojamientos rurales: Casas de turismo rural intramuros con patios de mampostería antigua, apartamentos turísticos integrados en el casco histórico señorial y hostales de interior. Entorno y actividades: Eje del Parque Natural de Montes Obarenes-San Zadornil. Sede del Sendero del Desfiladero de la Horadada (colosal garganta cortada por el río Oca). Ofrece rutas de senderismo botánico entre encinares atlánticos y mediterráneos mixtos, paseos fluviales por canales medievales de agua y micología forestal de otoño.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09232','rural','Oferta de turismo rural','Alojamientos rurales: Posadas de alta montaña construidas con vigas de pino de la Demanda y piedra caliza, casas rurales unifamiliares de pinar aisladas en las alturas y alojamientos para excursionistas. Entorno y actividades: Custodia el Parque Natural de las Lagunas Glaciares de Neila. Espectaculares rutas de senderismo de alta montaña que recorren el borde de los circos glaciares (Laguna Negra, Laguna Larga, Laguna de la Cascada), senderos micológicos de pinar húmedo alto (boletus), observación astronómica certificada Starlight y dehesas de pastores trashumantes.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09008','rural','Oferta de turismo rural','Alojamientos rurales: Parador nacional en el colosal Palacio Ducal herreriano, posadas castellanas con patios porticados rústicos, y casas rurales de campiña ganadera. Entorno y actividades: Ribera del río Arlanza medio. Rutas que conectan con senderos de cañadas reales ganaderas de largo recorrido, caminatas llanas ideales para cicloturismo familiar entre dehesas agrarias de encinas y cultivos, y rutas enológicas en la Denominación de Origen Arlanza.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09289','rural','Oferta de turismo rural','Alojamientos rurales: Hostales rurales especializados en micología y turismo activo, cabañas de madera forestales mimetizadas en la pinada y grandes casas de piedra de cantería burgalesa. Entorno y actividades: Comarca de Pinares, falda meridional de la Sierra de la Demanda. Rutas de senderismo al Comunero de Revenga (necrópolis medieval tallada en roca viva rodeada de robles centenarios), caminatas hacia las Lagunas de Neila, recolección masiva de hongos boletus y níscalos en pinares silvestres infinitos y senderos fluviales del río Arlanzón joven. PROVINCIA: MURCIA - VALLE DE RICOTE E INTERIOR (Texto Plano Limpio).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09009','rural','Oferta de turismo rural','Alojamientos rurales: Casas solariegas de turismo rural amplias para grupos, hoteles boutique de interior con encanto medieval en el casco antiguo y fincas rurales. Entorno y actividades: Valle de Tobalina alto, comarca de Las Merindades. Rutas de senderismo suave que bordean las dehesas del río Trueba, paseos cicloturistas llanos de gran recorrido por la antigua línea del Santander-Mediterráneo, y punto base idóneo para explorar los cañones calizos de la zona norte.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09274','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales vinculadas al patrimonio industrial textil del siglo XIX (antiguas fábricas e hilaturas mecánicas reconvertidas en pernoctas), apartamentos rústicos. Entorno y actividades: Sierra de la Demanda húmeda. Sede de la ruta de senderismo de la Senda de los Cascajales, caminatas bajo la umbría de densos hayedos calcícolas del río Oropesa, senderos micológicos micológicos de pinar y quejigal y paseos fotográficos fluviales de montaña.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09256','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles de campo y casas de turismo rural integrados en bodegas subterráneas tradicionales de la Ribera del Duero, fincas vinícolas tradicionales de agroturismo. Entorno y actividades: Comarca de la Ribera del Duero. Rutas de senderismo suave entre dehesas de viñedos centenarios de uva tempranillo, paseos cicloturistas llanos por los caminos de sirga del canal del Duero, turismo gastronómico-rural de asados y enoturismo de primer nivel mundial.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09363','rural','Oferta de turismo rural','Alojamientos rurales: Casas de labranza castellanas tradicionales de anchos muros de tapial y piedra caliza blanca con patios de carruajes, posadas rurales de campiña. Entorno y actividades: Llanura cerealista de la comarca de Odra-Pisuerga. Cruzado por el Camino de Santiago de la Meseta. Rutas de senderismo plano de interpretación histórica que siguen las calzadas romanas locales (Segisama), caminatas tranquilas de dehesa agraria y avistamiento de avifauna esteparia.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09014','rural','Oferta de turismo rural','Alojamientos rurales: Alojamientos rurales unifamiliares en el casco fortificado de piedra y caliza, apartamentos rústicos de montaña. Entorno y actividades: Borde del Páramo de Masa y cuna de Félix Rodríguez de la Fuente. Cuenta con el espectacular diapiro salino (fenómeno geológico único visible desde el espacio). Rutas de senderismo por las antiguas Salinas romanas de evaporación, caminatas de ascensión al castillo calizo sobre el abismo y rutas ornitológicas de grandes rapaces de roca.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09413','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales de piedra en pequeños núcleos agrícolas aislados húmedos del norte burgalés, apartamentos rústicos con chimenea de leña. Entorno y actividades: Entrada norte colindante con Cantabria. Destaca por el espectacular bosque de hayas y robles del Hayedo de Carrales. Rutas de senderismo hacia el Desfiladero de las Palancas, paseos boscosos por brezales y cercanía inmediata a las cascadas de Las Merindades.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09013','rural','Oferta de turismo rural','Alojamientos rurales: Palacetes rurales renacentistas con patios porticados rústicos, posadas de turismo rural medievales con vistas al castillo calizo alto. Entorno y actividades: Ribera del Duero oriental. Rutas de senderismo histórico que rodean su torre del homenaje del siglo X, caminatas agrícolas entre viñedos de cepa vieja, y senderos llanos fluviales que siguen el curso del río Arandilla.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09048','rural','Oferta de turismo rural','Alojamientos rurales: Albergues y casonas de turismo de interior vinculados al Camino de Santiago Francés, casas de labranza riojano-burgalesas. Entorno y actividades: Comarca de la Riojilla Burgalesa, falda norte de la Sierra de la Demanda. Rutas del Camino de Santiago, senderismo hacia las cuevas eremíticas paleocristianas talladas en las colinas de arcilla linderas, paseos por las riberas del río Tirón y rutas cicloturistas de dehesa.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31032','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales cueva bioclimáticas (viviendas excavadas directamente en la arcilla del risco de la montaña), hoteles de campo orientados al ecoturismo de llanura y apartamentos rurales familiares. Entorno y actividades: Puerta de entrada oficial al Parque Natural y Reserva de la Biosfera de las Bardenas Reales. Ofrece una experiencia única de turismo rural en un paisaje semidesértico. Destaca por las rutas de cicloturismo de montaña (BTT) bordeando formaciones como Castildetierra, senderismo geológico por barrancos de yeso y observación de aves esteparias y rapaces de desierto.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31264','rural','Oferta de turismo rural','Alojamientos rurales: Caseríos aislados de piedra y pradera ganadera de la comarca de Xareta, apartamentos rústicos familiares e íntimos rodeados de bosques mágicos de castaños. Entorno y actividades: Célebre por su monumental Cueva de las Brujas (Sorginen Lezea), un colosal túnel kárstico natural horadado por el regato del Infierno. Destaca por el Sendero de las Cuevas (que conecta peatonalmente con Urdax y las cuevas de Sara en Francia mediante un camino marcado por un caballo azul), senderismo de castañares, dehesas atlánticas y mitología.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33013','rural','Oferta de turismo rural','Alojamientos rurales: Parador nacional integrado en el palacio gótico monumental, casas de turismo rural señoriales en el casco medieval y fincas de agroturismo vitivinícola. Entorno y actividades: Zona de transición de la Navarra Media. Ofrece paseos llanos y rutas cicloturistas entre viñedos viejos de la Zona Media navarra, caminatas botánicas en las dehesas del río Cidacos y cercanía inmediata a la Laguna de Pitillas, un humedal protegido de primer nivel para la observación de aves acuáticas migratorias.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33009','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales y caseríos típicos del Valle de Larraun con grandes solanas de madera orientadas al sur, hoteles de montaña especializados en cicloturismo de interior. Entorno y actividades: Falda de la impresionante Sierra de Aralar. Eje central de la Vía Verde del Plazaola (antiguo trazado de tren reconvertido para caminantes y ciclistas). Rutas de senderismo forestal hacia el Nacedero del río Iribas, caminatas micológicas entre hayedos brumosos, dehesas ganaderas alpinas de oveja latxa y cuevas calizas como Mendukilo. PROVINCIA: GIRONA (Cataluña - Datos Curados).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33007','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles rurales de fachada histórica monumental, posadas castellano-navarras de sillería gruesa junto al río Ega y apartamentos rústicos. Entorno y actividades: Nudo logístico monumental del Camino de Santiago. Ofrece la espectacular ruta de senderismo del Cañón del río Urederra en la cercana Sierra de Urbasa (famoso por sus pozas naturales e increíbles cascadas de aguas de color azul turquesa cristalino), paseos de ribera fluvial y cicloturismo de carretera.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31195','rural','Oferta de turismo rural','Alojamientos rurales: Casas de turismo rural típicas del Valle de Aezkoa de arquitectura de mampostería oscura, pequeños apartamentos rústicos forestales pegados al pinar. Entorno y actividades: Entrada occidental a la Selva de Irati. Alberga las fotogénicas ruinas de la Real Fábrica de Armas de Orbaitzeta, devorada por la vegetación selvática del bosque. Rutas senderistas que ascienden hacia la cueva de Arpea y la estación megalítica del monte Urkulu (monumentos arqueológicos alpinos).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90728','rural','Oferta de turismo rural','Alojamientos rurales: Grandes caseríos unifamiliares con estructuras internas de vigas de roble centenarias vistas, posadas rurales de la comarca de Cinco Villas (Bortziriak). Entorno y actividades: Paisaje atlántico de colinas suaves cubiertas de helechos y bosques. Rutas de senderismo hacia el embalse de Endara, caminatas de ascensión a picos menores como Bianditz, rutas cicloturistas a lo largo de la Vía Verde del Bidasoa y senderos micológicos de castañares húmedos.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33015','rural','Oferta de turismo rural','Alojamientos rurales: Casonas de labranza tradicionales de adobe y piedra de la comarca de Valdizarbe con patios agrícolas, albergues y apartamentos rurales de paso. Entorno y actividades: Confluencia exacta del Camino de Santiago Francés y el Aragonés, bañado por el río Arga. Rutas de senderismo plano de interpretación histórica que siguen los senderos fluviales, caminatas llanas de cicloturismo de campiña y paseos fotográficos entre campos llanos de viñedos y olivares.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33003','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales de piedra tradicionales del prepirineo navarro a orillas del río Irati, apartamentos rústicos familiares. Entorno y actividades: Entorno de las sierras prepirenaicas y el Embalse de Itoiz. Rutas de senderismo hacia la espectacular Foz de Lumbier y Foz de Arbayún (colosales gargantas calizas estrechas talladas por los ríos con pasarelas e imponentes colonias de buitres leonados que anidan en roca), y kayak fluvial de interior.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31105','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles e instalaciones balnearias históricas de interior integradas en entornos de roca de arenisca rojiza, posadas rurales de la Ribera alta. Entorno y actividades: Extremo sur de Navarra, cuenca del río Alhama. Rutas de senderismo hacia el Macizo de la Atalaya y la formación del Macizo de Roscas (espectaculares agujas de roca caliza y arenisca esculpidas por la erosión). Rutas que recorren cuevas eremíticas ocultas, senderos de matorral mediterráneo y paseos de huerta.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90705','rural','Oferta de turismo rural','Alojamientos rurales: Casas de aldea tradicionales aezcoanas de alta montaña de piedra caliza con chimeneas centrales rústicas, apartamentos pequeños de pinar. Entorno y actividades: Considerado el "Balcón del Pirineo navarro" por ser el municipio a mayor altitud de la región (1.050 metros). Ofrece espectaculares rutas de senderismo hacia el Museo de Estelas en su cementerio natural integrado, paseos por laberintos geológicos de roca kárstica en el bosque y raquetas de nieve invernales.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31232','rural','Oferta de turismo rural','Alojamientos rurales: Casas de campo agrícolas tradicionales vinculadas al agroturismo de la Vega del Ebro, pequeños hoteles boutique de interior en el casco histórico. Entorno y actividades: Valle del Ebro y Ribera navarra. Rutas de senderismo plano por los senderos fluviales de los meandros del río Ebro, caminos que conectan con los regadíos e infraestructuras agrarias de sus famosas huertas tradicionales, cicloturismo familiar de llanura y base sur para expediciones a las Bardenas Reales. PROVINCIA: PONTEVEDRA (Texto Plano Limpio).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36009','rural','Oferta de turismo rural','Alojamientos rurales: Casonas de piedra mariñanas restauradas, hoteles rurales de costa orientados al turismo de relax marino, apartamentos rústicos con vistas a las marismas y alojamientos de agroturismo tradicional. Entorno y actividades: Ubicado plenamente en el complejo intermareal Umia-O Grove (sitio Ramsar de alta protección). Destaca por la espectacular ruta de senderismo costero de las Pedras Negras en San Vicente do Mar (pasarelas de madera sobre formaciones caprichosas de granito frente al Atlántico), observación ornitológica masiva de aves acuáticas, playas salvajes de dunas protegidas como Lanzada, y kayak de mar.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36005','rural','Oferta de turismo rural','Alojamientos rurales: Casas de aldea costeras construidas en sillería gruesa de granito, apartamentos rurales rodeados de fincas boscosas y pequeños hostales de mar con encanto. Entorno y actividades: Extremo occidental de la Península del Morrazo. Eje de acceso marítimo al Parque Nacional de las Islas Atlánticas (Islas Cíes). Ofrece la espectacular ruta de senderismo de la Costa da Vela (acantilados verticales brutales que miran al océano abierto bajo el Faro de Home), paseos botánicos por los pinares litorales de Nerga y Barra, y turismo ornitológico de aves marinas.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36024','rural','Oferta de turismo rural','Alojamientos rurales: Colosales pazos gallegos señoriales con portalones heráldicos y hórreos gigantes, casas rectorales restauradas en valles fluviales de interior y granjas escuela de agroturismo ganadero. Entorno y actividades: En el interior de la comarca del Deza, rodeado de frondosos bosques gallegos autóctonos. Destaca por el Monumento Natural de la Fraga de Catasós (un bosque mágico con los castaños y robles de mayor altura de Europa central), rutas de senderismo fluvial a lo largo del río Asneiro, senderos micológicos otoñales extremos y senderos del Camino de Santiago de Invierno.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36031','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles palacio históricos vinculados al termalismo señorial del siglo XIX, casas de turismo rural integradas en aldeas tradicionales de montaña y apartamentos rústicos junto al río Tea. Entorno y actividades: Cuenca del río Tea (Espacio Protegido de la Red Natura). Destaca por la Senda Fluvial del Río Tea (recorrido de senderismo plano bajo bosques de galería autóctonos tupidos de alisos e higueras), playas fluviales de interior de aguas medicinales y limpias, ascensiones de media montaña a los montes de la Paradanta y rutas cicloturistas.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36004','rural','Oferta de turismo rural','Alojamientos rurales: Pazos de turismo rural vinculados a la viticultura tradicional y bodegas solariegas, casas de piedra tradicionales integradas en el conjunto histórico y apartamentos litorales de ría. Entorno y actividades: Corazón de la Comarca del Salnés, bañado por la Ría de Arousa. Ofrece rutas que conectan senderos agrícolas entre interminables viñedos de uva albariño emparrados sobre granito, paseos llanos por las marismas del río Umia (ornitología de primer nivel de ánades y flamencos), y rutas ecuestres de costa. 📂 PROVINCIA: LA CORUÑA (Galicia - Datos Curados).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36017','rural','Oferta de turismo rural','Alojamientos rurales: Casas de labranza gallegas tradicionales de mampostería antigua con lareiras (grandes chimeneas tradicionales de suelo), pazos espectaculares con jardines botánicos e hilos de agua vivos. Entorno y actividades: Valles del río Ulla medio. Destaca por las rutas de senderismo que acceden a los cañones y estrechos del río Ulla (San Xoán da Cova), paseos de interpretación botánica por las riberas fluviales tupidas donde desovan los salmones, senderos micológicos en carballeiras (bosques de robles) y turismo de dehesas ganaderas.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36059','rural','Oferta de turismo rural','Alojamientos rurales: Apartamentos rústicos de montaña construidos con esquistos y losas de piedra tradicionales, casas rurales de aldea unifamiliares con porches de madera aisladas en valles cerrados. Entorno y actividades: Frontera natural con la provincia de A Coruña marcada por el río Ulla. Alberga el espectacular paraje natural de la Fervenza do Toxa (una de las cascadas más altas e imponentes de Galicia en caída libre rodeada de robles y laureles silvestres). Rutas senderistas de la Senda do Deza, caminatas fluviales y piragüismo de río limpio.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36002','rural','Oferta de turismo rural','Alojamientos rurales: Parador nacional emplazado en la imponente fortaleza amurallada de Monterreal sobre el mar, casonas rurales de costa y apartamentos rústicos en parroquias interiores. Entorno y actividades: Ría de Vigo meridional y faldas de la Sierra de la Groba. Ofrece rutas de senderismo de media montaña que exploran la Sierra de la Groba (donde pastan manadas de caballos salvajes Garranos en libertad), miradores hacia las Islas Cíes, senderos fluviales del río Fraga con molinos hidráulicos antiguos restaurados y paseos litorales.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36014','rural','Oferta de turismo rural','Alojamientos rurales: Alojamientos rurales unifamiliares dentro del casco histórico fortificado de granito, antiguos conventos y rectorales adaptadas, y casas de turismo rural a orillas del río Miño. Entorno y actividades: Custodia la entrada al Parque Natural del Monte Aloia (la montaña mítica gallega). Espectaculares rutas de senderismo de montaña y botánicas entre masas arbóreas maduras con miradores que divisan todo el estuario del río Miño y Portugal, tramos iniciales gallegos del Camino de Santiago Portugués y rutas fluviales en kayak.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90044','rural','Oferta de turismo rural','Alojamientos rurales: Casas tradicionales de pescadores mariñanas de piedra vistas en el núcleo histórico de Combarro, pazos rurales con amplias fincas agrícolas de frutales. Entorno y actividades: Ribera norte de la Ría de Pontevedra. Destaca por la célebre Ruta de la Variante Espiritual del Camino de Santiago. Ofrece la ruta de senderismo de los Molinos de Samieira (Senda dos Muíños), caminatas bajo la fronda de los bosques que descienden hacia el mar y paseos fotográficos de naturaleza costera entre horreos pegados al agua.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36013','rural','Oferta de turismo rural','Alojamientos rurales: Casas de campo gallegas tradicionales alejadas del núcleo costero masivo, alojamientos rurales en bodegas de interior de colina. Entorno y actividades: Entorno interior rural de la comarca costera. Rutas de senderismo suave que recorren la Senda Fluvial de Dorrón entre viejos molinos de agua harineros, paseos botánicos por los campos agrícolas de dehesas tradicionales de hortalizas y cepas viejas, y cercanía a calas vírgenes de pinar.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36018','rural','Oferta de turismo rural','Alojamientos rurales: Alojamientos rurales integrados en monasterios medievales de interior rehabilitados para pernocta, casas de piedra de pastores restauradas y apartamentos de montaña con chimenea. Entorno y actividades: Nacimiento del río Lérez y colinas de la Sierra del Candán. Destaca por las rutas de senderismo que rodean el Monasterio de Santa María de Aciveiro, caminatas de alta protección ecológica entre los robledales de montaña del Candán, senderos de puentes medievales de piedra y avistamiento de aves rapaces forestales.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36054','rural','Oferta de turismo rural','Alojamientos rurales: Casas de campo agrícolas y de dehesa bajas de sillería de granito independientes de interior, antiguos palacetes hortícolas con encanto rústico. Entorno y actividades: Cuenca baja de la ribera del río Miño fronterizo. Rutas de senderismo plano fluviales que siguen el curso del río, senderos que suben hacia el espectacular mirador del Monte Goián con defensas históricas enterradas en el bosque, senderos de viveros botánicos y kayak fluvial.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36028','rural','Oferta de turismo rural','Alojamientos rurales: Complejos de turismo de interior integrados en antiguas moles molineras, casas rurales tradicionales con parcelas amplias y viñedos. Entorno y actividades: Valle del Salnés de interior. Sede de la espectacular ruta de senderismo de la Ruta de la Piedra y del Agua (Senda da Pedra e da Auga, un recorrido bajo túneles vegetales umbríos jalonado por decenas de molinos de agua de granito tradicionales restaurados que sube al Monasterio de Armenteira), y cicloturismo de montaña.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36048','rural','Oferta de turismo rural','Alojamientos rurales: Casas de labranza tradicionales bajas de piedra vinculadas al agroturismo vinícola, apartamentos rústicos pequeños con vistas al estuario del Miño. Entorno y actividades: Microclima del Valle del Rosal. Sede de la espectacular y única ruta de senderismo de los Molinos de Folón y Picón (60 molinos hidráulicos de granito escalonados en una cascada de roca de montaña espectacular catalogados como Bien de Interés Cultural). Caminatas botánicas entre viñedos de dehesa húmeda alta y ornitología.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36052','rural','Oferta de turismo rural','Alojamientos rurales: Casas de labranza tradicionales de piedra con fincas ganaderas, apartamentos rurales rústicos con chimeneas de leña ideales para familias. Entorno y actividades: Comarca del Deza interior. Rutas de senderismo que conectan con el Monasterio románico de San Lorenzo de Carboeiro (enclavado de forma espectacular en un meandro cerrado del río Deza rodeado de bosque autóctono cerrado), caminatas hacia las cascadas fluviales y senderos micológicos.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90534','rural','Oferta de turismo rural','Alojamientos rurales: Posadas y hoteles de turismo de interior articulados en torno al patrimonio termal tradicional, casonas gallegas con corredores y huertos de frutales. Entorno y actividades: Valle del río Umia, Camino de Santiago Portugués. Destaca por las rutas de senderismo plano por el Jardín Botánico y la Carballeira local (Monumento Natural), paseos fluviales de ribera hacia la cascada natural de Segade con ruinas de antiguas instalaciones hidroeléctricas devoradas por el bosque y senderos forestales llanos.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36902','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales de canteros tradicionales gallegas construidas con grandes vigas e hileras de granito antiguo, apartamentos rústicos de media montaña. Entorno y actividades: Entorno de las sierras interiores pontevedresas. Posee un patrimonio etnográfico monumental de eiras (conjuntos de hórreos) y puentes de piedra viejos. Rutas de senderismo de la Senda del río Almofrei, caminatas geológicas interpretativas entre grabados prehistóricos (petroglifos) integrados de forma virgen en la naturaleza del monte bajo, y ríos de montaña trucheros.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36050','rural','Oferta de turismo rural','Alojamientos rurales: Casas de campo agrícolas tradicionales bajas independientes de interior de viñedo, pequeños apartamentos rurales sencillos dentro del recinto fortificado. Entorno y actividades: Confluencia de los ríos Miño y Tea. Rutas de senderismo plano por los senderos fluviales de las islas habitadas protegidas del río Miño (Illa de Fillaboa), dehesas agrarias de vid, paseos por las sendas verdes llanas de ribera ideales para cicloturismo familiar de relax y pesca tradicional de río. PROVINCIA: GRANADA (Texto Plano Limpio).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18147','rural','Oferta de turismo rural','Alojamientos rurales: Cortijos alpujarreños independientes construidos con piedra y vigas de castaño, complejos rústicos con piscina rodeados de olivares milenarios, y alojamientos eco-sostenibles de interior. Entorno y actividades: Capital y puerta natural de la Alpujarra, a los pies de Sierra Nevada y la Sierra de Lújar. Destaca por el sendero GR-7, rutas de senderismo fluvial a lo largo del cauce del río Guadalfeo, rutas cicloturistas de montaña (BTT), paseos botánicos entre plantaciones de cítricos y olivos de montaña, y senderos micológicos en las umbrías.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18151','rural','Oferta de turismo rural','Alojamientos rurales: Casas de arquitectura tradicional alpujarreña (muros de piedra encalados con terraos planos de arcilla y chimeneas de sombrero), hostales rústicos con encanto y apartamentos rurales con vistas directas al abismo del cañón. Entorno y actividades: Ubicado plenamente en el Parque Nacional de Sierra Nevada y el Conjunto Histórico del Barranco de Poqueira. Destaca por la emblemática ruta de senderismo circular que conecta Pampaneira, Bubión y Capileira por el fondo del barranco, senderos de alta montaña, caminatas fotográficas botánicas entre castaños centenarios y observación de aves rapaces de cumbre.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18089','rural','Oferta de turismo rural','Alojamientos rurales: Casas cueva auténticas excavadas directamente en la arcilla (alojamientos bioclimáticos subterráneos tradicionales con chimeneas blancas exteriores que mantienen temperatura constante todo el año), palacetes señoriales andaluces rústicos en el casco histórico y cortijos agrícolas aislados en la hoya. Entorno y actividades: Integrado en el Geoparque de Granada (UNESCO). Ofrece una experiencia única de turismo rural en un paisaje de cárcavas arcillosas de aspecto lunar. Rutas de senderismo geológico por los cañones de arcilla, cicloturismo por pistas áridas, rutas fotográficas al atardecer en el Mirador del Fin del Mundo y cercanía al Parque Natural de la Sierra de Baza.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18042','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles de alta montaña de estilo alpujarreño, grandes casonas de piedra de alquiler íntegro con chimeneas tradicionales de leña y hostales para montañeros. Entorno y actividades: El municipio más alto del Barranco de Poqueira, dentro del Parque Nacional de Sierra Nevada. Punto de partida logístico principal para la ascensión a pie a las cumbres del Mulhacén (techo de la península ibérica con 3.479 metros) y el Veleta. Senderismo de alta dificultad por las lagunas glaciares de Sierra Nevada, rutas ecuestres alpinas y avistamiento de cabra montés.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18134','rural','Oferta de turismo rural','Alojamientos rurales: Casas de campo tradicionales granadinas con huerto, hoteles de montaña rústicos y alojamientos de esquí en los núcleos altos de su término municipal. Entorno y actividades: Estribaciones occidentales de Sierra Nevada. Sede de una de las rutas de senderismo de aventura más espectaculares y transitadas de Andalucía: Los Cahorros del Río Monachil (desfiladero calizo angosto transitable mediante colosales puentes colgantes, cascadas y pasos de roca estrechos). Escalada deportiva vertical en caliza, senderos de robledales y cicloturismo de carretera exigente.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18116','rural','Oferta de turismo rural','Alojamientos rurales: Posadas y hoteles rurales vinculados al termalismo histórico y medicinal, casas tradicionalmente blancas de pueblo serrano con fuentes de agua fresca en sus patios rústicos y apartamentos de montaña. Entorno y actividades: Puerta occidental de la Alpujarra alta y Parque Natural de Sierra Nevada. Destaca por la ruta senderista del Sendero de los Pescadores, caminatas fluviales junto al río Lanjarón, paseos botánicos por el Parque del Salado y el Bosque de Tello (repleto de castaños e hilos de agua de deshielo), rutas micológicas y senderos ecuestres. PROVINCIA: LEÓN - VALLES OCCIDENTAL Y GLACIARES (Texto Plano Limpio).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19001','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles palacio rurales barrocos, casas de turismo rural cimentadas sobre el acantilado y alojamientos rústicos vinculados a sus baños árabes termales históricos. Entorno y actividades: Entorno de la Sierra de Tejeda y Almijara. Sede de la espectacular ruta senderista de los Tajos de Alhama (un colosal cañón calizo con paredes verticales de más de 50 metros esculpidas por el río Alhama justo a los pies del pueblo). Caminatas de interpretación botánica por el desfiladero, senderos que bordean el Pantano de los Bermejales (kayak, piragüismo) y paseos ornitológicos.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18180','rural','Oferta de turismo rural','Alojamientos rurales: Casonas tradicionales alpujarreñas de mampostería gruesa y launa adaptadas con porches de madera, apartamentos rústicos de alta montaña con chimeneas de leña ideales para el invierno. Entorno y actividades: Municipio célebre por situarse a 1.476 metros de altitud en pleno Parque Nacional de Sierra Nevada. Destaca por las rutas de senderismo de alta montaña que ascienden a la mítica Siete Lagunas (valle de origen glaciar espectacular), senderos fluviales por el curso alto del río Trevélez (pesca truchera limpia), turismo gastronómico-rural vinculado al curado del jamón de Trevélez y avistamiento de fauna de cumbre.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18094','rural','Oferta de turismo rural','Alojamientos rurales: Cabañas de madera forestales rústicas, apartamentos de montaña independientes rodeados de castañares viejos y complejos de ecoturismo rural junto al río Genil. Entorno y actividades: Vertiente norte de Sierra Nevada alta, cabecera del río Genil. Destaca por la famosa ruta senderista del Tranvía de la Sierra (itinerario plano que aprovecha el antiguo trazado ferroviario minero cruzando túneles en la roca y puentes sobre el río), acceso norte al sendero alpino Vereda de la Estrella bajo las caras norte de los tres miles, senderos de castaños milenarios y micología.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18046','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales andaluzas de cal blanca de alquiler íntegro integradas a las faldas de la peña, apartamentos rústicos de montaña con chimenea de leña y pequeños hostales rurales de turismo activo. Entorno y actividades: Custodia el Parque Natural de la Sierra de Castril. Sede de la célebre y fotogénica ruta de senderismo de las Pasarelas del Río Castril (un espectacular sendero de pasarelas de madera ancladas sobre la pared de roca caliza vertical del desfiladero fluvial). Ofrece caminatas exigentes hacia el Nacimiento del Río Castril, exploración de cuevas kársticas como la Cueva del Doncel, senderos micológicos en sus pinares de montaña y avistamiento de buitres leonados y quebrantahuesos.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18023','rural','Oferta de turismo rural','Alojamientos rurales: Cortijos andaluces señoriales con dehesas y amplias fincas arboladas rústicas, casas cueva turísticas rehabilitadas en sus pedanías de interior y hostales de campo. Entorno y actividades: Entrada central al Parque Natural de la Sierra de Baza. Ofrece rutas de senderismo de montaña por los prados altos y pinares béticos de la sierra, caminatas de ascensión hacia el pico Santa Bárbara (2.269 metros), senderos botánicos entre pinos carrascos y encinares centenarios, rutas de micología forestal de otoño y dehesas de ganado extensivo.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18167','rural','Oferta de turismo rural','Alojamientos rurales: Casas cueva tradicionales excavadas en chimeneas de arcilla acondicionadas para pernocta rústica, y pequeños hostales de interior dedicados al agroturismo de la cerámica artesanal. Entorno y actividades: Geoparque de Granada, entorno de la Hoya de Guadix. Destaca por las rutas de senderismo geológico e interpretativo que recorren el paisaje arcilloso rojizo de las cárcavas, caminatas hacia los yacimientos arqueológicos de dehesas prehistóricas, rutas cicloturistas llanas de desierto y paseos fotográficos por formaciones de erosión caliza menores.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18107','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales de piedra tradicionales calizas del prepirineo penibético, apartamentos rústicos pequeños en valles de pinos resineros. Entorno y actividades: Vertiente norte del Parque Natural de las Sierras de Tejeda, Almijara y Alhama. Rutas de senderismo forestal por el sendero del río Bacal, caminatas de media montaña que exploran densos pinares de repoblación viejos, senderos micológicos de otoño (recogida de níscalos) y rutas cicloturistas de montaña (BTT).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18143','rural','Oferta de turismo rural','Alojamientos rurales: Casas de campo tradicionales del Valle de Lecrín rodeadas de campos de azahar, apartamentos rústicos con chimenea de leña y fincas de agroturismo. Entorno y actividades: Valle de Lecrín, zona de transición entre Sierra Nevada y la costa. Destaca por el Monumento Natural de la Falla de Nigüelas (colosal fenómeno geológico de fractura de roca visible a pie de pueblo). Rutas senderistas de la senda de los Molinos de agua, paseos botánicos por los jardines románticos de Müller y senderos agrícolas.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18098','rural','Oferta de turismo rural','Alojamientos rurales: Palacetes rurales renacentistas con portadas de piedra de sillería dorada, casas de turismo rural cueva independientes, fincas agrícolas de agroturismo ganadero y complejos de cabañas de montaña. Entorno y actividades: Extremo norte de la provincia, comarca de Huéscar. Destaca por el paraje natural de los Rodríguez, que alberga un bosque con ejemplares monumentales de Secuoyas Gigantes plantadas en el siglo XIX (las "mariquitas"). Rutas de senderismo de alta montaña que ascienden a la imponente mole caliza de la Sierra de la Sagra (2.383 metros de altitud, el pico más alto del altiplano), senderos de pastores de cordero segureño y rutas micológicas.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18183','rural','Oferta de turismo rural','Alojamientos rurales: Casas de pueblo tradicionales alpujarreñas de mampostería estrecha, apartamentos rurales acogedores con chimenea para familias y senderistas. Entorno y actividades: Alpujarra Oriental, Parque Natural de Sierra Nevada bajo. Ofrece la ruta de senderismo del Sendero del agua y de la seda, caminatas por los antiguos caminos medievales de herradura que cruzan castañares y dehesas de secano, paseos fluviales por el río Válor y rutas micológicas en bosques de encinas viejas.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18108','rural','Oferta de turismo rural','Alojamientos rurales: Alojamientos rurales unifamiliares con muros anchos de piedra oscura de pizarra, apartamentos de montaña de la cara norte de Sierra Nevada. Entorno y actividades: Marquesado de Zenete, cara norte alpina. Famoso por albergar la Ruta Solidaria del Avión (itinerario de senderismo de media-alta montaña que asciende hasta los restos de un avión militar norteamericano estrellado en los años 60 en la sierra). Senderos forestales entre pinos silvestres, castaños y antiguas explotaciones mineras de hierro romanas.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18173','rural','Oferta de turismo rural','Alojamientos rurales: Casas de campo agrícolas tradicionales bajas independientes de interior de la vega fluvial, cortijos rodeados de plantaciones de frutos tropicales. Entorno y actividades: Desembocadura y vega baja del río Guadalfeo. Rutas de senderismo plano por los senderos fluviales de la vega tradicional de la caña de azúcar, caminatas agrícolas de interpretación de cultivos tropicales (chirimoyo, aguacate, mango), paseos llanos de cicloturismo familiar de relax por las llanuras litorales y ornitología en los humedales de la desembocadura. PROVINCIA: LEÓN (Texto Plano Limpio).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24116','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles de alta montaña construidos con sillería caliza y madera de roble, apartamentos rústicos con vistas a los macizos calcáreos y cabañas tradicionales de montaña. Cuenta con la mayor concentración de hórreos leoneses de tipo leonés y asturiano de la provincia. Entorno y actividades: En el corazón del Parque Nacional de los Picos de Europa (Vertiente Leonesa). Punto de partida oficial para la exigente y mítica vertiente leonesa de la Ruta del Cares. Destaca por el senderismo al Mirador del Tombo, ascensiones alpinas a las cumbres del Macizo Occidental (Torre de Santa María), paseos por el hayedo de Asotín y raquetas de nieve invernales.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90795','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales construidas en piedra de pizarra negra y madera de castaño típicas bercianas, pequeños hostales con encanto rodeados de viñedos y apartamentos para senderistas. Entorno y actividades: Custodia el Monumento Natural de Las Médulas (Patrimonio de la Humanidad), la mayor mina de oro a cielo abierto del Imperio Romano. Ofrece la ruta de senderismo de las Valiñas (caminata bajo castaños milenarios gigantes entre colosales picachos de arcilla roja), paseos fluviales por el Lago de Carucedo (humedal protegido ideal para la observación de aves acuáticas y piragüismo), y sendas micológicas.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90210','rural','Oferta de turismo rural','Alojamientos rurales: Pallozas tradicionales rehabilitadas (viviendas prerromanas de piedra con techumbre circular de paja de centeno), casas de turismo de aldea ancaresa aisladas en valles profundos y albergues de montaña. Entorno y actividades: En el corazón de la Reserva de la Biosfera de Los Ancares Leoneses. Entorno atlántico salvaje de aislamiento geográfico absoluto. Destaca por las rutas de senderismo alpino que ascienden al Pico Cuiña (1.987 metros) y al Miravalles, senderos bajo bosques autóctonos de acebos y robles, ríos trucheros cristalinos y territorio protegido del oso pardo ibérico. 📂 PROVINCIA: ZAMORA (Castilla y León - Datos Curados).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24209','rural','Oferta de turismo rural','Alojamientos rurales: Palacetes rurales barrocos e históricos vinculados a la nobleza berciana, hostales señoriales de paso para peregrinos del Camino de Santiago y casas de labranza entre viñedos de uva mencía. Entorno y actividades: Hito principal del Camino de Santiago Francés en León. Confluencia de los ríos Burbia y Valcarce. Ofrece rutas de senderismo fluvial, caminatas que ascienden hacia los sotos de castaños milenarios de Corullón, cicloturismo de carretera sin tráfico y paseos arqueológicos hacia el Castro celta de la Ventosa.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24130','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles de montaña con amplias cristaleras y vistas al lago de interior, apartamentos rústicos optimizados para montañeros y escaladores, y albergues fluviales. Entorno y actividades: Parque Regional de la Montaña de Riaño y Mampodre. Famoso por sus paisajes calcáreos que emulan los fiordos noruegos. Rutas de senderismo alpino de ascensión al Pico Gilbo (el Cervino leonés) y al Yordas, paseos náuticos y rutas de kayak en el Embalse de Riaño, avistamiento guiado de fauna ibérica salvaje (lobo ibérico, cabra montés, ciervos) y rutas de raquetas de nieve.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24145','rural','Oferta de turismo rural','Alojamientos rurales: Casonas solariegas de Babia con fachadas blanqueadas y escudos nobiliarios de piedra, hostales rurales de montaña y casas rurales unifamiliares con chimenea de leña rodeadas de prados alpinos altos. Entorno y actividades: Reserva de la Biosfera de Babia. Paisaje glaciar de valles abiertos y verdes siempre llanos donde pasta el caballo hispano-bretón de aptitud cárnica y la vaca asturiana de los valles. Espectaculares rutas de senderismo hacia la Laguna de Truchillas, caminatas de ascensión al Macizo de Ubiña meridional, senderos de pastores trashumantes, observación astronómica de cielos limpios nocturnos y micología de montaña.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24121','rural','Oferta de turismo rural','Alojamientos rurales: Hostales de alta montaña y apartamentos rústicos orientados al turismo de nieve e invernal, casas rurales de piedra y madera de pinar. Entorno y actividades: Parque Regional de la Montaña de Riaño, falda de la estación invernal de San Isidro. Destaca por el Monumento Natural de la Pinar de Lillo (uno de los pocos bosques relictos autóctonos de pino silvestre de la cordillera). Rutas de senderismo hacia el Lago Ausente, senderos micológicos en temporada de otoño y esquí alpino.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24137','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales integradas en antiguas colonias e instalaciones mineras industriales del siglo XIX rehabilitadas, apartamentos rústicos para turismo activo. Entorno y actividades: Valle del río Esla medio. El mayor hub de turismo activo y aguas bravas de la provincia; destaca por el Canal de Aguas Bravas de Sabero (sede de campeonatos de kayak y rafting). Rutas de senderismo por la Senda de las Minas, caminatas exigentes hacia las cumbres calizas de la Peña de la Valdoré, vías ferratas verticales y dehesas de escalada deportiva. PROVINCIA: HUELVA (Andalucía - Datos Curados).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24115','rural','Oferta de turismo rural','Alojamientos rurales: Casas de piedra de pizarra negra y madera unifamiliares integradas en un conjunto arquitectónico mozárabe medieval intacto (Peñalba de Santiago), apartamentos rurales de aislamiento absoluto en valles recónditos. Entorno y actividades: En el interior del Valle del Silencio y los Montes Aquilianos. Ofrece la espectacular ruta de senderismo circular del Valle del Silencio (sendero que transita bajo túneles vegetales umbríos siguiendo el río Oza hasta la cueva eremítica de San Genadio), caminatas de montaña hacia los picos Aquilianos, dehesas y senderos botánicos entre nogales y castaños, y micología.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24177','rural','Oferta de turismo rural','Alojamientos rurales: Casas de turismo rural tradicionales de montaña con muros anchos de mampostería, apartamentos rústicos junto a puentes medievales. Entorno y actividades: Alto Valle del Curueño, jalonado por calzadas romanas viejas. Rutas de senderismo histórico de la Calzada Romana de la Carisa oriental, caminatas espectaculares hacia las Cascadas de Nocedo de Curueño, pasarelas sobre el río en las Hoces de Valdeteja (desfiladero calizo estrecho brutal), pesca de trucha con pluma tradicional leonesa y senderos de raquetas.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90791','rural','Oferta de turismo rural','Alojamientos rurales: Cabañas forestales de piedra caliza, apartamentos rurales acogedores para familias y espeleólogos a pie de montaña. Entorno y actividades: Valle del río Torío alto. Nudo de acceso principal al Monumento Natural de la Cueva de Valporquero (colosal joya espeleológica mundial de estalactitas y río subterráneo activo transitable mediante turismo de aventura). Rutas senderistas de las Hoces de Vegacervera, caminatas geológicas entre lapiaces calcáreos gigantes y senderos micológicos de robledal.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24100','rural','Oferta de turismo rural','Alojamientos rurales: Confortables casonas de piedra con corredores tradicionales bercianos, albergues con encanto y apartamentos rurales de paso jacobeo. Entorno y actividades: Entrada al Bierzo desde los Montes de León, bañado por el río Meruelo. Ofrece el Camino de Santiago Francés. Destaca por su monumental playa fluvial natural integrada en el puente romano del pueblo ideal para el baño en verano, rutas de senderismo hacia las Fragas del río Meruelo bajo bosques de castaños y robles, y rutas cicloturistas.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24194','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales de piedra de mampostería tradicional serrana leonesa, apartamentos rústicos pequeños orientados al turismo activo de montaña. Entorno y actividades: Custodia el Monumento Natural de las Hoces de Vegacervera. Espectaculares rutas de senderismo vertical que transitan entre paredes calizas verticales de más de 100 metros esculpidas por el río Torío, caminatas que ascienden a los altos de las muelas calcáreas, escalada clásica en roca caliza de primer nivel, pesca y rutas micológicas.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24101','rural','Oferta de turismo rural','Alojamientos rurales: Casas de labranza tradicionales de Omaña con corrales de losa de piedra oscura de esquisto, apartamentos rurales aislados en valles ganaderos. Entorno y actividades: Reserva de la Biosfera de los Valles de Omaña y Luna. Rutas de senderismo de media montaña que recorren dehesas ganaderas de abedules autóctonos viejos (Abidulal de Murias), caminatas llanas por cañadas y senderos ganaderos tradicionales, observación de fauna cantábrica (territorio de urogallo y oso pardo en umbrías) y micología.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24172','rural','Oferta de turismo rural','Alojamientos rurales: Casas de piedra y pizarra tradicionales cabreiresas de aislamiento de montaña alta con chimeneas rústicas de suelo, pequeños hostales de campo de interior. Entorno y actividades: Sierra de la Cabrera alta, cuenca del río Eria. Alberga el Monumento Natural del Lago de Truchillas (espectacular lago de origen glaciar rodeado de circos de roca). Rutas de senderismo exigentes de alta montaña, caminos pastoriles altos entre brezos y escobas, pesca truchera limpia en ríos vírgenes y senderos de interpretación del aislamiento cabreirés.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24202','rural','Oferta de turismo rural','Alojamientos rurales: Casonas de labranza tradicionales de Laciana rehabilitadas, apartamentos rústicos forestales e instalaciones ligadas al agroturismo ganadero de montaña. Entorno y actividades: Reserva de la Biosfera de Laciana. Rutas de senderismo forestal por el sendero del Brañallín, caminatas hacia las brañas ganaderas de altura con cabañas tradicionales de piedra ("teitos" menores), dehesas agrícolas de pasto, rutas cicloturistas por la Vía Verde de Laciana (antiguo trazado minero plano ideal para familias) y avistamiento de oso pardo. PROVINCIA: NAVARRA - VALLES ATLÁNTICOS Y PIRENAICOS (Texto Plano Limpio).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26011','rural','Oferta de turismo rural','Alojamientos rurales: Casas de campo agrícolas tradicionales bajas independientes de la ribera del río Esla, pequeños hoteles de interior de paso en el casco fortificado de adobe. Entorno y actividades: Llanura y ribera del río Esla bajo, Camino de Santiago Francés. Rutas de senderismo plano por los senderos fluviales de las dehesas del Esla, caminatas agrícolas llanas ideales para cicloturismo familiar de relax por las cañadas reales de la meseta leonesa, pesca fluvial y ornitología en tablas de agua. PROVINCIA: GIRONA (Texto Plano Limpio).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17178','rural','Oferta de turismo rural','Alojamientos rurales: Masías tradicionales ampurdanas rehabilitadas de piedra, pequeños complejos de ecoturismo rural y fincas de agroturismo frutal. Entorno y actividades: Ubicado plenamente en el Parque Natural dels Aiguamolls de l''Empordà. Destaca por las rutas llanas de senderismo y cicloturismo que bordean el curso final del río Fluvià, observación ornitológica masiva en las marismas y lagunas protegidas, y paseos botánicos por dunas salvajes costeras.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18004','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles de montaña de estética alpina, chalets rústicos de piedra y madera, y casas de turismo rural de alquiler íntegro con chimenea en valles verdes. Entorno y actividades: Eje principal del Valle de Camprodon en el Pirineo Oriental. Punto de partida para el senderismo de alta montaña y alpinismo (ascensión al pico Costabona), rutas botánicas entre frondosos robledales, rutas de raquetas de nieve e invernales en la estación de Vallter 2000, y senderos micológicos de Pirineo.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17184','rural','Oferta de turismo rural','Alojamientos rurales: Auténticas casas de payés vinculadas al agroturismo tradicional, alojamientos rurales familiares con huerto ecológico y granjas rodeadas de campos volcánicos. Entorno y actividades: En el corazón del Parque Natural de la Zona Volcánica de la Garrotxa. Sede de rutas de senderismo directas al Volcán de Santa Margarida (con su ermita en el centro del cráter) y al Volcán del Croscat. Ofrece paseos icónicos por el hayedo de la Fageda d''en Jordà (crecido de forma única sobre una colada de lava), rutas ecuestres de colina y micología.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18002','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles boutique de ambientación medieval integrados en el casco histórico de piedra, posadas con encanto de cara al río Fluvià y masías aisladas. Entorno y actividades: Entrada oriental a la comarca de La Garrotxa. Ofrece rutas de senderismo fluvial a lo largo del cauce del río Fluvià, caminos tradicionales de herradura que conectan con dehesas y colinas boscosas, y paseos de interpretación botánica y patrimonial románica.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17145','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles rurales de montaña con instalaciones de spa, pequeños apartamentos rústicos optimizados para montañeros y albergues de naturaleza pirenaica. Entorno y actividades: Confluencia de los ríos Rigard, Freser y Segadell, y nexo con el tren cremallera que sube al Valle de Nuria. Destaca por el senderismo alpino de alta exigencia, rutas que ascienden al Puigmal (2.914 metros), dehesas de alta montaña, vías ferratas de escalada deportiva en roca caliza, observación de fauna alpina (isards) y deportes de nieve.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17046','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales integradas en construcciones de roca volcánica basáltica, pequeños hostales de montaña y apartamentos rústicos con vistas al acantilado. Entorno y actividades: Asentado de forma espectacular sobre un risco de basalto de 50 metros de altura esculpido por los ríos Fluvià y Toronell. Ofrece rutas de senderismo geológico por la base del desfiladero basáltico, paseos botánicos por huertos tradicionales de ribera y senderos forestales de La Garrotxa baja.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18001','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles boutique rurales en antiguas casas de indios coloniales, apartamentos rústicos de costa y masías de piedra reformadas rodeadas de pinos. Entorno y actividades: Combinación de turismo costero, forestal y rural en el Macizo de Begur. Sede de los senderos litorales de los Caminos de Ronda (Camins de Ronda), caminatas que cruzan densos bosques de pinos piñoneros piñoneros que mueren en calas salvajes (Sa Riera, Aiguablava), snorkel y kayak de mar en la reserva marina de Ses Negres.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18015','rural','Oferta de turismo rural','Alojamientos rurales: Hostales tradicionales de alta montaña de piedra vista y madera caliza, casas rústicas de alquiler íntegro con grandes chimeneas y estufas de leña. Entorno y actividades: Pueblo pirenaico de alta montaña. Destaca por la exigente ruta de senderismo hacia el nacimiento del río Ter en el circo glaciar de Ulldeter, caminatas alpinas fronterizas con Francia, turismo de nieve invernal en la estación de Vallter 2000 y recolección micológica extrema en bosques de pino negro.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17032','rural','Oferta de turismo rural','Alojamientos rurales: Casas de pescadores encaladas rehabilitadas como hoteles con encanto mediterráneo, y masías rústicas aisladas en campos de olivos. Entorno y actividades: En el interior del Parque Natural del Cap de Creus. Rutas de senderismo indómito entre acantilados de pizarra negra esculpidos por el viento de Tramontana, caminos de piedra seca tradicionales que conducen al Faro de Cap de Creus, observación de geología pura y kayak de mar en calas rocosas vírgenes.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17114','rural','Oferta de turismo rural','Alojamientos rurales: Grandes masías señoriales solariegas de agroturismo en la periferia, y hoteles de naturaleza de interior con certificación eco-sostenible. Entorno y actividades: Capital de La Garrotxa rodeada por cuatro volcanes extintos. Ofrece el inicio de las Vías Verdes cicloturistas (Ruta del Carrilet), paseos de interpretación ecológica por los humedales boscosos de la Moixina, rutas botánicas por el Volcán Montsacopa y senderos micológicos.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90595','rural','Oferta de turismo rural','Alojamientos rurales: Masías rurales de aislamiento absoluto en la montaña alta, apartamentos rústicos con chimenea de leña rodeados de densas pinadas. Entorno y actividades: Espacio de Interés Natural de la Alta Garrotxa y el curso alto del río Muga. Es el primer parque internacional certificado como campamento astronómico y de observación de estrellas (Cielo Starlight de máxima pureza). Rutas de senderismo por las pozas naturales y aguas turquesas del río Muga, senderos forestales salvajes de encinares y quejigales, y rutas de aislamiento. PROVINCIA: CÁCERES - VALLES Y GARGANTAS DE MONTAÑA (Texto Plano Limpio).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17124','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales integradas en un casco histórico gótico medieval de piedra dorada intacto, posadas agrícolas de campiña. Entorno y actividades: Comarca del Baix Empordà. Rutas de senderismo plano y cicloturismo familiar a lo largo de las dehesas agrícolas de los arrozales de Pals, paseos botánicos por las dunas protegidas y pinares de la playa de Pals, y ornitología en los humedales linderos del río Ter.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08021','rural','Oferta de turismo rural','Alojamientos rurales: Casas de turismo rural tradicionales de piedra y madera vinculadas a valles prepirenaicos, apartamentos rústicos junto al río. Entorno y actividades: Valle del río Ter medio. Conectado por la Vía Verde de la Ruta del Ferro i del Carbó (trazado plano ideal para cicloturismo familiar). Rutas de senderismo micológico por los bosques de los alrededores, paseos fluviales entre puentes medievales de piedra y caminatas de media montaña.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17102','rural','Oferta de turismo rural','Alojamientos rurales: Casas de labranza tradicionales de montaña del Alt Empordà alto, apartamentos rústicos con jardín y barbacoa independientes. Entorno y actividades: Vertiente sur de los Pirineos, comarca de las Salines-Bassegoda. Destaca por las rutas de senderismo forestal entre inmensos bosques de castaños, robles y alcornoques, caminatas hacia el Santuario de las Salines, senderos micológicos de otoño y rutas cicloturistas exigentes de montaña (BTT).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90610','rural','Oferta de turismo rural','Alojamientos rurales: Apartamentos rurales de playa de pizarra costera, pequeñas casas de campo aisladas en los valles del interior del cabo. Entorno y actividades: Nudo costero norte de transición al Parque Natural del Cap de Creus y la Albera. Rutas de senderismo exigentes que ascienden hacia el Monasterio medieval de Sant Pere de Rodes (colosal monumento románico con vistas de pájaro sobre el mar abierto), Caminos de Ronda costeros y kayak de mar.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17116','rural','Oferta de turismo rural','Alojamientos rurales: Casas de montaña tradicionales de mampostería fluvial oscura aisladas bajo densos bosques, albergues de naturaleza de interior. Entorno y actividades: En el corazón del indómito Macizo de las Guilleries. Paisaje boscoso frondoso de humedad extrema. Rutas de senderismo que siguen la riera de Osor entre pozas naturales de agua limpia, senderos micológicos de primer nivel (recogida de castañas y setas), cicloturismo de montaña y rutas de aislamiento.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17086','rural','Oferta de turismo rural','Alojamientos rurales: Masías de montaña rústicas de piedra caliza de río independientes de interior, pequeños refugios forestales en parajes de frontera. Entorno y actividades: Custodia el Paraje Natural de Interés Nacional de la Albera. Ofrece la espectacular ruta de senderismo boscoso que asciende al Castillo de Requesens rodeado de densos alcornocales y hayedos mediterráneos de altura, senderos megalíticos con dólmenes y menhires prehistóricos y ornitología. PROVINCIA: CANTABRIA (Texto Plano Limpio).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23028','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles de montaña rústicos de piedra y madera, casas de pueblo tradicional andaluz con chimeneas de leña encaladas y complejos de turismo activo a las faldas del castillo de la Yedra. Entorno y actividades: Puerta natural del Parque Natural de las Sierras de Cazorla, Segura y Las Villas. Destaca por el sendero circular del río Cerezuelo, la proximidad al Nacimiento del Río Guadalquivir en la Cañada de las Fuentes, senderismo de alta montaña en el entorno del Gilillo y rutas de avistamiento de grandes ungulados y aves rapaces.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23081','rural','Oferta de turismo rural','Alojamientos rurales: Casas de turismo rural intramuros enclavadas en un casco histórico medieval empinado intacto, apartamentos rústicos con vistas panorámicas al mar de olivos y cabañas de alta montaña. Entorno y actividades: Municipio enriscado a más de 1.100 metros de altitud en la Sierra de Segura profunda. Destaca por las rutas de senderismo hacia el Yelmo (epicentro nacional del vuelo libre en parapente), paseos micológicos en los frondosos pinares laricios de alta montaña, senderos ecuestres e interpretación de la fauna silvestre.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23047','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles rurales con encanto rústico colgados de los riscos calizos, chalets de montaña independientes con piscina y alojamientos integrados en las pedanías del corazón del Parque (como Arroyo Frío o Burunchel). Entorno y actividades: Custodia los espectaculares cortados donde se asienta su fotogénico castillo templario. Sede de la gran ruta de senderismo de la Cerrada del Utrero (espectacular cañón calizo del río Guadalquivir joven con cascadas de toba), la ruta del río Borosa (desfiladero fluvial con pasarelas de madera y pozas turquesas como el Charco de la Cuna) y piragüismo en el embalse del Tranco.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23043','rural','Oferta de turismo rural','Alojamientos rurales: Casas de cal de pueblo andalusí de alquiler íntegro con miradores directos al embalse, apartamentos rústicos pequeños de piedra caliza y posadas serranas tradicionales. Entorno y actividades: Asentado sobre una colosal muela de roca que vigila el Embalse del Tranco de Beas. Ofrece rutas de senderismo que bordean el gran lago de interior, piragüismo y barcos solares de recreo, senderos micológicos de pinar húmedo alto, y es una zona de máxima pureza para la observación astronómica nocturna con certificación Starlight.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24005','rural','Oferta de turismo rural','Alojamientos rurales: Grandes cortijos ganaderos y agrícolas con encanto andaluz serrano, fincas de montería con picaderos de caballos y casas de campo independientes rodeadas de pinos piñoneros. Entorno y actividades: En el corazón del Parque Natural de la Sierra de Andújar. La meca internacional absoluta para el rastreo guiado y avistamiento fotográfico del Lince Ibérico en libertad. Ofrece la ruta senderista del Santuario de la Virgen de la Cabeza, paseos fluviales por las dehesas de encinas maduras del río Jándula y observación del águila imperial ibérica.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24012','rural','Oferta de turismo rural','Alojamientos rurales: Casas de labranza tradicionales de piedra de cantería con patios andaluces rústicos, palacetes de interior con encanto y apartamentos rurales de campiña alta. Entorno y actividades: Estribaciones de Sierra Morena, a las orillas del Embalse de Rumblar. Ofrece rutas de senderismo arqueológico hacia el yacimiento de la Edad del Bronce de Peñalosa, paseos llanos que rodean su imponente castillo omeya del siglo X (el más antiguo conservado de Europa), kayak de interior en el embalse, y observación del cielo negro Starlight.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23904','rural','Oferta de turismo rural','Alojamientos rurales: Casas de pastores de alta montaña de piedra gruesa con chimeneas rústicas de suelo, pequeños hostales de montaña aislados de la civilización y alojamientos de ecoturismo ganadero. Entorno y actividades: Altiplano y cañones de la Sierra de Segura alta, uno de los municipios más extensos y despoblados. Sede de la espectacular ruta senderista del Nacimiento del Río Segura (donde brota el agua a presión desde una colosal gruta kárstica inundada), senderismo hacia los campos de Hernán Perea (estepa alpina caliza única en el sur peninsular), y senderos pastoriles de trashumancia.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23018','rural','Oferta de turismo rural','Alojamientos rurales: Cortijos unifamiliares de montaña con parcelas amplias de frutales, apartamentos rústicos con chimenea de leña y hostales especializados en montañeros. Entorno y actividades: En pleno Parque Natural de Sierra Mágina. Destaca por las rutas de senderismo de alta montaña que ascienden al pico Mágina (el techo de la provincia con 2.165 metros de altitud), caminatas bajo los raros y protegidos bosques de adelfas de Cuadros y dehesas de cornicabras, y rutas micológicas de otoño.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23073','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales andaluzas de cal blanca de alquiler íntegro vinculadas al agroturismo olivarero, apartamentos rústicos de montaña. Entorno y actividades: Vertiente sur de la Sierra de Cazorla. Custodia el Monumento Natural de la Cueva del Agua de Tíscar (colosal gruta caliza natural donde el río se desborda en cascadas interiores rugientes). Rutas de senderismo hacia el santuario de Tíscar, paseos botánicos entre olivares de sierra y dehesas mediterráneas viejas de encina.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23044','rural','Oferta de turismo rural','Alojamientos rurales: Casonas solariegas de sillería dorada con amplios jardines y huertos tradicionales, apartamentos de turismo de montaña rústicos. Entorno y actividades: Cara sur de Sierra Mágina. Rutas senderistas de interpretación botánica que exploran los lapiaces calcáreos altos, caminatas hacia los pinsapares de repoblación viejos en el barranco del Gualijar, recolección de setas en temporada en quejigales y senderos ganaderos tradicionales de montaña.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23082','rural','Oferta de turismo rural','Alojamientos rurales: Apartamentos tradicionales de montaña con acabados en madera de pino, casas rurales familiares independientes junto a riachuelos trucheros limpias y cabañas de pinar. Entorno y actividades: Extremo norte de la Sierra de Segura, frontera con Albacete. Rutas de senderismo hacia el paraje de la Peña del Olivar, caminatas exigentes de ascensión a la Cambrón, senderos micológicos otoñales extremos bajo densos bosques de pino negral y paseos fluviales por el río Guadalimar joven.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24013','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales de pueblo tradicionales de interior, apartamentos rústicos acogedores para familias y grupos pequeños y alojamientos vinculados a huertos. Entorno y actividades: Piedemonte de la Sierra de Segura. Rutas de senderismo que siguen la Senda del río Beas bajo túneles vegetales umbríos de alisos, caminatas micológicas por las lomas linderas forestales, paseos fotográficos de olivares de campiña y cicloturismo de carretera sin tráfico.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24086','rural','Oferta de turismo rural','Alojamientos rurales: Complejos de cabañas y casas de piedra rústica con techos de vigas de madera, fincas de montaña aisladas rodeadas de cerezos de altura. Entorno y actividades: En un anfiteatro natural de roca en Sierra Mágina alta. Célebre por el espectáculo botánico primaveral de la floración del cerezo en sus valles. Rutas de senderismo de ascensión al pico Almadén, caminatas por el sendero del Fuenmayor con cascadas y manantiales limpios de montaña, y rutas cicloturistas de montaña (BTT).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23076','rural','Oferta de turismo rural','Alojamientos rurales: Cabañas forestales integradas bajo encinares, hostales rurales especializados en turismo de paso e histórico y apartamentos rústicos de pinar. Entorno y actividades: Custodia el Parque Natural de Despeñaperros. Sede de las colosales formaciones geológicas de "Los Órganos de Despeñaperros" (paredes verticales de cuarcita espectaculares cortadas por la fractura de la falla). Rutas de senderismo hacia el barranco de la Valdeazores, senderos hacia las pinturas rupestres prehistóricas del Collado de los Jardines y avistamiento de ciervos.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23053','rural','Oferta de turismo rural','Alojamientos rurales: Casas de labranza tradicionales de campiña baja de mampostería estrecha, posadas con encanto rural andaluz e interior. Entorno y actividades: Falda norte de Sierra Mágina y vega del río Guadalquivir medio. Rutas de senderismo hacia el paraje natural de los espartales de Jódar, caminatas de interpretación etnográfica e histórica rodeando su torre de la Alhabia del siglo XIII, paseos fluviales por el río Jandulilla y senderos entre olivares de pendiente.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23094','rural','Oferta de turismo rural','Alojamientos rurales: Casas de campo agrícolas y de dehesa bajas de interior independientes, apartamentos rurales sencillos junto a zonas fluviales. Entorno y actividades: Entorno de la confluencia de los ríos Guadalén y Guarrizas, y rodeado por tres embalses (Guadalén, Giribaile y La Fernandina). Rutas de senderismo plano de ribera fluvial, dehesas agrarias donde pasta el ganado, paseos en piragua o kayak náutico de interior, pesca deportiva y observación ornitológica de aves acuáticas en tablas de agua. PROVINCIA: MÁLAGA (Texto Plano Limpio).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29084','rural','Oferta de turismo rural','Alojamientos rurales: Cortijos andaluces señoriales rodeados de olivares y viñedos, hoteles rurales boutique en fincas de agroturismo y antiguas casas de piedra de la serranía rehabilitadas con chimenea de leña. Entorno y actividades: Centro logístico y natural de la Serranía de Ronda y nexo con la Sierra de las Nieves. Destaca por las rutas de senderismo que descienden al fondo del Tajo de Ronda siguiendo el río Guadalevín, vías ferratas verticales en las paredes del desfiladero, senderos que cruzan encinares maduros de la comarca y rutas enológicas en sus bodegas de interior.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32025','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales integradas en fincas de cítricos y olivos, complejos orientados al turismo activo y de escalada y apartamentos rústicos con vistas a los cañones fluviales. Entorno y actividades: Entorno del Paraje Natural Desfiladero de los Gaitanes. Co-propietario de la entrada al célebre sendero del Caminito del Rey (espectacular pasarela aérea de madera anclada a 100 metros de altura sobre las paredes verticales del cañón del río Guadalhorce). Destaca por el senderismo geológico, escalada deportiva de primer nivel en El Chorro y kayak en los embalses linderos de Guadalteba.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32002','rural','Oferta de turismo rural','Alojamientos rurales: Haciendas agrícolas tradicionales andaluzas de gran porte, antiguos molinos de aceite reconvertidos en hoteles con encanto y casas de campo de llanura alta con amplios porches rústicos. Entorno y actividades: Custodia el espectacular Paraje Natural de El Torcal de Antequera (Patrimonio de la Humanidad por la UNESCO), uno de los paisajes kársticos de roca caliza más impresionantes y fotogénicos de Europa. Rutas senderistas señalizadas (Ruta Verde y Amarilla) entre callejones y figuras de piedra modeladas por la erosión, observación de cabra montés, avistamiento ornitológico de rapaces y rutas históricas hacia los Dólmenes prehistóricos de Antequera.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29090','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles y posadas rurales vinculados al termalismo histórico de su balneario, casas tradicionales blancas de pueblo serrano con patios y apartamentos de montaña independientes. Entorno y actividades: Puerta de entrada oficial al Parque Nacional Sierra de las Nieves. Sede de rutas de senderismo alpino de alta exigencia que ascienden al pico Torrecilla (el techo del parque con 1.919 metros de altitud). Ofrece paseos botánicos únicos por los misteriosos bosques relictos de Pinsapos (abetos de la era glaciar), caminatas por el sendero de las Cascadas y rutas de observación de fauna de alta montaña.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29053','rural','Oferta de turismo rural','Alojamientos rurales: Casas de pueblo andalusí de cal impecable con azulejos y macetas de flores, pequeños apartamentos rurales de colina con vistas a la sierra y el mar mediterráneo lejano. Entorno y actividades: En el interior del Parque Natural de las Sierras de Tejeda, Almijara y Alhama. Sede de la espectacular ruta de senderismo del Río Chíllar (caminata fluvial que transita por el cauce del agua dentro de estrechos cañones calizos conocidos como "Cahorros"), senderos micológicos de pinar y quejigal alto en la Axarquía, y rutas ecuestres de montaña.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32004','rural','Oferta de turismo rural','Alojamientos rurales: Complejos de cabañas forestales de madera, apartamentos rurales adaptados para familias y deportistas de aventura, y casas rurales aisladas junto a pinares. Entorno y actividades: Entorno de los Embalses del Guadalhorce y el Desfiladero de los Gaitanes. Nudo de acceso principal al recorrido del Caminito del Rey. Destaca por el senderismo botánico por la dehesa de Ardales, caminatas arqueológicas hacia la Cueva de Ardales (pinturas rupestres prehistóricas integradas en la naturaleza), piragüismo, vela y dehesas náuticos sin motor en el embalse del Conde de Guadalhorce. PROVINCIA: LEÓN (Castilla y León - Datos Curados).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29100','rural','Oferta de turismo rural','Alojamientos rurales: Casas de labranza tradicionales serranas vinculadas al agroturismo de castaños y vides, posadas con chimeneas rústicas y apartamentos turísticos de alta montaña. Entorno y actividades: En pleno Parque Nacional Sierra de las Nieves. Destaca por albergar el mirador de Luis Ceballos. Rutas de senderismo bajo inmensos bosques de pinsapos y densos castañares que tiñen el paisaje en otoño, caminatas que conectan con los senderos que suben a la meseta caliza alta de Quejigales y observación astronómica de cielos negros certificados.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29045','rural','Oferta de turismo rural','Alojamientos rurales: Villas rurales independientes colgadas de lomas escarpadas con piscinas, casas tradicionales de la Axarquía encaladas y hostales orientados al turismo de caminata internacional. Entorno y actividades: Parque Natural de las Sierras de Tejeda, Almijara y Alhama, en la Axarquía montañosa. Punto de partida principal para la exigente ascensión a pie al pico de La Maroma (techo de la provincia de Málaga con 2.066 metros de altitud). Senderos de interpretación geológica entre lapiaces calizos secos, rutas de cicloturismo de carretera de gran pendiente y turismo gastronómico-rural vinculado a sus viñedos de uva moscatel emparrados.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29046','rural','Oferta de turismo rural','Alojamientos rurales: Casas de campo de piedra y teja rodeadas de encinares maduros, apartamentos rurales unifamiliares con porche de leña y hostales de montaña. Entorno y actividades: Valle del río Guadiaro, enclavado entre el Parque Natural de Los Alcornocales y Grazalema. Destaca por las rutas de senderismo del Cañón de las Buitreras (un colosal y estrecho Monumento Natural fluvial con paredes verticales de roca donde anida una inmensa colonia de buitres leonados), senderos bajo densos alcornocales húmedos y paseos micológicos otoñales.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29076','rural','Oferta de turismo rural','Alojamientos rurales: Eco-lodges de diseño sostenible integrados en la dehesa mediterránea, casas rurales unifamiliares tranquilas y pequeños hoteles con encanto rústico. Entorno y actividades: Vertiente sur de la Sierra de las Nieves (Sierra Blanca). Ofrece la ruta de senderismo del Sendero de Juanar, caminatas botánicas bajo frondosos alcornocales y olivares de montaña, paseos hacia el Refugio de Juanar, observación de fauna ibérica (cabra montés) y rutas cicloturistas de montaña (BTT).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29041','rural','Oferta de turismo rural','Alojamientos rurales: Fincas ganaderas andaluzas con casas de labranza tradicionales encaladas, apartamentos rústicos a la sombra de su castillo enriscado y alojamientos con encanto. Entorno y actividades: Paraje Natural de Sierra Crestellina y transición al Campo de Gibraltar. Destaca por el sendero de los Arroyos, caminatas de observación ornitológica de grandes aves rapaces (colonia protegida de buitre leonado anidando frente a la costa del Mediterráneo), senderos geológicos en riscos calizos y baños de agua dulce mineromedicinal en los Baños de la Hedionda (baños romanos al aire libre).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32003','rural','Oferta de turismo rural','Alojamientos rurales: Cortijos andaluces señoriales con amplias fincas olivareras, casas de labranza tradicionales de campiña alta con patios interiores de vigas y azulejos. Entorno y actividades: Comarca de Nororma, entorno de las lagunas de Archidona. Ofrece las rutas de senderismo que suben a la Ermita de la Virgen de Gracia (santuario rodeado de pinares de repoblación viejos y restos de murallas islámicas), paseos de observación ornitológica en la Reserva Natural de las Lagunas de Archidona, y senderos llanos de cicloturismo de campiña.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29063','rural','Oferta de turismo rural','Alojamientos rurales: Apartamentos tradicionales de la serranía de Ronda con acabados en madera de castaño, casas rurales pequeñas e independientes junto a la estación de tren rural y cabañas de madera forestales. Entorno y actividades: Valle del río Guadiaro, Parque Natural de Grazalema bajo. Destaca por el Sendero del Guadiaro (itinerario de senderismo fluvial paralelo a la vía del ferrocarril que conecta con Benaoján), piragüismo fluvial, kayak y descenso de ríos en aguas limpias de montaña, y senderos micológicos de encinar húmedo.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29028','rural','Oferta de turismo rural','Alojamientos rurales: Casas de pueblo tradicionales serranas de mampostería estrecha, apartamentos rústicos acogedores para familias y espeleólogos cerca de las estaciones fluviales. Entorno y actividades: Serranía de Ronda kárstica. Custodia la imponente Cueva del Gato (Monumento Natural célebre por su colosal boca de roca de la que brota un río de agua helada y cristalina en forma de cascada y poza natural apta para el baño veraniego) y la Cueva de la Pileta (pinturas rupestres prehistóricas). Rutas senderistas de montaña y paseos fluviales por el Guadiaro.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29056','rural','Oferta de turismo rural','Alojamientos rurales: Casonas serranas heráldicas cuidadas con miradores que divisan el Estrecho de Gibraltar, casas de cal de pueblo andaluz independientes y apartamentos rurales de montaña. Entorno y actividades: Crestas de la Serranía de Ronda, bajo el castillo del Águila. Espectaculares rutas de senderismo que descienden hacia el cañón del río Genal, caminatas por densos alcornocales y dehesas de monte mediterráneo, vías ferratas de montaña de gran dificultad para escaladores y observación astronómica de cielos negros.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29057','rural','Oferta de turismo rural','Alojamientos rurales: Casas tradicionales alpujarreñoserranas de mampostería gruesa y cal de aislamiento de montaña, apartamentos rurales pequeños integrados en un pueblo-museo. Entorno y actividades: En el corazón del indómito y frondoso Valle del Genal. El municipio destaca por fusionar el senderismo con el arte moderno al aire libre (esculturas contemporáneas integradas en los callejones e itinerarios de naturaleza del pueblo). Rutas por el sendero del río Genal cruzando pasarelas fluviales, caminatas bajo castañares centenarios y senderos micológicos.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29032','rural','Oferta de turismo rural','Alojamientos rurales: Casas de campo agrícolas y de dehesa bajas de interior independientes, apartamentos rurales sencillos en el llano de la cuenca. Entorno y actividades: Entorno de la Reserva Natural de las Lagunas de Campillos. Rutas de senderismo plano de alta observación ornitológica de aves acuáticas y palustres (flamencos, cigüeñuelas) en su complejo endorreico de lagunas estacionales, senderos llanos de cicloturismo familiar de relax por las cañadas reales de campiña alta, y cercanía al embalse de Guadalhorce. PROVINCIA: CÁCERES (Texto Plano Limpio).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10087','rural','Oferta de turismo rural','Alojamientos rurales: Parador nacional en antiguo hospital medieval, hospederías reales de paso históricas, casas de turismo rural de arquitectura tradicional serrana con soportales de madera y piedra caliza. Entorno y actividades: En el corazón del Geoparque Villuercas-Ibores-Jara. Destaca por la ruta de senderismo del Desfiladero del Río Ruecas, la ascensión al pico de Las Villuercas (vistas de pájaro de las rañas geológicas), paseos botánicos por el Castañar de la Vizcaína con ejemplares centenarios protegidos y senderos micológicos de montaña.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10195','rural','Oferta de turismo rural','Alojamientos rurales: Palacios rurales reconvertidos en hoteles boutique dentro del recinto amurallado, antiguas casas señoriales hidalgas y fincas de dehesa extremeña destinadas al agroturismo ganadero. Entorno y actividades: Entorno de la penillanura trucocacereña y transición a Monfragüe. Ofrece rutas de senderismo plano y cicloturismo por los Berrocales de Trujillo (espectacular paisaje de colosales bolas de granito), paseos de interpretación ambiental por encinares maduros donde se cría el cerdo ibérico, y observación de avifauna esteparia.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10107','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales de montaña de piedra y adobe típicas del valle, hostales rústicos con terrazas sobre el río Jerga y pequeños apartamentos vacacionales rodeados de fincas de cerezos. Entorno y actividades: Custodia la entrada principal a la Reserva Natural de la Garganta de los Infiernos. Célebre por la ruta de senderismo de Los Pilones (espectaculares marmitas de gigante o pozas naturales excavadas por la erosión fluvial en la roca de granito liso aptas para el baño). Ofrece el sendero de las cascadas de las Nogaledas, rutas de alta montaña alpina hacia el puerto de Tornavacas y espectaculares paisajes fotográficos de floración en primavera.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10105','rural','Oferta de turismo rural','Alojamientos rurales: Parador nacional emplazado en el imponente castillo-palacio de los Condes de Oropesa, casas de piedra de labranza tradicionales veratas con entramados de madera oscura y apartamentos rústicos junto a arroyos forestales. Entorno y actividades: Vertiente sur de la Sierra de Gredos occidental, en la comarca de La Vera. Destaca por las rutas de senderismo fluvial hacia la Garganta de Jaranda, pozas de agua helada de deshielo cristalina de montaña ideales para el descanso estival, senderos que conectan con el Monasterio de Yuste bajo densos robledales, caminatas de dehesa extremeña y micología otoñal.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10096','rural','Oferta de turismo rural','Alojamientos rurales: Casas de turismo rural integradas en su judería (Conjunto Histórico), apartamentos rústicos con chimenea de leña rodeados de castañares viejos y complejos de cabañas forestales de madera de castaño. Entorno y actividades: Valle del Ambroz húmedo, falda de la Sierra de Béjar. Alberga el espectacular paraje natural del Castañar de Hervás (uno de los bosques de castaños mejor conservados del suroeste peninsular). Rutas de senderismo de la Chorrera de Hervás (cascada de montaña), cicloturismo de gran recorrido por la Vía Verde de la Plata (antiguo trazado de tren) y senderos micológicos extremos de otoño.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10175','rural','Oferta de turismo rural','Alojamientos rurales: Casas de pueblo tradicionales de dehesa de alquiler íntegro con chimeneas rústicas, apartamentos de turismo de interior y alojamientos ecoturísticos rurales de aislamiento. Entorno y actividades: En el interior del Parque Nacional de Monfragüe y Reserva de la Biosfera. La meca europea absoluta para el turismo ornitológico y observación fotográfica de aves rapaces calcícolas y forestales. Ofrece rutas de senderismo hacia el imponente Salto del Gitano (colosal farallón de roca cuarcita cortado sobre el río Tajo donde anida el buitre negro, águila imperial y cigüeña negra) y paseos fluviales por el Jaráiz.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10203','rural','Oferta de turismo rural','Alojamientos rurales: Cortijos extremeños señoriales con amplias fincas arboladas rústicas, chozos tradicionales de pastores circulares de piedra adaptados para pernocta de lujo, y casas de campo independientes. Entorno y actividades: Sierra de San Pedro meridional, frontera con Portugal. Posee uno de los conjuntos megalíticos prehistóricos más importantes de Europa. Rutas de senderismo de la Senda de los Dólmenes (recorrido que visita decenas de dólmenes de granito bien conservados integrados en dehesas), caminatas por alcornocales maduros, senderos micológicos y observación de la berrea del ciervo.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10108','rural','Oferta de turismo rural','Alojamientos rurales: Casas de piedra de pizarra negra y losa tradicionales hurdanas de aislamiento de montaña, apartamentos rústicos con porche de leña en alquerías pequeñas (como Riomalo de Arriba o Cabezo). Entorno y actividades: Comarca de Las Hurdes altas, un paisaje abrupto de valles estrechos. Sede de rutas de senderismo botánico que siguen los meandros encajonados de los ríos locales, caminatas hacia los saltos de agua ocultos como el Chorro de la Meancera, dehesas forestales menores, senderos micológicos de quejigal húmedo y rutas de aislamiento geológico puro. PROVINCIA: CANTABRIA - VALLES ATLÁNTICOS Y MONTAÑA (Texto Plano Limpio).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10041','rural','Oferta de turismo rural','Alojamientos rurales: Complejos de turismo de interior de piedra y pizarra orientados a grupos, apartamentos de montaña independientes rodeados de dehesas ganaderas menores y hostales rurales. Entorno y actividades: Las Hurdes bajas, entorno del río Alagón. Destaca por la proximidad al espectacular Meandro del Melero (colosal y fotogénico giro cerrado del río en forma de herradura sobre la vegetación de pinos). Rutas de senderismo hacia miradores paisajísticos, caminatas fluviales por las piscinas naturales del pueblo y rutas cicloturistas de montaña (BTT).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10079','rural','Oferta de turismo rural','Alojamientos rurales: Casas de pueblo tradicionales veratas de cal, barro y madera con balcones volados floridos (Conjunto Histórico), apartamentos rústicos con chimenea. Entorno y actividades: Comarca de La Vera, desfiladeros calizos y de granito de la Sierra de Tormantos. Sede de la espectacular ruta de las Piletas y las Ollas (pozas naturales circulares de agua cristalina labradas en el lecho de roca de la garganta mayor ideales para el baño veraniego), caminatas bajo robledales y castañares viejos, y rutas ecuestres de montaña.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10068','rural','Oferta de turismo rural','Alojamientos rurales: Casonas solariegas de sillería de piedra con escudos heráldicos, alojamientos rurales integrados en antiguas edificaciones monacales y posadas con encanto de interior. Entorno y actividades: Comarca de La Vera. Alberga el Monasterio Real de Yuste (Patrimonio Europeo), entorno rodeado de estanques antiguos e inmensos bosques de robles melojos. Rutas de senderismo del Emperador (itinerario histórico-natural homologado que recrea el viaje de Carlos V), paseos por la Garganta de Pedro Chate entre piscinas de agua dulce rústicas y rutas cicloturistas.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10115','rural','Oferta de turismo rural','Alojamientos rurales: Casas de campo de penillanura independientes rústicas, antiguos alojamientos agrícolas bajos rehabilitados con patios extremeños de cal. Entorno y actividades: Custodia el Monumento Natural de Los Barruecos. Espectacular y singular paisaje granítico de grandes charcas de agua dulce rodeadas de colosales y caprichosas peñas de granito lisas erosionadas por el agua y el viento (famosas por albergar una de las mayores colonias de cigüeña blanca de Europa que anida sobre las rocas desnudas), rutas senderistas geológicas e interpretativas y paseos fotográficos.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10033','rural','Oferta de turismo rural','Alojamientos rurales: Casas de montaña enriscadas en una colina cónica escarpada con arquitectura tradicional de pizarra y mampostería, apartamentos rústicos de aislamiento. Entorno y actividades: Geoparque Villuercas-Ibores-Jara alto. Rutas de senderismo de ascensión vertical hacia las ruinas de su castillo medieval encaramado en una peña caliza (vistas espectaculares de los valles de fractura del sinclinal), observación ornitológica de buitres leonados y alimoches anidando en los cortados rocosos y senderos botánicos de quejigales.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10072','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales de piedra tradicionales de la Sierra de Gata con balconadas rústicas de leña, apartamentos rústicos pequeños de alta montaña. Entorno y actividades: Valle de Jálama, en la Sierra de Gata profunda (zona lingüística del "A Fala"). Destaca por las rutas de senderismo hacia el pico Jálama (1.492 metros), caminatas forestales bajo inmensos bosques de castaños y robles, senderos micológicos otoñales extremos, ríos de montaña con piscinas naturales trucheras limpias y paseos entre olivares de pendiente escarpada.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10156','rural','Oferta de turismo rural','Alojamientos rurales: Casas tradicionales de la Sierra de Gata de arquitectura popular pura (muros de pizarra, barro y vigas de madera cruzadas con pasadizos cubiertos urbanos), apartamentos rústicos pequeños con chimenea junto al río. Entorno y actividades: Uno de los pueblos más puros y resguardados de Extremadura, Conjunto Histórico enclavado en un valle estrecho. Rutas senderistas de media montaña que exploran los pinares y robledales del entorno, caminatas por el sendero fluvial del río Erjas entre molinos de aceite hidráulicos antiguos y piscinas naturales de agua limpia serrana.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10062','rural','Oferta de turismo rural','Alojamientos rurales: Casas de campo agrícolas y de dehesa bajas de interior independientes, apartamentos rurales sencillos junto al parque fluvial. Entorno y actividades: Extremo occidental de Cáceres, enclavado en la confluencia de los ríos Tajo y Sever dentro del Parque Natural Tajo Internacional. Rutas de senderismo plano de alta protección ecológica entre marismas de interior y riberas abruptas de río, paseos fluviales en barcos turísticos transfronterizos, cicloturismo de llanura por cañadas reales ganaderas y observación ornitológica de aves rapaces raras (águila perdicera). PROVINCIA: OURENSE (Texto Plano Limpio).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32057','rural','Oferta de turismo rural','Alojamientos rurales: Casas de aldea tradicionales construidas en sillería de granito y tejados de pizarra, antiguas rectorales rehabilitadas y apartamentos rústicos con vistas verticales a los cañones. Entorno y actividades: En el corazón de la Ribeira Sacra. Custodia los miradores más espectaculares y vertiginosos de Galicia, como los Balcones de Madrid (cortados de roca caliza y granito con caídas verticales de más de 300 metros sobre el río Sil). Destaca por la ruta de senderismo del Cañón del Sil (PR-G 98), caminatas botánicas que visitan el Monasterio de Santa Cristina de Ribas de Sil oculto entre castaños centenarios gigantes, y micología otoñal.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34003','rural','Oferta de turismo rural','Alojamientos rurales: Casonas solariegas de cantería integradas dentro de un casco histórico medieval fortificado intacto (Conjunto Histórico), hostales rústicos de montaña con chimeneas tradicionales y casas de alquiler íntegro. Entorno y actividades: Vertiente sur de la Ribeira Sacra alta, vigilado por su imponente fortaleza del siglo XIV. Destaca por las rutas de senderismo de los Bosques de Caldelas (itinerarios que transitan bajo sotos mágicos de castaños y robles autóctonos), paseos fluviales por el sendero del río Edo, senderos micológicos de primer nivel y punto de partida hacia los catamaranes que navegan las aguas interiores del Sil.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34002','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles boutique rurales en antiguas fábricas de curtidos restauradas junto al cauce, casonas hidalgas gallegas con patios empedrados y apartamentos rústicos con encanto arquitectónico. Entorno y actividades: Bañado por el río Arnoia (Reserva de la Biosfera de las Áreas de Allariz). Sede del sendero fluvial del Arnoia, un bosque de galería impecable con molinos harineros y aceñas medievales de granito. Ofrece rutas de senderismo ecológico hacia el Eco-espacio de O Rexo (diseñado por Agustín Ibarrola fusionando arte y naturaleza en el campo), senderos tradicionales ganaderos y cicloturismo de baja dificultad.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32069','rural','Oferta de turismo rural','Alojamientos rurales: Pazos de turismo rural vinculados a la viticultura tradicional de la Comarca del Ribeiro, casas de piedra en el casco histórico judío y fincas agrícolas con encanto. Entorno y actividades: Confluencia de los ríos Avia y Miño. Sede de rutas que conectan senderos agrícolas entre viñedos de uva treixadura cultivados en bancales escarpados de interior. Destaca por las Pozas termales de Prexigueiro (instalaciones termales rodeadas de densos bosques caducifolios), paseos ornitológicos en el embalse de Castrelo de Miño (piragüismo, kayak de interior) y caminatas fluviales.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90521','rural','Oferta de turismo rural','Alojamientos rurales: Casas de piedra de pizarra y losa tradicionales de alta montaña, apartamentos rústicos con porche de leña e instalaciones unifamiliares en valles profundos aislados. Entorno y actividades: Frontera natural con León, vertiente gallega de la Sierra de San Mamede y de Peña Trevinca (el techo de Galicia con 2.127 metros). Alberga el espectacular Espacio Natural de Peña Trevinca, de origen glaciar. Rutas de senderismo alpino exigente hacia las lagunas glaciares de Carballeda (Laguna de la Serpiente), senderos entre bosques de tejos catalogados de reliquia medieval (Teixedal de Casaio) y turismo de observación astronómica con certificación Starlight. PROVINCIA: TOLEDO (Castilla-La Mancha - Datos Curados).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34004','rural','Oferta de turismo rural','Alojamientos rurales: Alojamientos rurales integrados en antiguas edificaciones monacales o rectorales recuperadas con amplias huertas de frutales, casonas de piedra con corredores de madera. Entorno y actividades: Tierras de Celanova. Ofrece rutas de senderismo arqueológico e histórico hacia el poblado fortificado de Castromao (castro celta integrado de forma virgen en la naturaleza del monte), caminatas por el sendero fluvial del río Sorga bajo carballeiras (bosques de robles) maduras y cicloturismo de carretera familiar.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32083','rural','Oferta de turismo rural','Alojamientos rurales: Cabañas forestales de madera de diseño eco-sostenible, casas rurales de alta montaña de piedra de esquisto aisladas en pequeñas aldeas de pastores y apartamentos rústicos de montaña. Entorno y actividades: Entorno alto del Embalse de Prada y vertiente norte del macizo de Peña Trevinca. Es uno de los mejores destinos de España para el astroturismo (Destino Turístico Starlight por la absoluta ausencia de contaminación lumínica). Rutas de senderismo exigentes de montaña alta que bordean circos glaciares, paseos en barca o kayak náutico de interior en el embalse y senderos pastoriles.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32052','rural','Oferta de turismo rural','Alojamientos rurales: Parador de turismo de lujo emplazado de forma monumental en el Monasterio de Santo Estevo de Ribas de Sil, casas de aldea tradicionales y apartamentos turísticos rurales. Entorno y actividades: Ribeira Sacra noroccidental. Alberga el colosal desfiladero del río Sil. Rutas de senderismo que descienden a los embarcaderos fluviales cruzando bosques atlánticos cerrados de castaños, paseos hacia miradores colgados en la roca caliza como los de Vilouxe o Cabezoá, y rutas de interpretación de monumentos románicos integrados en plena naturaleza forestal.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34007','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles de campo y posadas de turismo interior articulados en torno al patrimonio termal tradicional del Gran Balneario, casonas gallegas con amplios jardines históricos. Entorno y actividades: Valle del río Arenteiro. Destaca por las rutas de senderismo plano por el Parque Municipal (un colosal bosque botánico maduro a orillas del río de más de 30 hectáreas), paseos fluviales de ribera que visitan antiguas fábricas de papel de granito devoradas por la hiedra y la vegetación de ribera, y senderos micológicos.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90525','rural','Oferta de turismo rural','Alojamientos rurales: Alojamientos rústicos de gran nivel integrados en villas termales de interior, pazos rurales rodeados de viñedos viejos del Ribeiro y casas de labranza bajas de granito con porches. Entorno y actividades: Ribera del río Miño medio. Rutas de senderismo plano fluviales que siguen los meandros del Miño, paseos botánicos y terapéuticos en las termas y lodos calientes locales (Balneario de Laias), caminatas agrícolas de interpretación de viñedos y dehesas tradicionales gallegas de cultivos, y pesca de río. PROVINCIA: LUGO (Texto Plano Limpio).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28009','rural','Oferta de turismo rural','Alojamientos rurales: Pallozas tradicionales gallegas rehabilitadas (viviendas de piedra con techumbre circular de paja de centeno), casonas de montaña construidas en mampostería gruesa de pizarra y albergues históricos de paso jacobeo. Entorno y actividades: Entrada oficial del Camino de Santiago Francés en Galicia, a más de 1.300 metros de altitud en la frontera natural con León. Destaca por el senderismo de alta montaña que conecta con la Sierra de los Ancares, caminatas de interpretación de la arquitectura tradicional pirenaico-gallega, senderos bajo bosques de acebos y robles en la umbría, dehesas alpinas y rutas invernales con raquetas de nieve.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27017','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales construidas íntegramente con piedra de pizarra oscura y cubiertas de losa típicas de montaña alta, apartamentos rústicos de aislamiento absoluto en pequeñas aldeas de valle y albergues de naturaleza forestal. Entorno y actividades: En el corazón del Geoparque Mundial de la UNESCO Montañas do Courel, el mayor espacio botánico y reserva forestal de Galicia. Alberga la espectacular Devesa da Rogueira (un bosque de reliquia glaciar único en Europa que concentra más de 800 especies de plantas). Ofrece exigentes rutas de senderismo de montaña, caminatas fluviales siguiendo el río Lor, recolección micológica extrema en otoño y visitas a las antiguas aldeas tradicionales restauradas (como Seceda o Froxán).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90551','rural','Oferta de turismo rural','Alojamientos rurales: Casas de turismo de aldea de piedra aisladas en valles profundos de montaña, antiguos conjuntos ganaderos tradicionales rehabilitados y apartamentos rústicos con chimeneas de leña. Entorno y actividades: Núcleo principal de la Reserva de la Biosfera de Os Ancares Lucenses y Montes de Cervantes. Entorno de aislamiento geográfico extremo y naturaleza salvaje. Destaca por las rutas de senderismo alpino de alta exigencia que ascienden al Pico Tres Bispos (1.794 metros) y al Mustallar, senderos bajo inmensos bosques de castaños viejos, dehesas tradicionales, ríos trucheros cristalinos y territorio protegido del oso pardo ibérico.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27041','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles boutique rurales en espectaculares monasterios medievales rehabilitados, casas rurales vinculadas a la viticultura heroica y bodegas de interior, y pazos de granito con amplias fincas agrícolas de frutales. Entorno y actividades: Vertiente lucense de la Ribeira Sacra baja, confluencia de los ríos Miño, Sil y Cabe. Sede de rutas que conectan senderos entre viñedos escarpados cultivados en bancales de piedra verticales. Destaca por las rutas de senderismo que visitan el Monasterio de San Vicente de Pombeiro, cascadas naturales ocultas en la fronda (Fervenza de Augacaída) y paseos fluviales en catamarán. 📂 PROVINCIA: ASTURIAS - ZONA OCCIDENTAL (Datos Curados).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27030','rural','Oferta de turismo rural','Alojamientos rurales: Palacetes de interior con fachadas monumentales y escudos heráldicos de piedra, posadas de turismo rural tradicionales vinculadas al Camino de Santiago del Norte y casonas de labranza en las parroquias rurales de su término municipal. Entorno y actividades: Valle del río Masma, a las faldas de la Sierra de la Toxiza. Ofrece rutas de senderismo kárstico e histórico hacia la espectacular Cova del Rei Cintolo (la cueva más grande de Galicia con galerías de estalactitas y río subterráneo activo, transitable con visitas guiadas de aventura), caminatas botánicas bajo bosques de robles en el paraje de Os Remedios, senderos fluviales y cicloturismo de carretera.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27016','rural','Oferta de turismo rural','Alojamientos rurales: Pazos de turismo rural de sillería de granito con hórreos tradicionales, casas de labranza bajas vinculadas al agroturismo vinícola de interior y apartamentos rústicos con vistas directas al cañón fluvial. Entorno y actividades: Orilla occidental del río Miño en la Ribeira Sacra lucense. Sede de una de las estampas de naturaleza e interior más fotogénicas de Galicia: el Cabo do Mundo (colosal meandro cerrado del río Miño rodeado de viñedos en terrazas empinadas). Rutas de senderismo fluvial por el río Asma, paseos botánicos por sotos de castaños centenarios y cicloturismo entre dehesas tradicionales gallegas.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27034','rural','Oferta de turismo rural','Alojamientos rurales: Casas de piedra tradicionales de mampostería oscura con cubiertas de pizarra, apartamentos rústicos de alta montaña con porche de leña e instalaciones unifamiliares en valles cerrados aislados. Entorno y actividades: Parque Natural y Reserva de la Biosfera de Os Ancares. Bañado por el río Navia alto. Ofrece rutas de senderismo exigentes de media-alta montaña que exploran bosques atlánticos cerrados y vírgenes de robles rebollos y abedules, caminatas que cruzan su imponente puente medieval de piedra sobre el río caudaloso, pesca truchera tradicional de río limpio y senderos micológicos de otoño.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27040','rural','Oferta de turismo rural','Alojamientos rurales: Alojamientos rurales unifamiliares, antiguos pazos y casonas hidalgas gallegas restauradas con grandes huertas y corredores de madera tradicionales, y albergues de paso jacobeo de interior. Entorno y actividades: Comarca de la Ulloa alta, Camino de Santiago Francés. Destaca por las rutas de senderismo que conectan con los senderos que rodean el colosal Castillo de Pambre (fortaleza medieval gótica integrada de forma virgen en la naturaleza boscosa junto al río Pambre), caminatas llanas por dehesas agrarias de ganado extensivo y paseos botánicos en carballeiras.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28004','rural','Oferta de turismo rural','Alojamientos rurales: Hostales de alta montaña especializados en senderistas, casas rurales de alta montaña de piedra de esquisto aisladas en pequeñas aldeas de pastores y apartamentos rústicos con chimeneas rústicas de suelo. Entorno y actividades: El municipio de mayor altitud de Galicia (núcleo urbano a casi 1.000 metros), en las sierras del suroccidente astur-galaico y el Camino Primitivo. Alberga la espectacular Fervenza de Seimeira de Vilagocende (una de las cascadas naturales de montaña en caída libre más altas de Galicia, con más de 50 metros rodeada de robles y avellanos mágicos). Rutas senderistas exigentes de montaña alta y observación astronómica de cielos negros.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27031','rural','Oferta de turismo rural','Alojamientos rurales: Parador de turismo de lujo emplazado de forma monumental en el antiguo Monasterio e iglesia barroca en lo alto de la colina, casonas gallegas de labranza y apartamentos turísticos rurales en las parroquias de su término. Entorno y actividades: Centro logístico y natural del Valle de Lemos. Ofrece rutas de senderismo plano fluviales que siguen los meandros del río Cabe bajo bosques de galería autóctonos tupidos de alisos, paseos de interpretación botánica por dehesas tradicionales gallegas de cultivos de vid y campos de pasto llanos, cicloturismo familiar de relax y ornitología.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27059','rural','Oferta de turismo rural','Alojamientos rurales: Casas de campo agrícolas tradicionales de sillería de granito independientes de interior de viñedo, pazos rurales boutique y pequeños apartamentos turísticos rurales con porche. Entorno y actividades: En el interior de la Ribeira Sacra lucense meridional, flanqueado por los cañones profundos del río Sil. Sede de rutas de senderismo vertical exigente que transitan hacia miradores colgados literalmente sobre el abismo de roca caliza y granito, como el mirador de Caxide o del Duque. Paseos en los catamaranes que navegan las aguas del cañón fluvial del Sil, caminatas agrícolas y enoturismo.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27052','rural','Oferta de turismo rural','Alojamientos rurales: Casas de pueblo tradicionales de mampostería fluvial de río y pizarra, apartamentos rurales acogedores para familias y deportistas náuticos de interior junto a playas fluviales. Entorno y actividades: Valle del río Sil bajo y estribaciones del Macizo Central Orensano. Destaca por las rutas de senderismo plano por los senderos fluviales de su playa fluvial natural de San Clodio ideal para el baño veraniego, paseos hacia el espectacular mirador de As Penas de Matacás con vistas de pájaro sobre los viñedos viejos en terrazas, rutas cicloturistas y senderos micológicos. PROVINCIA: ASTURIAS - ZONA OCCIDENTAL (Texto Plano Limpio).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12080','rural','Oferta de turismo rural','Alojamientos rurales: Casas de turismo rural intramuros de mampostería medieval, hoteles boutique integrados en antiguos palacetes señoriales del Maestrazgo con vistas al castillo y masías aisladas en la periferia forestal. Entorno y actividades: Capital de la indómita comarca de Els Ports. Destaca por las rutas de senderismo que bordean sus kilométricas murallas medievales, paseos arqueológicos hacia las pinturas rupestres prehistóricas de Morella la Vella (Patrimonio de la Humanidad), exigentes circuitos de cicloturismo de montaña (BTT), senderos de micología en otoño y observación astronómica con cielos limpios certificados.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12139','rural','Oferta de turismo rural','Alojamientos rurales: Masías tradicionales de alta montaña construidas en sillería de piedra caliza con aislamiento reforzado para el invierno, apartamentos rústicos con chimenea de leña y albergues de naturaleza pirenaico-mediterránea. Entorno y actividades: En el corazón del Parque Natural del Macizo de Peñagolosa. Es el municipio situado a mayor altitud de la Comunidad Valenciana (1.246 metros). Destaca por la emblemática y mítica ruta de senderismo de ascensión al Pico de Peñagolosa (techo de la provincia con 1.813 metros, un colosal farallón calcáreo vertical), caminatas históricas hacia el Santuario de Sant Joan de Penyagolosa bajo inmensos bosques de pino negro y tejos relictos, y micología de boletus.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12079','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles de interior y posadas rurales fuertemente vinculados al patrimonio termal tradicional de su balneario, apartamentos turísticos orientados al turismo activo y de aventura y casas de pueblo rústicas junto al cauce. Entorno y actividades: Cañón fluvial del Alto Mijares. Célebre a nivel europeo por la espectacular surgencia de agua termal de la Fuente de los Baños (una poza natural turquesa donde brota el agua a unos constantes 25 °C todo el año apta para el baño medicinal). Ofrece la espectacular ruta de senderismo de los Estrechos del Río Mijares (desfiladero angosto con paredes verticales de roca de más de 100 metros), escalada deportiva vertical en caliza de primer nivel mundial y kayak de aguas bravas.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11002','rural','Oferta de turismo rural','Alojamientos rurales: Casas de piedra tradicionales de montaña colgadas literalmente en terrazas sobre el risco, pequeños hostales de montaña con chimeneas de campana y viviendas rurales con espectaculares miradores al barranco. Entorno y actividades: Encaramado de forma inverosímil a una colosal muela de roca caliza a 1.195 metros de altitud. Ofrece rutas de senderismo geológico por los barrancos de la Mola d''Ares, caminatas hacia el Barranc dels Horts (un paraje natural sagrado con un bosque de robles y quejigos centenarios monumentales único en el levante peninsular), observación de grandes colonias de buitre leonado y cabra montés, y senderos micológicos.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12128','rural','Oferta de turismo rural','Alojamientos rurales: Casas de pueblo tradicionales con fachadas de piedra rojiza lavada (rodeno) y callejones de trazado islámico floridos, hoteles boutique rurales con encanto en el casco antiguo y apartamentos rústicos a la sombra de su castillo. Entorno y actividades: Entorno de la Plana Alta y el desierto de las Palmas montañoso. Ofrece rutas de senderismo y paseos fotográficos de interpretación geológica que rodean la famosa "Roca Grossa" (una colosal mole de piedra de miles de toneladas inclinada sobre la calle), senderos agrícolas entre olivos milenarios y viñedos viejos de colina, y rutas cicloturistas de carretera sin tráfico.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12104','rural','Oferta de turismo rural','Alojamientos rurales: Casonas señoriales palaciegas de sillería reconvertidas en hoteles de campo, casas rurales de labranza tradicionales de vega con amplios patios interiores de azulejos y apartamentos rurales familiares. Entorno y actividades: Valle del río Palancia, encajonado de forma espectacular entre el Parque Natural de la Sierra de Espadán y la Sierra Calderona. Nudo de conexión central con la Vía Verde de Ojos Negros (la vía verde más larga de España, ideal para senderistas y cicloturistas). Ofrece la ruta del paraje natural del Manantial de la Esperanza, paseos fluviales por el cauce del Palancia, caminatas de interpretación botánica y turismo gastronómico-rural.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12051','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales de piedra medieval rehabilitada en un casco histórico galardonado, masías de agroturismo ganadero independientes en el altiplano y apartamentos rústicos con porche. Entorno y actividades: Comarca del Alt Maestrat montañoso. Ofrece paseos etnográficos de aislamiento absoluto, rutas de senderismo exigentes hacia el barranco del río Monleón, caminatas para ver el colosal "Carrasca de Culla" (una encina monumental milenaria protegida bajo cuya copa se cobijaban ejércitos), observación astronómica en su observatorio turístico del Astromestrat con cielos negros certificados, y micología.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12057','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales y hostales de montaña integrados en un núcleo rodeado de colinas escarpadas de roca roja (rodeno), cabañas forestales de madera y apartamentos pequeños con estufas de leña. Entorno y actividades: En el corazón del Parque Natural de la Sierra de Espadán. Alberga una de las mayores reservas ecológicas de Alcornoques de la península sobre suelos de arenisca roja. Rutas de senderismo botánico bajo túneles umbríos de bosques de alcornoques y helechos, senderos hacia los picos del Puntal de l''Algepsar, rutas micológicas otoñales especializadas en el hongo del corcho y cicloturismo de carretera de gran pendiente. 📂 PROVINCIA: MURCIA (Región de Murcia Datos Curados).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12026','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles rurales de estética modernista vinculados al termalismo tradicional de su célebre manantial de la Font d''en Segures, apartamentos de montaña e históricas casonas del Maestrat. Entorno y actividades: Altiplano calizo del Alt Maestrat. Custodia el paraje natural del Rivet (un bosque mágico y protegido de robles centenarios majestuosos encajonado en una pequeña dehesa alta). Rutas de senderismo de media montaña, paseos botánicos de interpretación de fuentes mineromedicinales, senderos ganaderos tradicionales y turismo gastronómico-rural enfocado en la trufa negra y los quesos de montaña.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12081','rural','Oferta de turismo rural','Alojamientos rurales: Palacetes rurales burgueses del siglo XIX con espectaculares jardines y huertos tradicionales señoriales, apartamentos rústicos de ribera y casas de pueblo familiares. Entorno y actividades: Valle del río Palancia. Sede de una de las estampas de agua dulce más famosas del levante: el paraje de El Salto de la Novia (espectacular e imponente cascada natural de más de 60 metros de altura en caída libre sobre el río Palancia encajonada entre paredes calizas). Rutas de senderismo plano de ribera, caminatas botánicas que visitan el "Olmo de Navajas" (árbol monumental plantado en el siglo XVII), y cicloturismo por la Vía Verde de Ojos Negros.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12022','rural','Oferta de turismo rural','Alojamientos rurales: Casas de montaña de piedra caliza tradicionales con muros anchos aislantes, apartamentos rústicos en valles cerrados de frutales de montaña junto a arroyos trucheros limpios. Entorno y actividades: Alto Palancia, estribaciones de la Sierra de El Toro y Peña Santa María. Rutas de senderismo hacia el Nacimiento del Río Palancia (Los Cloticos), caminatas de interpretación botánica por dehesas de sabinas y pinos silvestres, senderos micológicos otoñales extremos (recogida de níscalos), ríos de montaña con piscinas naturales de aguas cristalinas ideales para el descanso veraniego y paseos arqueológicos hacia su acueducto romano protegido.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22004','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles boutique rurales en conventos del siglo XVII rehabilitados, cortijos tradicionales andaluces rodeados de dehesas de encinas y casas de cal con teja árabe y chimeneas de leña a los pies de las ruinas de su castillo templario. Entorno y actividades: Capital y centro neurálgico del Parque Natural Sierra de Aracena y Picos de Aroche. Custodia la impresionante Gruta de las Maravillas (colosal cueva kárstica subterránea de estalactitas, estalagmitas y lagos interiores de agua turquesa cristalina en pleno casco urbano, transitable con visitas guiadas de aventura). Destaca por el sendero hacia Linares de la Sierra, paseos botánicos por el castañar alto, avistamiento ornitológico y micología de dehesa en otoño.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22003','rural','Oferta de turismo rural','Alojamientos rurales: Casas de turismo de aldea de piedra blanqueada andaluza, apartamentos rústicos con vigas de castaño e históricas posadas con patios empedrados y fuentes de agua viva. Entorno y actividades: En el interior de la sierra profunda húmeda, declarado Conjunto Histórico. Custodia el espectacular y místico paraje natural de la Peña de Arias Montano (colosal afloramiento de roca caliza rodeado de cuevas naturales y manantiales sagrados que domina todo el valle). Ofrece la ruta de senderismo circular Alájar-Linares de la Sierra a través de caminos tradicionales empedrados entre muros de piedra seca, paseos bajo densos alcornocales y quejigales, y micología.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21025','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales andaluzas de cal blanca de alquiler íntegro con grandes porches, apartamentos rústicos de montaña orientados al turismo activo y fincas de agroturismo ganadero destinadas a la cría tradicional del cerdo ibérico. Entorno y actividades: Sierra de Huelva occidental, vigilado de forma monumental por su imponente y fotogénico castillo medieval del siglo XIII intacto. Destaca por las rutas de senderismo de los Senderos del Chanza (itinerarios fluviales que siguen el curso joven del río), caminatas bajo sotos umbríos de castaños viejos, senderos micológicos otoñales de primer nivel (especializados en la seta del gurumelo) y dehesas ganaderas.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21033','rural','Oferta de turismo rural','Alojamientos rurales: Casonas de labranza tradicionales de sillería blanqueada y madera, hostales con encanto rústico junto a campos de frutales de montaña y fincas de agroturismo aisladas de la civilización. Entorno y actividades: En el corazón geográfico y más lluvioso de la sierra baja. Célebre por albergar la Fuente de los Doce Caños en pleno centro del pueblo, de donde brota un colosal manantial vivo de agua pura de deshielo del río Múrtigas. Ofrece la espectacular ruta de senderismo del Sendero de los Llanos (caminata plana bajo túneles vegetales umbríos de castaños y huertas antiguas), senderos forestales de alcornoques y quejigos, y rutas micológicas otoñales.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22001','rural','Oferta de turismo rural','Alojamientos rurales: Casas de pueblo tradicionales con fachadas de mampostería antigua y calles empedradas rústicas, apartamentos boutique rurales con encanto en el casco medieval y posadas rurales. Entorno y actividades: Faldas del cerro de San Cristóbal. Alberga la única mezquita rural del siglo X conservada casi intacta en España, erigida de forma espectacular sobre las ruinas de un castillo en plena cumbre boscosa. Ofrece la ruta de senderismo de ascensión al Pico de San Cristóbal (techo de la zona con miradores panorámicos), paseos botánicos por el sendero del arroyo de la Acebuche, caminatas de dehesa agraria y avistamiento de aves rapaces (colonia de buitre negro). 📂 PROVINCIA: SEVILLA (Andalucía - Datos Curados).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22005','rural','Oferta de turismo rural','Alojamientos rurales: Casonas señoriales andaluzas de gran porte convertidas en hoteles de campo, casas rurales de labranza tradicionales de vega con amplios patios interiores de cal y apartamentos rurales familiares. Entorno y actividades: Extremo occidental de la sierra alta, frontera con Portugal y bañado por el río Chanza. Ofrece las rutas de senderismo arqueológico e histórico hacia el yacimiento de la ciudad romana de Turóbriga y la ermita medieval de San Mamés (rodeada de dehesas vírgenes), caminatas geológicas interpretativas por los lapiaces calcáreos de los llanos de Aroche, senderos micológicos de encinar y cicloturismo de carretera sin tráfico.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21034','rural','Oferta de turismo rural','Alojamientos rurales: Casas de labranza tradicionales de la sierra alta con huertos integrados, apartamentos rústicos con chimeneas de piedra de suelo y alojamientos ecoturísticos rurales de aislamiento fluvial. Entorno y actividades: Valle del río Múrtigas, en una zona de humedad extrema. Sede de la espectacular y mítica ruta de senderismo del Ribera del Múrtigas (un recorrido plano bajo un bosque de galería atlántico denso y cerrado de alisos, sauces y chopos monumentales que emula el norte peninsular). Caminatas por sotos de castaños centenarios, paseos fotográficos de naturaleza interior y senderos ganaderos tradicionales de montaña.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21045','rural','Oferta de turismo rural','Alojamientos rurales: Alojamientos rurales unifamiliares con portadas tradicionales adornadas con "llanos" (espectaculares alfombras de piedras empedradas artísticas bicolores en el suelo de entrada), apartamentos rústicos pequeños. Entorno y actividades: Enclavado en un valle cerrado profundo de colinas ganaderas. Ofrece paseos de aislamiento absoluto y silencio rural, rutas de senderismo plano de baja dificultad que recorren el Sendero de las Suertes, caminatas micológicas otoñales extremas en los bosques de encinas viejas de los alrededores y paseos fotográficos de interpretación etnográfica urbana.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21043','rural','Oferta de turismo rural','Alojamientos rurales: Casas de campo de penillanura independientes rústicas, antiguos alojamientos agrícolas de dehesa bajos rehabilitados y hostales de interior dedicados al agroturismo gastronómico. Entorno y actividades: La meca internacional absoluta de la cultura del cerdo ibérico de bellota y la dehesa madura. Ofrece rutas de senderismo de interpretación ambiental por sus interminables campos adehesados de encinas y alcornoques centenarios donde pasta el ganado porcino en libertad (Senda de la Dehesa de Jabugo), paseos fluviales por las riberas linderas del Múrtigas alto, senderos micológicos y observación de estrellas (cielos negros Starlight). PROVINCIA: ALBACETE (Castilla-La Mancha Datos Curados).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25082','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles tradicionales de alta montaña construidos con sillería de piedra oscura y cubiertas de pizarra, apartamentos alpinos rústicos con chimeneas de leña y bordas pirenaicas restauradas para alquiler íntegro. Entorno y actividades: Puerta de entrada oriental principal al Parque Nacional de Aigüestortes y Estany de Sant Maurici. Sede de la mítica ruta senderista que asciende al fotogénico Estany de Sant Maurici vigilado por las colosales agujas de roca caliza de Els Encantats. Destaca por el senderismo de alta montaña (red de refugios Carros de Foc), el ascenso al pico Peguera, rutas invernales de esquí y raquetas de nieve, y avistamiento de fauna alpina (rebecos, urogallos).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25209','rural','Oferta de turismo rural','Alojamientos rurales: Casas de turismo rural (casas de payés) integradas en pequeñas aldeas tradicionales de montaña, hoteles boutique rurales a orillas del río y alojamientos de ecoturismo orientados a los deportes de aventura. Entorno y actividades: Capital del Pallars Sobirà, bañado por el río Noguera Pallaresa. La meca internacional absoluta del turismo activo de aguas bravas en España; destaca por la práctica de rafting, hidrospeed, descenso de cañones y kayak fluvial de nivel extremo. Ofrece rutas de senderismo hacia el Parque Natural del Alt Pirineu, caminatas por el Valle de Àssua siguiendo itinerarios pastoriles literarios y senderos micológicos en sus frondosos abetales y pinares de pino negro.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27014','rural','Oferta de turismo rural','Alojamientos rurales: Colosales casas de piedra aranesas con grandes lucernarios y empinados tejados de pizarra negra gótica, hoteles de montaña premium con instalaciones de spa y apartamentos rústicos de gran porte con chimeneas de leña. Entorno y actividades: Capital del Valle de Arán, entorno de vertiente atlántica de humedad extrema y densos bosques caducifolios. Ofrece espectaculares rutas de senderismo hacia el paraje de Uelhs deth Joeu (donde brotan a presión las aguas de deshielo del glaciar del Aneto que discurren subterráneas), caminatas por el sendero fluvial del río Garona, cicloturismo de montaña de descenso (BTT Enduro), proximidad inmediata a Baqueira Beret para deportes de nieve y rutas micológicas.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25043','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales unifamiliares construidas con losas de piedra tradicionales y balconadas de madera rústica orientadas al sur, pequeños hostales familiares de montaña y apartamentos turísticos rurales integrados en pintorescos pueblos pirenaicos. Entorno y actividades: Puerta de entrada occidental al Parque Nacional de Aigüestortes (acceso al espectacular Valle de Sant Nicolau y el Estany Llong) y custodio del conjunto de Iglesias Románicas de la Vall de Boí (Patrimonio de la Humanidad por la UNESCO). Destaca por las rutas de senderismo alpino de alta exigencia, paseos terapéuticos en la estación termal de Caldes de Boí con decenas de fuentes mineromedicinales calientes, senderos de micología forestal y esquí alpino en Boí Taüll.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27015','rural','Oferta de turismo rural','Alojamientos rurales: Antiguas masías fortificadas aisladas en el llano de la cuenca caliza, campamentos ecoturísticos rurales de diseño bioclimático y apartamentos para deportistas de aventura e investigadores del cielo. Entorno y actividades: Al pie de la Sierra del Montsec. Nudo de acceso principal al colosal y vertiginoso Congost de Montrebei (un impresionante y angosto desfiladero calizo transitable a pie mediante pasarelas excavadas en acantilados verticales de roca sobre el río Noguera Ribagorzana). Destaca por el kayak fluvial de cañón y piragüismo, rutas cicloturistas y es el epicentro nacional del astroturismo y la observación de estrellas al contar con el Parque Astronómico del Montsec (Reserva y Destino Turístico Starlight de máxima pureza).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25126','rural','Oferta de turismo rural','Alojamientos rurales: Hostales tradicionales pirenaicos de mampostería oscura de río a los pies de grandes farallones calcáreos, apartamentos rústicos pequeños optimizados para deportistas náuticos de río y casas rurales de montaña. Entorno y actividades: Confluencia del río Noguera Pallaresa y el río de Santa Magdalena. El mayor punto de embarque para el rafting y el descenso de ríos alpinos en la provincia. Ofrece espectaculares rutas de senderismo hacia el Valle de Cardós y la Coma de Burg dentro del Parque Natural del Alt Pirineu, caminatas fluviales entre sauces y chopos, senderos micológicos otoñales extremos y rutas de aislamiento geológico puro.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25127','rural','Oferta de turismo rural','Alojamientos rurales: Casas de turismo rural tradicionales de la alta Cerdanya leridana construidas con bloques de granito y piedra, chalets alpinos rústicos con chimeneas de leña independientes y albergues de montaña forestales. Entorno y actividades: Valle alto de la Cerdanya, frontera con Andorra. Meca del esquí nórdico y de fondo en España (pistas de Lles y Aransa). Ofrece espectaculares rutas de senderismo de alta montaña que ascienden a los lagos de origen glaciar de los estanques de la Pera, caminatas forestales de interpretación botánica bajo inmensos bosques boreales de pino negro autóctono, senderos ganaderos que suben a prados alpinos altos con ganado extensivo y paseos de invierno con raquetas.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25183','rural','Oferta de turismo rural','Alojamientos rurales: Casas de campo tradicionales de sillería de piedra con amplias fincas ganaderas, apartamentos rurales rústicos con chimeneas de leña ideales para familias y pequeños hostales pirenaicos de interior. Entorno y actividades: Valle del río Noguera Pallaresa medio, falda de la estación invernal y de montaña de Port Ainé. Rutas de senderismo que conectan con los senderos que rodean el Parque Natural del Alt Pirineu occidental, caminatas por el fondo del valle boscoso, paseos llanos fluviales y cicloturismo, pesca deportiva truchera limpia en ríos vírgenes de montaña y deportes de nieve en invierno.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25022','rural','Oferta de turismo rural','Alojamientos rurales: Casas de turismo de interior integradas en un casco urbano empedrado medieval compacto a orillas del agua, alojamientos rurales pequeños de mampostería baja de río y apartamentos rústicos. Entorno y actividades: Desfiladero calizo inferior del río Segre. Sede de la espectacular ruta de senderismo del Congost de Mu (itinerario de pasarelas de madera ancladas a las paredes de roca caliza del cañón fluvial, puentes colgantes y estrechos pasos sobre el agua cristalina). Ofrece paseos botánicos por huertos tradicionales de ribera, piragüismo, senderos de media montaña por canchales de caliza y observación de aves rapaces calcícolas (buitres leonados). PROVINCIA: SORIA (Texto Plano Limpio).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42215','rural','Oferta de turismo rural','Alojamientos rurales: Posadas reales en impresionantes casonas pinariegas de sillería de piedra de los siglos XVI al XVIII, hoteles de montaña rústicos con acabados en madera de pino de Soria y casas de alquiler íntegro con chimeneas de granito. Entorno y actividades: En el corazón de la comarca de Pinares y a los pies del Parque Natural de la Laguna Negra y los Circos Glaciares de Urbión. Sede del acceso principal a la legendaria y fotogénica Laguna Negra de Urbión, un lago de origen glaciar encajonado entre colosales paredes verticales de roca y pinos silvestres. Ofrece rutas de senderismo de alta montaña que ascienden al Pico Urbión (nacimiento del río Duero), paseos botánicos por los pinares continuos más extensos de España, turismo micológico extremo (boletus) y deportes de nieve.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42189','rural','Oferta de turismo rural','Alojamientos rurales: Casas de turismo rural construidas en piedra caliza con solanas rústicas de madera, hostales orientados al excursionismo y apartamentos rústicos a orillas del río Ucero bajo la sombra de su castillo medieval. Entorno y actividades: Puerta de entrada oficial meridional al Parque Natural del Cañón del Río Lobos. Célebre a nivel nacional por su colosal desfiladero kárstico de calizas rojizas esculpido por el río. Ofrece la ruta de senderismo de la Senda del Río (caminata plana bajo imponentes acantilados verticales de roca donde anidan buitres leonados hasta llegar a la Ermita templaria de San Bartolomé y la cueva Grande), senderos de interpretación geológica y botánica de sabinas albares, y rutas de agroturismo.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42069','rural','Oferta de turismo rural','Alojamientos rurales: Grandes chalets rústicos de montaña independientes integrados bajo la sombra forestal, complejos de cabañas de madera pinariegas y apartamentos para montañeros y recolectores con cocinas integradas. Entorno y actividades: Flanqueado por la Sierra de Urbión y bañado por el curso más joven e indómito del río Duero. Destaca por sus puentes medievales de piedra perfectamente integrados en la naturaleza fluvial. Ofrece exigentes rutas de senderismo de alta montaña hacia los circos glaciares, la ruta de los Senderos del Duero joven entre saltos de agua y rocas musgosas, y es uno de los mayores centros nacionales de micología para la recolección regulada de níscalos y hongos boletus.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42113','rural','Oferta de turismo rural','Alojamientos rurales: Palacetes rurales barrocos con portadas heráldicas de sillería dorada dentro de un casco histórico monumental amurallado, posadas con encanto de interior y casas de cal de dehesa. Entorno y actividades: Encaramado sobre un cerro estratégico que domina el Valle del Jalón. Ofrece rutas de senderismo histórico que rodean su monumental arco de triunfo romano de tres vanos, caminatas botánicas por los páramos calizos y dehesas de encinas y sabinas que lo circundan, cicloturismo de carretera sin tráfico y cercanía al nacimiento del río Jalón.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90806','rural','Oferta de turismo rural','Alojamientos rurales: Casonas de labranza tradicionales sorianas unifamiliares con corrales recuperados y amplias parcelas, apartamentos rurales de interior y alojamientos de montaña junto al bosque. Entorno y actividades: Conocido como "La Puerta de Pinares", lindando con las aguas del Embalse de la Cuerda del Pozo. Ofrece rutas de senderismo que conducen a parajes náuticos de interior como Playa Pita (playa fluvial rodeada de inmensos pinares silvestres ideal para el baño estival, kayak y piragüismo), senderos de interpretación trufícola (capital de la trufa negra de Soria en invierno), senderos micológicos en otoño y rutas cicloturistas llanas.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42035','rural','Oferta de turismo rural','Alojamientos rurales: Posadas reales castellanas integradas en palacios renacentistas y conventos restaurados, casas de turismo rural a la sombra de su colosal castillo fortificado y apartamentos rurales familiares. Entorno y actividades: Tierra de Frontera de la meseta del Duero. Destaca por albergar en su término la espectacular Ermita de San Baudelio de Berlanga (joya mozárabe aislada en pleno paisaje agrario árido y dehesa caliza). Ofrece rutas de senderismo fluvial por el río Escalote, caminatas hacia las dehesas de encinas centenarias del cañón del Duero meridional, observación astronómica nocturna y ornitología.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42078','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales tradicionales pinariegas construidas con mampostería oscura y piedra arenisca, apartamentos rústicos de alta montaña con chimeneas de leña y albergues forestales. Entorno y actividades: El municipio situado a mayor altitud de la vertiente soriana de Urbión. Custodia el espectacular paraje natural de Castroviejo (un laberinto geológico de colosales rocas areniscas esculpidas de forma caprichosa por la erosión en mitad de un bosque cerrado). Rutas de senderismo que ascienden al Nacimiento del Río Duero y a la cascada de la Cueva de la Serra, vías ferratas de montaña de aventura y micología de boletus.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42046','rural','Oferta de turismo rural','Alojamientos rurales: Casas de turismo rural puras que conservan la arquitectura popular medieval intacta de la provincia (muros de mampostería caliza, entramados de madera de enebro o sabina, barro y chimeneas cónicas de cesto tradicionales), posadas con encanto sobre el risco. Entorno y actividades: Conjunto Histórico colgado sobre un cerro calizo escarpado que mira al Valle de la Sangre. Custodia la Reserva Natural del Sabinar de Calatañazor (el bosque de Sabinas Albares más denso, maduro y mejor conservado del planeta, con ejemplares milenarios gigantescos de hasta 14 metros de altura). Ofrece la ruta de senderismo del cañón del río Milanos, caminatas geológicas interpretativas y observación ornitológica de rapaces de roca.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42125','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales unifamiliares con porches de roca caliza en pequeños núcleos agrícolas puros aislados en valles de pinos y sabinas, apartamentos rústicos pequeños. Entorno y actividades: Entorno de pinares y sabinares del interior soriano central. Es reconocido a nivel mundial como Destino Turístico y Cielo Starlight por la absoluta ausencia de contaminación lumínica y la máxima nitidez para la observación de estrellas en la naturaleza. Rutas de senderismo micológico otoñal, caminatas hacia el Manantial de la Fuentona cercano y senderos forestales llanos. PROVINCIA: PONTEVEDRA (Galicia - Datos Curados).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42124','rural','Oferta de turismo rural','Alojamientos rurales: Casas tradicionales sorianas rehabilitadas de mampostería de río y madera, apartamentos rurales pequeños para familias y espeleólogos cerca del cauce fluvial. Entorno y actividades: Custodia el Monumento Natural de La Fuentona de Muriel (conocido como el Ojo de Mar, una espectacular y colosal surgencia kárstica natural o pozo de agua dulce turquesa profunda y cristalina de la que nace el río Abión). Rutas senderistas señalizadas que transitan por la hoz caliza calcárea de la Fuentona bajo sabinas centenarias y nidos de buitres, paseos botánicos y cuevas kársticas con ríos subterráneos activos. PROVINCIA: ÁVILA (Texto Plano Limpio).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05105','rural','Oferta de turismo rural','Alojamientos rurales: Hostales de alta montaña especializados en montañeros, hoteles rurales premium construidos en piedra de granito y grandes ventanales de cristal, y cabañas alpinas independientes con chimenea de leña. Entorno y actividades: El principal centro logístico y de acceso al Parque Regional de la Sierra de Gredos. Custodia el punto de partida de la Plataforma de Gredos, de donde nace la mítica ruta senderista que asciende al Circo de Gredos y a la Laguna Grande bajo la silueta del Pico Almanzor (2.592 metros). Destaca por el avistamiento de la cabra montés de Gredos, rutas de raquetas de nieve, zonas de dehesa ganadera, baño en las pozas del río Tormes y certificación astronómica Starlight.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('51001','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles de campo y fincas rústicas rodeadas de campos de frutales e higueras, casas de piedra de la vertiente sur con amplios porches y apartamentos de dehesa a las faldas del castillo de Don Álvaro de Luna. Entorno y actividades: Capital de la vertiente sur de la Sierra de Gredos (el Valle del Tiétar). Custodia las impresionantes Cuevas del Águila (colosal formación geológica subterránea de estalactitas y estalagmitas gigantes iluminadas, transitable con visitas guiadas). Ofrece rutas de senderismo fluvial por las piscinas naturales del río Arenal, caminatas por densos castañares y dehesas mediterráneas, y ascensiones a los Galayos (meca de la escalada clásica en roca). 📂 PROVINCIA: SEGOVIA (Castilla y León - Datos Curados).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('51003','rural','Oferta de turismo rural','Alojamientos rurales: Casonas solariegas de sillería de granito con corredores de madera, hoteles rurales de ribera junto al río Tormes, antiguas fábricas de luz reconvertidas en alojamientos rústicos y casas de labranza tradicionales. Entorno y actividades: Nudo estratégico occidental del Valle del Tormes y el Aravalle, a los pies de Gredos. Ofrece las rutas de senderismo fluvial del río Tormes cruzando su monumental puente románico, caminatas de media montaña que se adentran en el Valle del Jerte colindante, senderos micológicos de robledal, paseos a caballo y agroturismo enfocado en la cultura agrícola tradicional del judión del Barco.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05047','rural','Oferta de turismo rural','Alojamientos rurales: Fincas de agroturismo de gran extensión con microclima mediterráneo, casas rurales de diseño exclusivo aisladas entre gargantas y pequeños apartamentos tradicionales de fachadas blancas de entramado de madera. Entorno y actividades: Vertiente sur extrema de Gredos, resguardada de los vientos del norte y abierta al Embalse de Rosarito. Destaca por la espectacular ruta de senderismo de la Garganta de Santa María con pozas naturales de agua cristalina aptas para el baño veraniego. Ofrece rutas arqueológicas hacia el Castro Celta de El Raso rodeado de robles, cicloturismo de carretera, y observación ornitológica de grullas y aves acuáticas en el embalse.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05165','rural','Oferta de turismo rural','Alojamientos rurales: Alberga el primer Parador de Turismo histórico de España, hoteles forestales perfectamente mimetizados entre el pinar, casas de aldea tradicionales de cantería y chalets rústicos de montaña. Entorno y actividades: Cabecera alta del Valle del Tormes, a más de 1.500 metros de altitud. Destaca por albergar el Nacimiento del Río Tormes en el paraje de las Chorreras. Ofrece la ruta de senderismo del Pinar de Navarredonda (un inmenso bosque de pino silvestre autóctono), caminatas ecuestres de montaña alta, senderos micológicos otoñales y es un punto de referencia para el turismo de observación de estrellas en cielos oscuros certificados (Starlight).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05241','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales de campo independientes con amplias parcelas forestales, chalets de montaña tradicionales de piedra caliza y apartamentos rústicos de fin de semana adaptados para familias. Entorno y actividades: Cuenca del Alberche bajo, flanqueado por la Sierra de Guadarrama occidental. Custodia el espectacular e imponente Castañar de El Tiemblo (un bosque mágico con castaños milenarios gigantescos, como "El Abuelo", único en el Sistema Central). Ofrece rutas de senderismo hacia la Reserva Natural del Valle de Iruelas, paseos náuticos de interior (kayak, piragüismo, vela) en el Embalse de El Burguillo, y caminatas arqueológicas hacia los Toros de Guisando.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05186','rural','Oferta de turismo rural','Alojamientos rurales: Posadas señoriales de estilo barroco francés en el casco monumental, casas rurales integradas en antiguas dependencias del Palacio de los Duques de Alba y apartamentos de turismo activo orientados a deportistas de aventura. Entorno y actividades: En el corazón del idílico Valle del Corneja. Capital mundial y referente absoluto de los deportes de vuelo libre (parapente y ala delta) gracias a las corrientes térmicas de su Puerto de Peña Negra. Ofrece rutas de senderismo de media montaña por la Sierra de Villafranca, caminatas llanas que siguen las riberas del río Corneja entre molinos harineros antiguos, y cicloturismo de carretera de gran pendiente.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05041','rural','Oferta de turismo rural','Alojamientos rurales: Grandes complejos de casas rurales de alquiler íntegro con barbacoas y zonas recreativas a orillas del agua, apartamentos rústicos fluviales y casas de pueblo tradicionales. Entorno y actividades: En pleno Valle del río Alberche medio, rodeado de huertos de melocotoneros. Destaca por albergar un entramado de pozas y playas fluviales naturales de aguas cristalinas ideales para el baño y el descanso veraniego. Ofrece rutas de senderismo de media montaña que ascienden hacia la Sierra de la Paramera, senderos micológicos de robledal, caminatas agrícolas y rutas cicloturistas llanas.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05089','rural','Oferta de turismo rural','Alojamientos rurales: Casas de pueblo tradicionales andaluzas-extremeñas de cal blanca con balconadas de madera colgadas del risco (Conjunto Histórico), apartamentos rústicos pequeños con chimenea de piedra de suelo. Entorno y actividades: Enriscado en un anfiteatro natural espectacular bajo los colosales picachos calizos de Los Galayos. Sede de rutas de senderismo de alta montaña y escalada clásica, caminatas botánicas que recorren la Garganta de los Pelayos entre piscinas naturales de montaña limpia, senderos micológicos en sus frondosos pinares silvestres y avistamiento de aves rapaces de roca. PROVINCIA: SEGOVIA (Texto Plano Limpio).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40195','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles rurales premium con instalaciones de spa, antiguas casonas señoriales castellanas de sillería dorada, posadas de piedra con grandes chimeneas tradicionales de leña y apartamentos rústicos de cara al abismo. Entorno y actividades: El principal centro logístico y de acceso al Parque Natural de las Hoces del Río Duratón. Sede del inicio de la espectacular ruta de senderismo de la Senda de los Dos Ríos, caminatas hacia la Ermita de San Frutos colgada sobre el abismo del cañón, y es la meca nacional para el piragüismo y rutas en kayak fluvial por las aguas calmadas del meandro. Destaca por el turismo de avistamiento ornitológico (la mayor colonia europea de buitre leonado en roca) y senderos micológicos.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40156','rural','Oferta de turismo rural','Alojamientos rurales: Palacetes medievales y renacentistas de alquiler exclusivo dentro de una villa amurallada intacta (Conjunto Histórico), hospederías boutique reales con encanto rústico, patios empedrados de sillería y habitaciones con vigas de sabina centenarias. Entorno y actividades: Estribaciones septentrionales de la Sierra de Guadarrama. Ofrece rutas de senderismo histórico y natural que rodean sus kilométricas murallas calcáreas y su castillo del siglo XIII, caminatas de dehesa agraria entre robles y encinas centenarias donde pasta el ganado, senderos tradicionales ganaderos y cicloturismo de carretera de colinas suaves.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40181','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles boutique de estética neoclásica herreriana, parador nacional en una antigua casa de infantes palaciega, apartamentos de montaña de madera y piedra en el núcleo forestal de Valsaín, y refugios de montaña. Entorno y actividades: Vertiente norte del Parque Nacional de la Sierra de Guadarrama y de los Montes de Valsaín. Custodia el espectacular paraje de la Boca del Asno y Los Asientos a orillas del río Eresma. Ofrece las rutas de senderismo fluvial del Camino de Pesquerías Reales, ascensiones alpinas de alta dificultad hacia el Macizo de Peñalara y los Siete Picos, senderos entre pinares silvestres maduros del pinar de Valsaín, rutas invernales con raquetas de nieve y micología.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40170','rural','Oferta de turismo rural','Alojamientos rurales: Casonas porticadas tradicionales con solanas de madera que miran a la plaza elíptica, chalets de montaña independientes con chimenea de leña, y hoteles rurales de campo adaptados para familias y deportistas de nieve. Entorno y actividades: Piedemonte de la Sierra de Ayllón y nexo con la estación de esquí de La Pinilla. Custodia el espectacular Hayedo de la Pedrosa (uno de los hayedos más meridionales y protegidos de la península). Ofrece la ruta de las dehesas de robles melojos, caminatas botánicas otoñales de gran valor fotográfico, rutas de agroturismo hacia los célebres Pueblos Negros y Amarillos (como Madriguera o Alquite) integrados en su término, y micología de boletus.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40024','rural','Oferta de turismo rural','Alojamientos rurales: Posadas reales de piedra y caliza integradas en palacios renacentistas con patios porticados rústicos, antiguas casas de labranza rehabilitadas con chimeneas de campana y apartamentos turísticos rurales. Entorno y actividades: Comarca de la Sierra de Ayllón oriental, bañado por el río Aguisejo. Ofrece paseos etnográficos e históricos que rodean su torre fortificada de "La Martina" del siglo XI en la cumbre, caminatas por el desfiladero calizo del río Aguisejo entre túneles de sauces y chopos, senderos geológicos en páramos áridos calizos, cicloturismo de carretera sin tráfico y rutas micológicas de otoño.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40115','rural','Oferta de turismo rural','Alojamientos rurales: Casas de turismo de interior colgadas literalmente sobre el risco medieval amurallado, posadas con encanto rústico con vistas panorámicas al agua y apartamentos rurales para amantes del silencio. Entorno y actividades: Custodia la entrada occidental al Parque Natural de las Hoces del Río Riaza y está bañado por el Embalse de Linares del Arroyo. Ofrece rutas de senderismo geológico y ornitológico bordeando el profundo desfiladero calizo (Refugio de Rapaces de Montejo), piragüismo, vela y deportes náuticos sin motor en el embalse, paseos botánicos por sabinares centenarios y observación astronómica de cielos negros.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40162','rural','Oferta de turismo rural','Alojamientos rurales: Casas de piedra de pastores de la sierra tradicionales rehabilitadas con muros anchos aislantes, apartamentos rústicos forestales e instalaciones ligadas al turismo micológico. Entorno y actividades: Falda norte de la Sierra de Guadarrama y Somosierra. Custodia la Cueva de los Enebralejos (colosal cueva de estalactitas con necrópolis prehistórica integrada, transitable con visitas guiadas) y el Acebal de Prádena (el bosque de acebos autóctono más grande e importante del Sistema Central). Rutas de senderismo botánico bajo los acebos mágicos repletos de frutos rojos en invierno, caminatas ganaderas y recolección micológica.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40139','rural','Oferta de turismo rural','Alojamientos rurales: Complejos de cabañas de madera forestales mimetizadas bajo el pinar, apartamentos rústicos con porche de leña junto a arroyos trucheros y casas rurales de mampostería tradicional. Entorno y actividades: Valle del río Cega, falda del Puerto de Navafría. Alberga el espectacular paraje natural de El Chorro de Navafría (una imponente cascada natural de montaña de más de 20 metros de altura rodeada de inmensos pinos silvestres) y sus piscinas naturales fluviales de agua de deshielo ideales para el verano. Rutas de senderismo de alta montaña que ascienden al puerto, senderos micológicos extremos de níscalos y boletus en otoño, y esquí de fondo. PROVINCIA: GIRONA (Texto Plano Limpio).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26061','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales de arquitectura tradicional serrana con muros gruesos de mampostería y vigas de roble, antiguos palacetes burgueses reconvertidos en hoteles boutique con encanto y apartamentos de montaña a las faldas de la sierra. Entorno y actividades: En el Alto Valle del río Oja, rodeado por las cumbres de la Sierra de la Demanda. Nudo logístico principal de montaña en la región. Destaca por las rutas de senderismo hacia el pico San Lorenzo (el techo de La Rioja con 2.271 metros), paseos botánicos por el hayedo de la dehesa de Ezcaray, cicloturismo por la Vía Verde del Oja, turismo de nieve invernal en la estación de Valdezcaray y micología extrema de boletus.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26130','rural','Oferta de turismo rural','Alojamientos rurales: Alojamientos rurales integrados en antiguas edificaciones monacales o rectorales recuperadas con amplias huertas de frutales, hostales de montaña para senderistas y casas de pueblo tradicionales con grandes chimeneas de leña. Entorno y actividades: Valle del río Cárdenas, cuna del castellano y custodio de los Monasterios de Suso y Yuso (Patrimonio de la Humanidad por la UNESCO). Ofrece espectaculares rutas de senderismo de media y alta montaña que ascienden hacia los Montes Distercios, caminatas botánicas bajo frondosos hayedos y robledales del barranco de San Millán, senderos micológicos otoñales y dehesas de ganado extensivo.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26071','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles de campo premium integrados en antiguos conventos del siglo XIV y palacios señoriales con espectaculares bodegas subterráneas (calados medievales), y casonas de turismo de interior vinculadas a la viticultura tradicional. Entorno y actividades: Capital del vino de la Rioja Alta, meandro del río Ebro y los Montes Obarenes. Ofrece rutas que conectan senderos agrícolas entre interminables mares de viñedos viejos, paseos cicloturistas llanos de gran recorrido siguiendo las dehesas del río Ebro, piragüismo y kayak fluvial de baja dificultad, y paseos fotográficos de interpretación del paisaje del viñedo.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26058','rural','Oferta de turismo rural','Alojamientos rurales: Casas de piedra tradicionales del Cidacos de mampostería oscura y tejados de losa caliza, apartamentos rústicos pequeños con porche de leña e instalaciones unifamiliares en pequeños pueblos de montaña aislados de la civilización. Entorno y actividades: Alto Valle del río Cidacos, enclavado en una zona montañosa agreste. Posee una de las mayores y más espectaculares concentraciones de huellas de dinosaurio (icnitas) del mundo. Rutas de senderismo paleontológico y al aire libre que visitan decenas de yacimientos (como el yacimiento de la Virgen del Campo o de Valdecevillo) con reproducciones a escala real, caminatas geológicas por barrancos calizos y senderos micológicos.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26177','rural','Oferta de turismo rural','Alojamientos rurales: Casonas de piedra de pastores de los Cameros tradicionales rehabilitadas con muros anchos aislantes, hostales de alta montaña especializados en montañeros y albergues de naturaleza forestal. Entorno y actividades: El principal nexo logístico y de acceso al Parque Natural de la Sierra de Cebollera. Ofrece la espectacular ruta de senderismo de las Cascadas de Puente Rá, caminatas que ascienden hacia los circos glaciares del pico Cebollera (2.141 metros), senderos botánicos bajo inmensos bosques de pinos silvestres, hayedos y acebedas, observación astronómica de cielos negros certificados (Starlight) y micología de otoño.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90930','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles de interior vinculados al termalismo histórico de su célebre balneario, apartamentos turísticos rurales orientados al turismo activo y casas rurales pequeñas de montaña con chimeneas. Entorno y actividades: Valle del río Cidacos medio, encajonado entre colosales cortados calizos. Célebre a nivel nacional por las Pozas Termales de Arnedillo (surgencias de agua caliente medicinal totalmente gratuitas al aire libre junto al río que brotan a más de 52 °C aptas para el baño terapéutico). Ofrece rutas de senderismo por la Vía Verde del Cidacos, vías ferratas de montaña y escuelas de escalada deportiva en roca caliza de primer nivel, y ornitología (observación de buitres leonados).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26112','rural','Oferta de turismo rural','Alojamientos rurales: Apartamentos tradicionales de montaña con acabados en madera de pino y castaño, casas de pueblo tradicionales enriscadas en una colina caliza y cabañas de madera forestales. Entorno y actividades: Comarca de Camero Nuevo, bañado por el río Alberco alto y lindando con el Embalse de González Lacasa. Custodia las impresionantes Cuevas de Ortigosa (colosales galerías kársticas de estalactitas y estalagmitas abiertas en el interior del monte calcáreo de la Viña, transitables con visitas guiadas de aventura). Rutas senderistas que cruzan su imponente puente de hormigón sobre el abismo y dehesas forestales linderas.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26034','rural','Oferta de turismo rural','Alojamientos rurales: Palacetes de turismo de interior integrados en casonas nobiliarias señoriales del siglo XVI y XVII de sillería dorada con escudos heráldicos, apartamentos rústicos con encanto arquitectónico gótico en el casco viejo y posadas. Entorno y actividades: Asentado de forma espectacular sobre un cerro que vigila un meandro cerrado del río Ebro en la Rioja Alta (Conjunto Histórico). Ofrece paseos fotográficos de interpretación del paisaje y dehesas de viñedos, rutas de senderismo agrícola entre calados tradicionales, cicloturismo de carretera familiar sin tráfico y turismo gastronómico-rural.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26178','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales de piedra tradicionales de mampostería india oscura aisladas en valles profundos serranos del Alto Najerilla, pequeños hostales con chimeneas rústicas de suelo. Entorno y actividades: Comarca de las Siete Villas, enclavado en las estribaciones de la Sierra de la Demanda y los Picos de Urbión. Un paraje de aislamiento geográfico absoluto y silencio rural extremo. Rutas de senderismo de montaña que exploren los profundos desfiladeros del río Urbión joven, caminatas por sotos de castaños centenarios y hayedos cerrados, pesca truchera tradicional de río limpio y senderos micológicos de otoño.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26138','rural','Oferta de turismo rural','Alojamientos rurales: Parador nacional emplazado en un antiguo hospital de peregrinos del siglo XII, albergues de paso históricos y casonas castellano-riojanas tradicionales de labranza en las llanuras agrícolas de su término. Entorno y actividades: Valle del río Oja medio, hito monumental central del Camino de Santiago Francés. Rutas de senderismo plano de interpretación histórica que siguen las calzadas y dehesas agrarias de la llanura cerealista, paseos fluviales por el sendero del río Oja bajo bosques de galería, cicloturismo de paseo familiar por cañadas reales ganaderas y dehesas agrícolas de cultivos. PROVINCIA: SALAMANCA (Texto Plano Limpio).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37005','rural','Oferta de turismo rural','Alojamientos rurales: Casas de turismo rural de arquitectura popular serrana (entramados de madera, piedras de granito y balcones volados), hoteles de montaña rústicos con encanto y apartamentos rurales con chimenea encalada. Entorno y actividades: En el corazón del Parque Natural de Las Batuecas-Sierra de Francia (Reserva de la Biosfera). Destaca por las rutas de senderismo hacia el Valle de Las Batuecas (Senda del río Batuecas hasta las pinturas rupestres prehistóricas del neolítico y el Monasterio del desierto carmelita), ascensiones a la mítica Peña de Francia (1.727 metros de altitud) y el sendero etnográfico del Camino de las Raíces bajo castaños centenarios.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37250','rural','Oferta de turismo rural','Alojamientos rurales: Casonas de labranza tradicionales de los Arribes construidas en piedra de granito con patios castellano-leoneses, apartamentos rústicos y posadas de turismo activo orientadas al senderismo fluvial. Entorno y actividades: Pleno Parque Natural de Arribes del Duero. Sede de la espectacular ruta de senderismo hacia el Pozo de los Humos (imponente e histórica cascada del río Uces en caída libre de más de 50 metros rodeada de encinares y cortados calizos). Ofrece paseos por los cañones fluviales del río Duero, senderos que visitan viñedos escarpados en bancales tradicionales y observación ornitológica de primer nivel (cigüeña negra, buitre leonado y águila real).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37001','rural','Oferta de turismo rural','Alojamientos rurales: Casas de montaña tradicionales de sillería de granito gruesa con batipuertas (típicas medias puertas de madera), galerías de leña abiertas y posadas de alta montaña con chimeneas de piedra para el invierno. Entorno y actividades: Enclavado en la Sierra de Candelario (Sierra de Béjar alta). Destaca por su trazado urbano con regaderas de agua cristalina de deshielo vivas. Ofrece exigentes rutas de senderismo alpino de alta montaña hacia el pico Calvitero (2.425 metros de altitud, el techo de Salamanca) y los circos glaciares de la Hoya Moros, rutas con raquetas de nieve, senderos micológicos de otoño y densos robledales.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37009','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles boutique rurales en antiguas casas señoriales, viviendas de turismo rural empedradas con entramados de madera oscura que lucen retratos pintados de sus antiguos habitantes en las fachadas, y hostales con chimeneas de leña rústicas. Entorno y actividades: Conjunto Histórico en el corazón de la Sierra de Francia profunda. Sede de la famosa y fotogénica ruta de senderismo del Camino del Agua (un sendero circular homologado que fusiona esculturas de autores contemporáneos al aire libre con la fronda del bosque mediterráneo). Ofrece caminatas bajo sotos umbríos de castaños viejos, rutas micológicas otoñales y paseos fluviales por arroyos de montaña de aguas limpias.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49065','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales cimentadas sobre roca granítica pura, hostales rurales con encanto enriscados y apartamentos de interior vinculados a una colosal red de bodegas subterráneas medievales excavadas en la roca viva (calados históricos). Entorno y actividades: Capital de los Arribes del Duero zamoranos (Parque Natural). Ofrece espectaculares rutas de senderismo hacia miradores colgados sobre el vacío (Mirador del Castillo, Mirador de las Escaleras) con vistas verticales al río Duero encajonado en cañones graníticos brutales. Cruceros fluviales en barca por los cañones de agua, dehesas mediterráneas de olivos y viñedos viejos de colina (enoturismo), y ornitología.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37008','rural','Oferta de turismo rural','Alojamientos rurales: Alojamientos rurales intramuros dentro de una villa medieval amurallada sobre una colina escarpada, castillos medievales reconvertidos parcialmente para pernocta de lujo, posadas serranas y apartamentos rústicos familiares. Entorno y actividades: Confluencia de los ríos Francia y San Benito, en la Sierra de Francia. Sede de la ruta de senderismo del Camino de los Prodigios (itinerario artístico-natural entre robledales y viñedos viejos). Ofrece paseos por las dehesas tradicionales salmantinas, caminatas por los profundos valles forestales húmedos que cobijan líquenes y setas en temporada, y avistamiento de aves rapaces de bosque.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37003','rural','Oferta de turismo rural','Alojamientos rurales: Parador de turismo nacional emplazado en el imponente castillo medieval de Enrique II de Trastámara, grandes cortijos ganaderos salmantinos con picaderos de caballos y fincas de agroturismo destinadas a la cría tradicional del toro bravo y el cerdo ibérico de bellota. Entorno y actividades: Cuenca del río Águeda. Ofrece espectaculares rutas de senderismo llano de interpretación ambiental por el Campo Charro, caminatas agrícolas entre encinares centenarios de dehesas maduras infinitas, paseos fluviales por el sendero del Águeda con playas fluviales, rutas cicloturistas de llanura alta y observación ornitológica de aves esteparias.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37285','rural','Oferta de turismo rural','Alojamientos rurales: Casas de piedra tradicionales de mampostería antigua de grano granítico, apartamentos rústicos acogedores en el casco fortificado a la sombra del castillo de don Dionís de Portugal y posadas de campiña alta. Entorno y actividades: Comarca de El Abadengo, en los límites de Arribes del Duero meridional. Rutas de senderismo de interpretación etnográfica e histórica (Ruta de las Fortificaciones de Frontera), caminatas hacia el cañón del río Águeda inferior, senderos micológicos de monte bajo y dehesa, y paseos agrícolas entre olivares centenarios y almendros que florecen de forma espectacular en invierno.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37006','rural','Oferta de turismo rural','Alojamientos rurales: Posadas reales neoclásicas en antiguas casonas de cantería, casas de labranza tradicionales salmantinas con amplios patios de carruajes, y apartamentos rurales familiares de interior. Entorno y actividades: Asentado de forma monumental sobre un meandro de roca granítica del río Tormes bajo (Conjunto Histórico). Ofrece la Senda Fluvial del río Tormes, un tramo de bosque de galería maduro e islas protegidas. Rutas de senderismo hacia los campos de dehesa del Campo Charro norte, paseos de interpretación botánica entre encinas viejas y canchales de granito liso, y rutas micológicas otoñales. PROVINCIA: MURCIA (Texto Plano Limpio).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30028','rural','Oferta de turismo rural','Alojamientos rurales: Cortijos tradicionales de montaña construidos en sillería de piedra caliza con chimeneas de leña, complejos rústicos de cabañas de madera forestales y casas de cal de pueblo serrano enclavadas bajo su imponente castillo de la Orden de Santiago. Entorno y actividades: En el corazón del interior montañoso más abrupto e indómito de la región. Custodia el paraje natural de los Calares de la Santa y la Sierra de Mojantes. Destaca por el sendero fluvial de La Puerta (espectacular caminata sombría por el cauce del río Alhárabe entre estrechos cañones de roca caliza y pozas de agua cristalina aptas para el baño veraniego), rutas de senderismo de alta montaña que ascienden al pico Revolcadores (techo de la región con 2.014 metros de altitud), senderos micológicos otoñales y arte rupestre (Patrimonio de la Humanidad).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30008','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales integradas en fincas forestales y de agricultura de colina, complejos orientados al turismo activo y la escalada deportiva, hostales de montaña a las faldas del Parque y apartamentos rústicos. Entorno y actividades: Principal nudo logístico y de acceso al Parque Natural de Sierra Espuña. Ofrece las rutas de senderismo que recorren el Valle de Leiva, la Senda del Dinosaurio con puentes colgantes, y caminatas geológicas interpretativas por los espectaculares Pozos de la Nieve del siglo XVI integrados en las cumbres alpinas. Destaca por las dehesas forestales de pino carrasco y laricio más densas del levante, y es un destino con certificación Starlight por la excelente calidad de sus cielos nocturnos para la observación astronómica.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30015','rural','Oferta de turismo rural','Alojamientos rurales: Palacetes de turismo de interior integrados en antiguas casonas nobiliarias de sillería dorada con escudos heráldicos en el casco histórico medieval, fincas de agroturismo ganadero y apartamentos rurales familiares con amplios porches rústicos. Entorno y actividades: Nudo monumental del Noroeste murciano flanqueado por las Sierras de la Sagra y de las Cabras. Custodia el idílico paraje natural de las Fuentes del Marqués (un oasis botánico espectacular repleto de manantiales caudalosos de agua pura de deshielo, riachuelos y cuevas artificiales en mitad de un bosque maduro de encinas y quejigos). Ofrece rutas de senderismo por la Vía Verde del Noroeste (antiguo trazado de tren ideal para familias y cicloturismo), caminatas de media montaña y paseos fotográficos.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30013','rural','Oferta de turismo rural','Alojamientos rurales: Casas de campo tradicionales de labranza vinculadas al agroturismo arrocero a orillas del agua, apartamentos rústicos con porche de leña y hostales de cañón orientados a los deportes de aventura y aguas bravas. Entorno y actividades: Bañado por el curso alto del río Segura y su confluencia con el río Mundo. Alberga el Monumento Natural del Cañón de Almadenes (espectacular desfiladero kárstico angosto de paredes de roca caliza verticales de más de 100 metros de altura sobre el Segura). El mayor hub de turismo activo de la región; destaca por la práctica de rafting, hidrospeed y kayak en aguas bravas. Rutas de senderismo ecológico que visitan el Santuario de la Virgen de la Esperanza (excavado directamente en la roca de la gruta caliza fluvial) y paseos ornitológicos en arrozales.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30039','rural','Oferta de turismo rural','Alojamientos rurales: Alojamientos rurales unifamiliares integrados en antiguas casas de labranza tradicionales con almazaras de aceite recuperadas, fincas rústicas de frutales y apartamentos de montaña en las pedanías del Parque (como La Santa). Entorno y actividades: Vertiente sur de la Sierra de Espuña caliza, resguardada de los vientos del norte. Ofrece la espectacular ruta de senderismo del Barranco de Gebas, un paisaje geológico único de "badlands" o cárcavas arcillosas de aspecto lunar que mueren en las aguas de color azul turquesa del Embalse de Algeciras. Caminatas hacia el Santuario de Santa Eulalia rodeado de pinares viejos de repoblación, rutas de cicloturismo de montaña (BTT) de alto nivel y visitas al yacimiento argárico de La Bastida en plena naturaleza.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30022','rural','Oferta de turismo rural','Alojamientos rurales: Casas de campo señoriales de interior con anchos muros de mampostería integradas en bodegas tradicionales y viñedos de altura, posadas de interior rústicas y apartamentos rurales familiares. Entorno y actividades: Altiplano murciano septentrional, rodeado por el espacio protegido de la Sierra del Carche. Ofrece rutas que conectan senderos agrícolas entre interminables campos de cepas viejas de uva monastrell cultivadas en colinas áridas, caminatas de media montaña que ascienden hacia el pico de la Madama (1.371 metros) entre pinares silvestres y dehesas calizas secas, senderos botánicos, cicloturismo de carretera sin tráfico y enoturismo de primer nivel.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30029','rural','Oferta de turismo rural','Alojamientos rurales: Casas de cal de pueblo andalusí de alquiler íntegro con chimeneas rústicas, apartamentos rústicos pequeños vinculados al agroturismo de almendros y frutales de hueso, y posadas de interior. Entorno y actividades: Cuenca del río Mula y falda septentrional de Sierra Espuña. Célebre por el espectáculo botánico primaveral de la floración masiva del almendro que tiñe sus campos de tonos blancos y rosados. Rutas de senderismo hacia el paraje de Fuente Caputa (un entramado de pozas naturales de agua cristalina y manantiales en mitad de un cañón calizo rústico ideales para el baño en verano), cicloturismo por la Vía Verde del Noroeste y senderos históricos que rodean su castillo del siglo XVI alto.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30017','rural','Oferta de turismo rural','Alojamientos rurales: Casonas solariegas de sillería de piedra caliza con espectaculares balconadas de forja tradicional en un casco histórico medieval galardonado (Conjunto Histórico), apartamentos rústicos de montaña unifamiliares con jardín y barbacoa. Entorno y actividades: Comarca del Noroeste de interior. Ofrece paseos etnográficos de aislamiento y caminatas botánicas, rutas de senderismo que recorren la Sierra de la Peña Rubia con escuelas de escalada clásica y deportiva en paredes de roca, caminatas llanas fluviales por el sendero del río Argos bajo túneles vegetales umbríos de alisos y chopos, y rutas cicloturistas de montaña (BTT). PROVINCIA: TERUEL (Texto Plano Limpio).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19190','rural','Oferta de turismo rural','Alojamientos rurales: Casonas solariegas de sillería dorada de la nobleza molinesa con amplios patios interiores rústicos, hoteles de montaña de piedra y madera, y apartamentos rurales con vistas directas a su colosal alcázar medieval. Entorno y actividades: Eje logístico y natural del Geoparque Mundial de la UNESCO de la Comarca de Molina-Alto Tajo. Destaca por la emblemática ruta de senderismo del Barranco de la Hoz (un desfiladero espectacular de areniscas rojizas esculpido por el río Gallo con agujas de roca caprichosas), senderos que se adentran en el Parque Natural del Alto Tajo, micología otoñal y es una zona de máxima pureza para la observación astronómica nocturna con certificación Starlight.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19060','rural','Oferta de turismo rural','Alojamientos rurales: Auténticas casas rurales de Arquitectura Negra construidas íntegramente con losas de pizarra oscura y piedra caliza del entorno, apartamentos rústicos íntimos con chimeneas de leña ideales para parejas y alojamientos ecosostenibles de aislamiento serrano. Entorno y actividades: En el corazón del Parque Natural de la Sierra Norte de Guadalajara, a las faldas del Pico Ocejón. Ofrece paseos fotográficos de naturaleza interior y aislamiento absoluto. Destaca por la espectacular ruta de senderismo que asciende a las Cascadas del Aljibe (doble salto de agua natural en un cañón de pizarra), caminatas de ascensión al Ocejón (2.048 metros de altitud) entre robledales y brezales, y senderos micológicos de otoño.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19257','rural','Oferta de turismo rural','Alojamientos rurales: Parador de turismo nacional emplazado de forma monumental en el imponente castillo medieval fortificado, casonas nobiliarias señoriales reconvertidas en hoteles boutique en el casco histórico e históricas fincas de labranza. Entorno y actividades: Valle del río Henares y nexo de acceso al Parque Natural del Barranco del Río Dulce. Ofrece la espectacular ruta de senderismo del río Dulce (caminata plana por el fondo de un angosto cañón calizo bajo cortados donde anidan grandes rapaces y que aloja el mirador de Félix Rodríguez de la Fuente), senderos botánicos entre sabinares y quejigales centenarios, y cicloturismo de carretera familiar.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19216','rural','Oferta de turismo rural','Alojamientos rurales: Complejos de cabañas forestales de madera mimetizadas bajo el pinar, hostales de alta montaña especializados en pescadores y montañeros, y casas rurales de piedra junto al río con chimeneas rústicas de campana. Entorno y actividades: En el interior del Parque Natural del Alto Tajo profundo. Sede de rutas de senderismo fluvial escarpadas y espectaculares que transitan entre estrechos cañones calizos, pozas de agua helada turquesa cristalina ideales para el baño y el descanso estival en la Laguna de Taravilla o el Salto de Poveda. Pesca deportiva de trucha con mosca sin muerte en ríos vírgenes limpios, piragüismo y senderos micológicos extremos.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19311','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales de arquitectura negra puras que conservan un entramado urbano impecable de piedra y pizarra oscura calada con madera de roble, y apartamentos turísticos pequeños con chimeneas de leña. Entorno y actividades: Sierra Norte de Guadalajara, en un valle protegido de alta montaña. Custodia la espectacular ruta de senderismo hacia la Chorrera de Despeñaelagua (una imponente cascada natural de montaña de más de 120 metros de caída escalonada sobre roca caliza). Caminatas que ascienden a la Chorrera desde prados ganaderos altos, rutas micológicas otoñales bajo hayedos y quejigales, y miradores estelares Starlight.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19212','rural','Oferta de turismo rural','Alojamientos rurales: Posadas de turismo de interior integradas en conventos franciscanos y palacios del siglo XVI y XVII de sillería dorada con escudos heráldicos, apartamentos con encanto arquitectónico en el casco medieval y casas de labranza de la Alcarria. Entorno y actividades: Comarca de La Alcarria meridional, valle de los ríos Arlés y Guadiela. Ofrece rutas que conectan con senderos agrícolas entre colinas de monte bajo mediterráneo aromático (tomillo, espliego, romero), caminatas tranquilas de dehesa agraria e interpretación apícola (rutas de la miel de la Alcarria), cicloturismo de carretera familiar sin tráfico y paseos fotográficos.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19333','rural','Oferta de turismo rural','Alojamientos rurales: Casas de montaña de piedra caliza tradicionales con muros anchos aislantes, apartamentos rústicos forestales integrados en pequeños núcleos del valle y albergues de naturaleza fluvial. Entorno y actividades: Centro geográfico y de interpretación del Parque Natural del Alto Tajo. Alberga el espectacular paraje de la Escaleruela y el Mirador de Zaorejas colgado sobre un meandro vertical cerrado con caídas de roca de más de 150 metros. Rutas de senderismo de cañón de río bajo túneles vegetales umbríos de pinos laricios, quejigos y tejos salvajes, caminatas micológicas y observación astronómica (cielos negros certificados Starlight).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19092','rural','Oferta de turismo rural','Alojamientos rurales: Palacetes de turismo de interior vinculados al agroturismo vitivinícola, casas de labranza tradicionales de campiña alta con patios de carruajes y apartamentos rurales de cara a su plaza porticada medieval. Entorno y actividades: Piedemonte de la Sierra de Ayllón occidental, bañado por el río Aliendre. Ofrece las rutas de senderismo que suben a las ruinas de su castillo del siglo IX alto, caminatas agrícolas entre dehesas tradicionales y campos de viñedos viejos de altura, cicloturismo de carretera, turismo gastronómico-rural y base sur de acceso a los cañones de la Sierra Norte.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19065','rural','Oferta de turismo rural','Alojamientos rurales: Casas de aldea de mampostería de piedra tradicionales de montaña alta de aislamiento, apartamentos rústicos pequeños con chimenea de piedra de suelo y albergues forestales de paso. Entorno y actividades: Límite noroccidental de la Sierra Norte alta, frontera con Segovia. Custodia el Parque Natural del Hayedo de Tejera Negra (el bosque de hayas más meridional de Europa central, Patrimonio de la Humanidad por la UNESCO). Espectaculares y protegidas rutas de senderismo botánico otoñal de gran valor fotográfico (Senda de las Carretas) bajo las hayas centenarias mezcladas con tejos, abedules y acebos mágicos, senderos pastoriles de montaña, ríos trucheros limpios (río Lillas) y recolección micológica.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19291','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles de campo y posadas de turismo interior articulados en torno al patrimonio termal tradicional de su Real Balneario de Carlos III, apartamentos de ribera y casas de cal con porche junto al río Cifuentes. Entorno y actividades: Confluencia de los ríos Tajo y Cifuentes, a los pies de las Tetas de Viana (muelas gemelas calizas singulares). Célebre por el espectacular paraje de las Cascadas del río Cifuentes (un torrente de agua que cae en cascadas y saltos de agua rústicos ruidosos en pleno casco urbano entre puentes y vegetación de ribera). Rutas de senderismo de ascensión a las Tetas de Viana (Monumento Natural), paseos fluviales por el Tajo, piragüismo y pesca deportiva. PROVINCIA: BURGOS (Texto Plano Limpio).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09905','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales de piedra tradicionales calizas del cañón con terrazas sobre el agua, hostales rústicos con encanto de río y apartamentos para senderistas. Entorno y actividades: En el interior del Parque Natural de las Hoces del Alto Ebro y Rudrón. Célebre por su cascada natural gigante de agua turquesa que brota de la Cueva del Agua y cruza el pueblo en terrazas de toba. Ofrece la Senda de las Hoces del Ebro, senderismo geológico entre formaciones kársticas con formas de "ruinas de ciudad", escalada y observación de buitre leonado.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09216','rural','Oferta de turismo rural','Alojamientos rurales: Casas de piedra tradicionales de Las Merindades de alquiler íntegro con chimenea, pequeños apartamentos rústicos con porche de leña junto al cauce. Entorno y actividades: Famoso por su monumental Puente de Dios, un colosal arco de roca natural esculpido de forma kárstica por el río Nela sobre el que se asienta el pueblo. Rutas senderistas de la Senda del río Nela, caminatas hacia la Cascada de la Mea, paseos ecunimes y senderos micológicos de robledal.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14075','rural','Oferta de turismo rural','Alojamientos rurales: Casas de pueblo blanco andaluz de cal e impecable piedra caliza con chimeneas de leña, hoteles rurales boutique encaramados al risco medieval y apartamentos rústicos con vistas directas al cañón fluvial. Entorno y actividades: En el corazón del Parque Natural de las Sierras Subbéticas (Geoparque de la UNESCO). Destaca por la espectacular y mítica ruta de senderismo del Río Bailón (caminata que cruza profundos cañones y lapiaces calcáreos), la visita guiada a la Cueva de los Murciélagos (colosal yacimiento arqueológico del neolítico con pinturas rupestres integradas en la roca), paseos por la Vía Verde de la Subbética para cicloturismo y senderos micológicos.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14055','rural','Oferta de turismo rural','Alojamientos rurales: Palacetes barrocos de interior en su histórico barrio de la Villa, casas de turismo de labranza vinculadas al agroturismo olivarero, cortijos tradicionales andaluces con patios de azulejos y fuentes de agua fresca. Entorno y actividades: Falda norte de las Sierras Subbéticas. Ofrece rutas de senderismo de alta montaña que ascienden al pico Tiñosa (techo de la provincia de Córdoba con 1.568 metros de altitud), paseos fotográficos de naturaleza entre olivares de pendiente extrema, caminatas botánicas que visitan el paraje del manantial de la Fuente del Rey, y cicloturismo de carretera sin tráfico.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14036','rural','Oferta de turismo rural','Alojamientos rurales: Grandes cortijos ganaderos señoriales de sillería rústica Morena, fincas de montería con picaderos de caballos, complejos de cabañas de madera forestales y casas de campo aisladas de la civilización. Entorno y actividades: Custodia el Parque Natural de Sierra de Hornachuelos. Alberga uno de los bosques mediterráneos y dehesas de encinas y alcornoques mejor conservados del sur peninsular. Rutas de senderismo de aventura por el Sendero del Guadalora (bosque de galería fluvial denso y cerrado), caminatas hacia el embalse de Bembézar (kayak, piragüismo de interior), observación ornitológica de grandes rapaces (buitre negro, águila imperial) y dehesas de ganado extensivo.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14054','rural','Oferta de turismo rural','Alojamientos rurales: Casonas de labranza tradicionales de Los Pedroches construidas en piedra de grano granítico grueso con portalones rústicos, apartamentos turísticos de interior y alojamientos de agroturismo dedicados a la cría tradicional del cerdo ibérico de bellota. Entorno y actividades: Capital de la Comarca de Los Pedroches. Ofrece una experiencia única de turismo rural en un mar infinito de encinas centenarias. Rutas de senderismo de interpretación ambiental por la dehesa de Pozoblanco, caminatas llanas ideales para cicloturismo familiar de relax por las cañadas reales ganaderas, senderos micológicos otoñales y es una zona de máxima pureza para la observación astronómica nocturna al contar con certificación internacional Starlight.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17006','rural','Oferta de turismo rural','Alojamientos rurales: Casas de campo de interior unifamiliares con porches de roca caliza, hoteles rurales señoriales en el casco monumental e históricas posadas con patios andaluces rústicos llenos de macetas y hilos de agua. Entorno y actividades: Centro geográfico de las Sierras Subbéticas. Custodia el espectacular paraje natural del Picacho de la Sierra de Cabra (conocido como el "Balcón de Andalucía", una colosal muela calcárea con una ermita en su cumbre de más de 1.200 metros). Rutas de senderismo geológico por la Senda de la Fuente de las Piedras, caminatas kársticas por la sima de Cabra, y cicloturismo familiar por la Vía Verde del Aceite.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26041','rural','Oferta de turismo rural','Alojamientos rurales: Casas de piedra tradicionales de montaña con muros anchos aislantes, apartamentos rústicos de pinar e instalaciones unifamiliares en pequeños núcleos de dehesa. Entorno y actividades: En el interior del Parque Natural de la Sierra de Cardeña y Montoro. Espectaculares rutas de senderismo plano que transitan entre dehesas maduras de encinas combinadas con bloques de granito lisos de erosión berroqueña, caminatas fluviales que recorren el río Yeguas (paraíso ecológico donde habita el lince ibérico en libertad), senderos micológicos de otoño y rutas ecuestres.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17002','rural','Oferta de turismo rural','Alojamientos rurales: Casas de pueblo tradicionales andaluzas de cal blanca de alquiler íntegro a los pies de su colosal e impecable castillo medieval de película, hostales de campo de interior y apartamentos rurales. Entorno y actividades: Vega del Guadalquivir medio, falda meridional de Sierra Morena y lindando con el Embalse de La Breña II. Ofrece rutas de senderismo que bordean el gran lago de interior, piragüismo, vela y kayak náutico, caminatas forestales bajo pinares de repoblación viejos y encinares de dehesa de Sierra Morena, y rutas de agroturismo.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14043','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales excavadas o asentadas sobre la roca de piedra moliz rojiza tradicional en el casco histórico colgado sobre el meandro, y fincas olivareras señoriales de campiña alta. Entorno y actividades: Bañado por un colosal y monumental meandro cerrado del río Guadalquivir (Monumento Natural). Ofrece rutas de senderismo fluvial por el sendero de las Aceñas, caminatas micológicas otoñales e interpretación ambiental por la dehesa del Parque Natural de Cardeña y Montoro norte, y rutas cicloturistas de carretera de colinas suaves.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14035','rural','Oferta de turismo rural','Alojamientos rurales: Casonas solariegas de granito de la comarca de Los Pedroches occidentales con patios de carruajes, posadas de turismo rural tradicionales de llanura alta y apartamentos rurales. Entorno y actividades: Entorno del altiplano ganadero de dehesas. Rutas de senderismo e interpretación etnográfica e histórica (Senda del Camino de Santiago Mozárabe), caminatas llanas ideales para cicloturismo de paseo entre encinares centenarios donde se observa fauna de dehesa, ornitología de aves esteparias y rapaces, y turismo astronómico nocturno con cielos limpios Starlight. PROVINCIA: GRANADA - ZONA NORTE Y ALTIPLANO (Texto Plano Limpio).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18086','rural','Oferta de turismo rural','Alojamientos rurales: Complejos trogloditas turísticos (barrios de casas cueva tradicionales excavadas en badlands), y alojamientos de diseño bioclimático exóticos aislados en mitad del desierto. Entorno y actividades: Corazón del Geoparque de Granada. Custodia el Parque Megalítico de Gorafe (la mayor concentración de dólmenes prehistóricos de España, con más de 240 megalitos integrados en la dehesa árida). Rutas de senderismo geológico por el cañón del río Gor, caminatas fotográficas por el Desierto de Gorafe (paisaje de arcillas rojas brutales tipo Colorado), cicloturismo BTT y observación de estrellas con cielos limpios Starlight.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18082','rural','Oferta de turismo rural','Alojamientos rurales: Alojamientos cueva tradicionales rehabilitados en barrios históricos colgados, apartamentos rústicos de interior y casas de campo de labranza tradicionales de la vega del río. Entorno y actividades: Altiplano granentino nororiental. Ofrece rutas de senderismo arqueológico de primer nivel hacia el yacimiento argárico de Castellón Alto (poblado de la Edad del Bronce excavado de forma virgen en la roca de la colina) y la necrópolis ibérica de Tútugi, senderos llanos de cicloturismo familiar entre badlands de yeso y observación astronómica nocturna.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18146','rural','Oferta de turismo rural','Alojamientos rurales: Casas cueva de turismo rural unifamiliares con porches de cal, apartamentos rústicos pequeños en un casco histórico dominado por su alcazaba de los siete torreones y cortijos aislados en la dehesa. Entorno y actividades: Zona norte extrema del altiplano, cuna de los yacimientos paleontológicos clave del Pleistoceno inferior (Venta Micena, Fuente Nueva). Rutas de senderismo de interpretación paleontológica y arqueológica por la cuenca lacustre seca, paseos hacia la piscina natural de Fuencaliente (manantial vivo de agua templada constante todo el año donde nadan peces en libertad), y senderos ganaderos. PROVINCIA: LUGO (Texto Plano Limpio).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33071','rural','Oferta de turismo rural','Alojamientos rurales: El hotel rural pionero que inauguró el turismo verde en España, casas de aldea tradicionales con gruesos muros de piedra y tejados de pizarra negra, y antiguas rectorales rehabilitadas en mitad del pinar. Entorno y actividades: Cuna histórica del turismo rural español, integrado en la Reserva de la Biosfera del Río Eo, Oscos y Terras de Burón. Destaca por la emblemática Senda Verde y la Ruta del Agua (recorrido etnográfico que transita entre cascadas, molinos hidráulicos y el impresionante conjunto del mazo de Os Teixois). Ofrece senderos bajo bosques mágicos de robles y castaños, ríos salmoneros de aguas cristalinas y talleres artesanales vivos de cuchillería.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22901','rural','Oferta de turismo rural','Alojamientos rurales: Bordas de montaña familiares con grandes chimeneas tradicionales de campana pirenaicas, casas de turismo rural de piedra y madera vista y hostales rústicos para montañeros. Entorno y actividades: En el Parque Natural de los Valles Occidentales. Alberga la espectacular Selva de Oza (bosque atlántico cerrado de hayas, abetos centenarios y tejos). Rutas de senderismo por la antigua Calzada Romana que sigue el curso del río Aragón Subordán, ascensión alpina al emblemático Castillo de Acher, senderos hacia el Ibón de Acherito y avistamiento del oso pardo.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04017','rural','Oferta de turismo rural','Alojamientos rurales: Cortijos tradicionales andaluces restaurados con muros gruesos de cal, eco-lodges integrados en el paisaje volcánico, casas de campo independientes y apartamentos rústicos de interior en pedanías de montaña (como Huebro o Fernán Pérez). Entorno y actividades: Vertiente de interior de la Reserva de la Biosfera del Parque Natural de Cabo de Gata-Níjar. Destaca por la espectacular ruta de senderismo del Agua de Huebro (caminata que sigue un histórico canal de molinos hidráulicos tradicionales entre huertas y oasis), senderos geológicos entre calderas volcánicas extintas, caminatas hacia los pozos de los frailes, cicloturismo BTT y ornitología.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04014','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles de montaña de estética alpujarreña, grandes villas rurales de alquiler íntegro con chimeneas de leña, complejos de cabañas de madera forestales y casas de turismo de aldea blanqueadas junto al río. Entorno y actividades: Capital y centro natural de la Alpujarra Almeriense, a las faldas del Parque Nacional de Sierra Nevada. Destaca por la ruta de senderismo de la Hidroeléctrica (espectacular e histórico itinerario llano que transita sobre un canal de agua excavado en los profundos riscos del río Andarax). Ofrece paseos botánicos por el paraje del Nacimiento, rutas de alta montaña alpina, senderos de castañares y quejigales, micología y turismo enológico de altura.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04088','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales de campo independientes aisladas en mitad del llano, apartamentos rústicos de diseño bioclimático orientados al aislamiento desértico, y cortijos agrícolas tradicionales de olivares. Entorno y actividades: Custodia el Paraje Natural del Desierto de Tabernas (el único desértico propiamente dicho de todo el continente europeo). Ofrece una experiencia única de turismo rural en un entorno de cárcavas y ramales arcillo-arenosos (badlands). Destaca por la ruta de senderismo del Cañón de Alfaro, caminatas geológicas interpretativas por los escenarios del spaghetti western, cicloturismo de desierto y es un destino con certificación Starlight por la nitidez extrema de sus cielos para la observación astronómica nocturna.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04025','rural','Oferta de turismo rural','Alojamientos rurales: Casas de pueblo tradicionales con fachadas escalonadas de mampostería blanca a la sombra de su castillo nazarí alto, apartamentos turísticos integrados en antiguas instalaciones y estaciones ferroviarias mineras restauradas, y posadas serranas. Entorno y actividades: Vertiente norte de la Sierra de los Filabres. Punto de partida neurálgico de la Vía Verde del Almanzora (antiguo trazado ferroviario minero ideal para familias y cicloturismo). Ofrece la espectacular ruta de senderismo del sendero de los mineros hacia el poblado abandonado de Las Menas en pleno bosque de montaña, caminatas bajo pinares silvestres silvestres viejos, senderos micológicos de otoño y turismo gastronómico de secaderos tradicionales.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04098','rural','Oferta de turismo rural','Alojamientos rurales: Casonas solariegas de sillería dorada con escudos heráldicos, palacetes de interior con encanto andaluz rústico a las faldas de su monumental castillo del siglo XVI, y cortijos ganaderos aislados en el altiplano. Entorno y actividades: Parque Natural de Sierra de MaríaLos Vélez. Ofrece espectaculares rutas de senderismo arqueológico hacia la Cueva de los Letreros (donde se descubrió el Índalo prehistórico, Patrimonio de la Humanidad por la UNESCO). Caminatas forestales de interpretación botánica entre inmensas masas boscosas de pinos carrascos y encinares centenarios maduros, senderos micológicos, rutas de raquetas de nieve invernales en las cumbres y dehesas ganaderas.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04010','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales unifamiliares con porches de roca, palacetes agrícolas tradicionales burgueses del siglo XVIII reconvertidos en hoteles de campo en el Valle de Laujar, y posadas alpujarreñas tradicionales. Entorno y actividades: Corazón de la Alpujarra almeriense, cuenca alta del río Andarax. Ofrece la ruta de senderismo de las Acequias del río, caminatas de media montaña por la Sierra de Gádor, paseos botánicos por dehesas de encinas viejas y almendros que tiñen el paisaje de tonos rosados durante la floración invernal, cicloturismo de carretera familiar y turismo gastronómico.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90403','rural','Oferta de turismo rural','Alojamientos rurales: Casas de piedra tradicionales de montaña con muros anchos aislantes, apartamentos rústicos de pinar e instalaciones unifamiliares de mampostería en las alturas de la dehesa alpina. Entorno y actividades: Vertiente norte del Parque Nacional de Sierra Nevada (Comarca del Río Nacimiento). Rutas de senderismo exigentes de alta montaña que ascienden hacia el puerto de la Ragua, caminatas fluviales por el sendero del río Abrucena entre saltos de agua y pozas de agua de deshielo helada cristalina, senderos micológicos otoñales extremos (recogida de níscalos), y paseos botánicos por densos bosques de castaños y robles melojos de la umbría. PROVINCIA: LLEIDA - PREPIRINEO Y SUR DE MONTAÑA (Texto Plano Limpio).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25193','rural','Oferta de turismo rural','Alojamientos rurales: Masías tradicionales prepirenaicas rehabilitadas con muros gruesos de piedra caliza, apartamentos rústicos de montaña con chimeneas de leña y hostales con encanto enclavados en el casco amurallado medieval. Entorno y actividades: En el corazón de la Vall de Lord (Prepirineo del Solsonès) y flanqueado por el Embalse de Llosa de Cavall. Destaca por la espectacular ruta de senderismo del Santuario de Lord (enclavado de forma inverosímil en lo alto de una colosal muela calcárea), caminatas botánicas que recorren las fuentes del río Cardener, senderos micológicos otoñales extremos, y kayak de interior, piragüismo y dehesas de remo en las aguas turquesas del embalse. PROVINCIA: SORIA (Castilla y León - Datos Curados).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25207','rural','Oferta de turismo rural','Alojamientos rurales: Colosales masías de agroturismo señoriales aisladas en mitad de dehesas boscosas, casas de labranza tradicionales con huertos ecológicos y casonas de piedra con corredores de madera. Entorno y actividades: Entorno prepirenaico de la comarca del Solsonès. Destaca por la ruta de senderismo de la Ribera Salada (un paraje fluvial virgen con espectaculares pozas naturales y puentes románicos de granito ideales para el baño y el descanso estival). Ofrece caminatas de interpretación de la naturaleza por dehesas de pinos silvestres y robledales, senderos micológicos otoñales y cicloturismo familiar de relax.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25171','rural','Oferta de turismo rural','Alojamientos rurales: Casas de turismo rural empotradas en calles del casco antiguo, hostales rústicos orientados al excursionismo y los deportes de aventura de interior, y apartamentos de montaña con vistas a los cañones fluviales. Entorno y actividades: Confluencia del río Flamisell y el Noguera Pallaresa, a las orillas del Embalse de Sant Antoni. Sede de rutas que conectan con los senderos del desfiladero de Collegats (un espectacular cañón calizo estrecho cortado por el río con paredes de roca verticales de más de 100 metros). Ofrece senderismo geológico para ver formaciones como l''Argenteria, barranquismo técnico, piragüismo de río, kayak y vela en el embalse.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25234','rural','Oferta de turismo rural','Alojamientos rurales: Casas de labranza tradicionales del Pallars Jussà de alquiler íntegro con chimeneas rústicas de campana, apartamentos de montaña en pequeñas aldeas aisladas de la civilización y posadas rurales. Entorno y actividades: Cuenca de la Hoya de Tremp, integrado en el Geoparque Orígens (UNESCO). Ofrece espectaculares rutas de senderismo arqueológico e histórico hacia los yacimientos de dinosaurios y dólmenes prehistóricos de la Terreta, caminatas geológicas interpretativas por los valles de fractura calizos, cicloturismo de carretera, y es una zona de máxima pureza para la observación del cielo estrellado certificado (Destino y Reserva Starlight del Montsec).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25077','rural','Oferta de turismo rural','Alojamientos rurales: Casas de piedra tradicionales de montaña con solanas rústicas de madera, hostales orientados a montañeros y escaladores, y apartamentos rurales pequeños cerca del río Segre. Entorno y actividades: Valle del río Segre medio, en las estribaciones de la Sierra de Boumort. Capital prepirenaica de la paleontología; destaca por albergar espectaculares yacimientos con nidos y huevos reales de dinosaurio fosilizados (visitas guiadas interpretativas en el paraje natural). Rutas de senderismo de montaña, escuelas de escalada clásica y deportiva en paredes de roca caliza vertical de primer nivel, y senderos micológicos.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25155','rural','Oferta de turismo rural','Alojamientos rurales: Casas de pueblo tradicionales con fachadas de mampostería antigua y calles estrechas rústicas, apartamentos boutique rurales y alojamientos orientados a los deportes de aventura aérea. Entorno y actividades: Valle del Segre alto, falda de la montaña de la Montaña de Alinyà. Un referente absoluto para los deportes de vuelo libre (parapente) gracias a las corrientes térmicas estables de su montaña. Rutas de senderismo hacia el paraje natural de los Lagos de Alinyà, caminatas por los cañones calizos de Tres Ponts, senderos micológicos otoñales y turismo gastronómico-rural. SORIA - TIERRAS DE ALMAZÁN Y SUR DE LA MESETA (Texto Plano Limpio).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42020','rural','Oferta de turismo rural','Alojamientos rurales: Posadas castellanas integradas en antiguas casonas porticadas de sillería de los siglos XVII y XVIII, hoteles boutique rurales con vistas al casco monumental y apartamentos rústicos unifamiliares con chimenea junto al río Duero. Entorno y actividades: Centro neurálgico e histórico de la dehesa soriana meridional. Destaca por el sendero fluvial de las Riberas del Duero (caminata plana bajo un maduro bosque de galería de chopos y sauces), rutas de senderismo plano de largo recorrido (GR-14 Senda del Duero), paseos de observación ornitológica en dehesas mixtas de encinas y pinos piñoneros, cicloturismo familiar y micología.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42123','rural','Oferta de turismo rural','Alojamientos rurales: Casas de turismo rural que conservan la arquitectura popular renacentista y castellana (muros de piedra, entramados rústicos de madera y teja curva), y apartamentos rústicos pequeños que miran a su fotogénica plaza mayor señorial. Entorno y actividades: Entorno de la cuenca alta del río Morón. Ofrece tranquilas rutas de senderismo llano de interpretación paisajística entre campos de cereal y dehesas agrarias aisladas, caminatas botánicas hacia los encinares del entorno de la ermita, paseos fotográficos de arquitectura rural tradicional y cicloturismo de llanura alta por pistas vecinales sin tráfico.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42119','rural','Oferta de turismo rural','Alojamientos rurales: Casas de labranza tradicionales bajas de tapial y piedra caliza con corrales recuperados, apartamentos rústicos familiares e íntimos a la sombra de su palacio fortificado de los Mendoza y posadas rurales. Entorno y actividades: Extremo oriental meridional, bañado por el río Nágima y lindando con el Embalse de Monteagudo. Custodia la dehesa palustre del embalse, declarada Zona ZEPA y de máxima protección ecológica por ser un punto clave del interior peninsular para el turismo ornitológico de aves acuáticas migratorias (ánades, cigüeñuelas, garzas). Rutas de senderismo plano perimetral, caminatas de dehesa agraria y observación astronómica con cielos limpios nocturnos.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42155','rural','Oferta de turismo rural','Alojamientos rurales: Casas de piedra tradicionales de mampostería oscura con cubiertas de teja árabe vieja, hostales orientados al excursionismo rústico de aislamiento y apartamentos unifamiliares integrados en su casco amurallado de trazado islámico. Entorno y actividades: En la comarca de la Serranía soriana meridional, transición hacia la provincia de Guadalajara. Ofrece rutas de senderismo exigentes de media montaña que ascienden hacia los altos del cerro del Tarancón, caminatas por los cañones calizos excavados por el río Talegones joven, senderos micológicos de encinar húmedo y sabinares centenarios aislados del ruido urbano.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42030','rural','Oferta de turismo rural','Alojamientos rurales: Casas de campo agrícolas tradicionales independientes de interior con amplios patios de carruajes, y pequeños apartamentos rurales rústicos de fin de semana adaptados para familias junto al cauce fluvial. Entorno y actividades: Cuenca del río Duero medio, comarca de las dehesas agrícolas de Almazán. Ofrece rutas de senderismo suave que conectan con los senderos que bordean los pinares de repoblación viejos y dehesas de sabinas albares linderas, paseos de interpretación botánica y fluvial a orillas del Duero, pesca fluvial tradicional de río y cicloturismo de paseo. PROVINCIA: MURCIA - COMARCA DEL NOROESTE E INTERIOR MONTAÑOSO (Texto Plano Limpio).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30012','rural','Oferta de turismo rural','Alojamientos rurales: Casas de turismo rural y de campo integradas en bodegas e infinitas dehesas vitivinícolas tradicionales, pequeños hostales de interior con encanto y apartamentos rústicos con chimeneas de leña. Entorno y actividades: Puerta natural del Noroeste, cabecera del río Mula. Destaca por el paraje natural del Salto del Usero (espectacular e imponente poza natural de agua turquesa excavada por la erosión fluvial en la roca caliza en forma de bóveda abierta ideal para el baño veraniego). Ofrece rutas de senderismo por la Sierra de la Silla, paseos agrícolas y enoturismo activo en bodegas amparadas por su Denominación de Origen.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30032','rural','Oferta de turismo rural','Alojamientos rurales: Casas de labranza tradicionales bajas de tapial y piedra caliza con huertos integrados de frutales de hueso, apartamentos rústicos familiares de fin de semana y alojamientos de montaña pegados al Parque. Entorno y actividades: Vertiente norte de la Sierra de Espuña caliza. Rutas de senderismo que se adentran en los densos pinares de repoblación viejos de Sierra Espuña, caminatas hacia el paraje de la Fuente de la Higuera, senderos históricos de interpretación del patrimonio morisco (como el castillo de las Paleras y su poblado fortificado enterrado en la naturaleza), y cicloturismo de carretera de gran pendiente. PROVINCIA: GUADALAJARA - SEÑORÍO DE MOLINA Y ALTO TAJO (Texto Plano Limpio).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19223','rural','Oferta de turismo rural','Alojamientos rurales: Casas de turismo rural unifamiliares con porches de roca caliza, apartamentos rústicos de montaña pequeños adaptados para el turismo activo y hostales de montaña. Entorno y actividades: Parque Natural del Alto Tajo. Custodia el espectacular paraje natural del Salto de Poveda (una imponente cascada natural originada por una antigua presa abandonada sobre el río Tajo rodeada de inmensos pinares silvestres y cortados calizos). Rutas de senderismo hacia el cañón del río Tajo superior, caminatas geológicas interpretativas por el sendero de la Laguna de Taravilla, pesca fluvial tradicional, piragüismo y rutas micológicas.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19103','rural','Oferta de turismo rural','Alojamientos rurales: Casas de piedra tradicionales de alta montaña con muros anchos aislantes, apartamentos rústicos en valles cerrados de frutales de montaña junto a arroyos trucheros limpios y antiguos pajares rehabilitados. Entorno y actividades: Alto Tajo oriental, falda del macizo de la Sierra de Albarracín. Destaca por el espectacular y singular paraje geológico de las "Piedras Picadas" y la Plaza de Toros Natural (colosales acumulaciones geológicas de formaciones de roca cuarcita esculpidas por el agua). Rutas de senderismo hacia las Aguaspeñas (monumentales formaciones de toba caliza rezumantes de agua cubiertas de musgo), caminatas por hayedos y pinares de pino silvestre, y micología de boletus.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19204','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales de alta montaña de piedra caliza con aislamiento reforzado para el invierno, apartamentos rústicos forestales pegados al bosque y albergues alpinos. Entorno y actividades: El municipio situado a mayor altitud de toda Castilla-La Mancha (núcleo urbano a casi 1.500 metros), en la Sierra de Albarracín alta y el Alto Tajo oriental. Rutas de senderismo de alta montaña entre pinares boreales de pino silvestre, caminatas hacia los cortados de las umbrías del río Cabrillas, paseos botánicos por el nacimiento de manantiales de agua limpia de montaña, y raquetas de nieve invernales. PROVINCIA: ZARAGOZA (Texto Plano Limpio).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50192','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales tradicionales aragonesas de piedra y adobe de alquiler íntegro con espectaculares porches, hoteles rústicos integrados en el entorno natural del cauce fluvial y apartamentos vacacionales con vistas a las muelas calizas. Entorno y actividades: Custodia el mundialmente célebre Parque Natural del Monasterio de Piedra y está bañado por el Embalse de La Tranquera. Sede de una de las rutas de senderismo botánico y acuático más espectaculares de Europa (recorrido jalonado por colosales cascadas naturales de agua de toba, como la Cola de Caballo de más de 50 metros, grutas kársticas como la Gruta Iris y lagos interiores de aguas turquesas). Ofrece deportes náuticos sin motor en el embalse (kayak, piragüismo), senderos por las hoces de roca caliza y rutas micológicas.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50251','rural','Oferta de turismo rural','Alojamientos rurales: Palacetes de turismo de interior integrados en casonas nobiliarias del casco histórico, hostales de montaña para senderistas en sus parroquias rurales y casas de aldea tradicionales de mampostería gruesa y chimeneas de leña a las faldas del macizo. Entorno y actividades: Principal nudo de acceso nororiental al Parque Natural del Moncayo. Un oasis de biodiversidad forestal atlántica en mitad de la meseta ibérica. Ofrece espectaculares rutas de senderismo de alta montaña que ascienden al Pico de San Miguel (el techo del Sistema Ibérico con 2.314 metros de altitud), caminatas de interpretación botánica bajo densos hayedos (Hayedo de Peña Lobera), dehesas ganaderas altas, rutas de raquetas de nieve invernales y micología de boletus.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90144','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles palacio históricos del siglo XIX fuertemente vinculados al patrimonio termal tradicional de sus balnearios medicinales, apartamentos turísticos de interior con encanto y posadas rurales. Entorno y actividades: Valle del río Jalón alto, comarca de Calatayud. Alberga el espectacular Lago Termal de Alhama (el lago termal natural más grande de Europa, donde brota agua mineral a unos constantes 32 °C todo el año apta para el baño terapéutico al aire libre). Ofrece rutas de senderismo plano de ribera fluvial, caminatas que recorren las dehesas agrícolas de viñedos viejos de altura, cicloturismo de carretera familiar sin tráfico y paseos arqueológicos hacia las murallas romanas de la zona.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50248','rural','Oferta de turismo rural','Alojamientos rurales: Parador de turismo nacional emplazado en un colosal palacio aragonés con fachada monumental de sillería dorada, casas de turismo rural intramuros empedradas con entramados de madera rústica y apartamentos boutique en el casco histórico medieval (Conjunto Histórico). Entorno y actividades: Comarca de las Cinco Villas septentrional, enclavado sobre una colina escarpada que mira a la Sierra de la Peña. Ofrece rutas de senderismo histórico y natural que rodean sus kilométricas murallas calizas y restos de fortificaciones de frontera, caminatas por los cañones y dehesas agrícolas del río Onsella, rutas cicloturistas de colinas suaves y observación ornitológica de rapaces calizas.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50175','rural','Oferta de turismo rural','Alojamientos rurales: Casas de campo de interior unifamiliares con porches de roca caliza, hostales rurales de montaña orientados al turismo activo y de aventura, y apartamentos optimizados para escaladores a orillas del río. Entorno y actividades: Cañón fluvial del río Jalón medio. Capital de la escalada deportiva en roca caliza de primer nivel en Aragón por sus colosales farallones de caliza verticales (como las paredes de Chodes). Sede de las espectaculares rutas de senderismo de las Hoces del Jalón (itinerarios que transitan por estrechos desfiladeros de roca caliza cortados por el río), caminatas geológicas interpretativas y senderos entre huertos tradicionales.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50073','rural','Oferta de turismo rural','Alojamientos rurales: Casas de campo señoriales de interior con anchos muros de mampostería integradas en bodegas tradicionales y viñedos viejos de colina, posadas de interior rústicas y apartamentos rurales familiares. Entorno y actividades: Altiplano meridional de la provincia, rodeado por el espacio protegido de la Sierra de Algairén. Ofrece rutas que conectan senderos agrícolas entre interminables dehesas y mares de viñedos viejos (enoturismo amparado por su Denominación de Origen), caminatas de media montaña que ascienden hacia el pico de Valdemadera entre pinares silvestres y quejigales centenarios, y cicloturismo de carretera de colinas suaves sin tráfico.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50069','rural','Oferta de turismo rural','Alojamientos rurales: Casas de piedra tradicionales de montaña con muros anchos aislantes, apartamentos rústicos de pinar e instalaciones unifamiliares en pequeños núcleos de dehesa. Entorno y actividades: En la cara oculta e indómita meridional del Parque Natural del Moncayo, Valle del río Isuela. Sede de rutas de senderismo vertical exigente que transitan entre estrechos cañones calizos, caminatas fluviales por el sendero del río Isuela, vías ferratas de montaña y escuelas de escalada en roca de la "Cara Oculta", senderos micológicos de otoño y rutas ecuestres de montaña. PROVINCIA: BURGOS - DESFILADEROS Y ALTA MONTAÑA (Texto Plano Limpio).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43071','rural','Oferta de turismo rural','Alojamientos rurales: Masías tradicionales de piedra (masos) rehabilitadas en mitad de olivares y almendros, hoteles boutique rurales con encanto en el casco antiguo medieval e históricas casonas con vistas a los riscos. Entorno y actividades: Puerta de entrada septentrional al Parque Natural de Els Ports. Destaca por la emblemática ruta de senderismo de las Roques de Benet (colosales farallones de roca caliza verticales que dominan el paisaje), caminatas fluviales por los estrechos del río Estrets, paseos botánicos que visitan "Lo Parot" (un olivo monumental con más de mil años de antigüedad protegido), cicloturismo de gran recorrido por la Vía Verde de la Val de Zafán y senderos micológicos.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17052','rural','Oferta de turismo rural','Alojamientos rurales: Casas de piedra tradicionales de montaña colgadas literalmente sobre el abismo del risco calizo, pequeños hostales con encanto de alta montaña y apartamentos rústicos optimizados para escaladores mundiales. Entorno y actividades: Enclavado de forma inverosímil en lo alto de un colosal acantilado de roca calcárea que vigila el Embalse de Siurana, entre la Sierra de Montsant y las Montañas de Prades. Es una de las grandes mecas internacionales absolutas de la escalada deportiva en roca por sus paredes de caliza perfectas. Ofrece rutas de senderismo geológico e interpretativo que bordean el precipicio, caminatas hacia los saltos de agua del Toll de l''Ou, kayak de interior y piragüismo en el embalse, y ornitología.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43084','rural','Oferta de turismo rural','Alojamientos rurales: Casas de turismo de interior integradas en el antiguo barrio alfarero de pescadores a orillas del agua, alojamientos rústicos con vistas directas al meandro fluvial y fincas de agroturismo agrícola de frutales. Entorno y actividades: Asentado sobre un espectacular giro cerrado del río Ebro bajo la silueta de su colosal castillo templario del siglo XII (el cual corona la roca). El mayor hub de turismo fluvial pasivo de la provincia; destaca por las rutas en kayak y piragüismo fluvial siguiendo el curso tranquilo de la Ribera de l''Ebre, paseos etnográficos para cruzar el río en el histórico "Pas de Barca" (transbordador tradicional de madera sin motor propulsado por la corriente), y caminatas de media montaña por la Sierra de Cardó.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43116','rural','Oferta de turismo rural','Alojamientos rurales: Casonas de piedra arenisca roja (pedra roja) tradicionales de montaña con cubiertas de losa, hostales rurales familiares con grandes chimeneas de piedra de leña y apartamentos forestales mimetizados bajo las pinadas. Entorno y actividades: Conocida como la "Vila Vermella", en el corazón del espacio protegido de las Montañas de Prades a casi 1.000 metros de altitud. Destaca por la ruta de senderismo hacia la Roca Foradada (un espectacular arco natural de roca arenisca en mitad del bosque), caminatas botánicas bajo frondosos castañares y robledales, senderos micológicos otoñales extremos (recogida de robellones), y es un destino con certificación astronómica internacional Starlight por la nitidez extrema de sus cielos nocturnos.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43018','rural','Oferta de turismo rural','Alojamientos rurales: Casas de pueblo tradicionales con fachadas de sillería caliza dorada en un núcleo histórico medieval compacto, apartamentos rústicos pequeños de montaña y masías independientes rodeadas de dehesas. Entorno y actividades: Límite occidental del Parque Natural de Els Ports, frontera con Teruel. Ofrece rutas de senderismo que se adentran en el paraje de las Fonts del Algars, caminatas fluviales por el cauce de aguas cristalinas del río Algars con piscinas naturales de roca ideales para el baño en verano (como el Toll del Vidre), rutas cicloturistas de montaña (BTT), senderos micológicos y paseos ecuestres.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43069','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles boutique rurales con encanto integrados en antiguas bodegas tradicionales y casas solariegas vinculadas a la viticultura heroica de colina, posadas de interior rústicas y apartamentos rurales familiares. Entorno y actividades: Corazón de la Comarca del Priorat, rodeado de lomas de pizarras desmenuzadas (llicorella). Ofrece rutas que conectan senderos agrícolas entre interminables campos de cepas viejas cultivadas en pendientes extremas y bancales tradicionales. Rutas de senderismo de media montaña que ascienden hacia la Sierra de Montsant meridional, cicloturismo de carretera sin tráfico y enoturismo de primer nivel con su prestigiosa Denominación de Origen Calificada.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43096','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales de alta montaña caliza de la serranía con muros anchos aislantes, apartamentos rústicos forestales pegados al pie del risco de Montsant, y albergues de naturaleza. Entorno y actividades: Ubicado a las faldas de la espectacular e imponente pared rocosa del Parque Natural de la Sierra de Montsant. Nudo de acceso principal a los senderos históricos conocidos como "Graus" (pasos escarpados y estrechos excavados en la roca viva que suben a la alta meseta caliza del parque, como el Grau de la Grallera). Rutas de senderismo de alta dificultad, vías ferratas de montaña de aventura para escaladores, visitas arqueológico-naturales a la Cartuja de Escaladei (rodeada de cipreses centenarios) y observación de estrellas. PROVINCIA: ALBACETE (Texto Plano Limpio).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02023','rural','Oferta de turismo rural','Alojamientos rurales: Cabañas forestales de madera y piedra perfectamente integradas en la vegetación serrana, casas rurales tradicionales de alta montaña con chimeneas de leña en el núcleo histórico de Riópar Viejo, y hostales de montaña para senderistas. Entorno y actividades: En el corazón del Parque Natural de los Calares del Mundo y de la Sima (Sierra de Alcaraz). Sede del acceso principal al Monumento Natural del Nacimiento del Río Mundo (célebre por "Los Chorros", una espectacular surgencia kárstica donde el agua brota a presión desde una colosal cueva caliza en una pared vertical y cae en cascadas de más de 80 metros). Ofrece senderismo de alta montaña por el Calar del Mundo, rutas micológicas otoñales, avistamiento de fauna y raquetas de nieve en invierno.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02003','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales cueva auténticas (viviendas excavadas directamente en el interior de la montaña caliza con chimeneas exteriores blancas), hoteles boutique rústicos con vistas panorámicas al desfiladero fluvial y apartamentos adaptados para el turismo activo. Entorno y actividades: Ubicado de forma espectacular en el cañón de la Hoz del Río Júcar. El mayor hub de turismo activo y de aventura de la provincia; destaca por la práctica de rafting, piragüismo, barranquismo, kayak de río y rutas en quads. Ofrece la ruta de senderismo del Sendero del Júcar (caminata plana que bordea el curso del agua bajo imponentes paredes de roca vertical), paseos fotográficos por sus callejones empinados y playas fluviales de agua dulce en verano.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02030','rural','Oferta de turismo rural','Alojamientos rurales: Complejos de turismo rural de alquiler íntegro con barbacoas y piscinas a orillas del agua, casas rurales de piedra de mampostería tradicional serrana en sus pedanías aisladas y hostales de montaña a las faldas de su castillo medieval. Entorno y actividades: Valle del río Segura alto y el río Tus, a los pies del Parque Natural de la Sierra de Segura y los Calares. Sede de rutas de senderismo fluvial y de aventura hacia el Estrecho de los Infiernos o la Cerrada de tus (angostos desfiladeros de roca caliza con pasarelas de madera y pozas turquesas heladas aptas para el baño veraniego). Ofrece piragüismo en el Embalse de la Fuensanta, senderos hacia el Calar de la Sima, observación de grandes rapaces y micología de sierra.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02004','rural','Oferta de turismo rural','Alojamientos rurales: Palacetes de turismo de interior integrados en casonas renacentistas de sillería con balcones de forja tradicional en su conjunto monumental, casas de labranza tradicionales con huertos y apartamentos rurales familiares. Entorno y actividades: Centro logístico e histórico de la Sierra de Alcaraz. Punto de inicio neurálgico de la Vía Verde de la Sierra de Alcaraz (antiguo trazado de tren acondicionado ideal para caminantes y cicloturistas). Ofrece rutas de senderismo hacia el paraje natural de los Estrechos del río Alcaraz, caminatas de interpretación botánica entre pinares y encinares centenarios de media montaña, y rutas gastronómico-rurales.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02018','rural','Oferta de turismo rural','Alojamientos rurales: Casas de pastores de la alta sierra tradicionales rehabilitadas con muros anchos aislantes, apartamentos rústicos de montaña aislados de la civilización urbana y dehesas de agroturismo ganadero. Entorno y actividades: Extremo sur de la provincia, enclavado en las estribaciones de la Sierra de las Cabras y la Sierra de Taibilla, lindando con Murcia y Andalucía. Custodia el conjunto de Pinturas Rupestres del Barranco de la Tóbola (Patrimonio de la Humanidad por la UNESCO). Ofrece la espectacular ruta de senderismo del Sendero de los Nogales Centenarios, caminatas de alta montaña hacia el pico Taibilla (2.081 metros, el techo de Albacete), senderos pastoriles trashumantes y observación de estrellas Starlight. PROVINCIA: MALLORCA (Islas Baleares - Datos Curados).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02041','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales unifamiliares integradas intramuros en el interior de una villa medieval fortificada colgada del meandro, y pequeños apartamentos rústicos con vistas directas a los cañones de caliza. Entorno y actividades: Asentado sobre un monumental y vertiginoso meandro cerrado del río Júcar inferior (el "anfiteatro del Júcar"). Ofrece rutas de senderismo fluvial por la Senda de las Huertas, caminatas geológicas interpretativas por los cortes calizos de las hoces que aíslan el pueblo, paseos tranquilos de agroturismo en sus terrazas de cultivo tradicionales, cicloturismo de carretera familiar y ornitología. PROVINCIA: LANZAROTE (Canarias - Datos Curados).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35034','rural','Oferta de turismo rural','Alojamientos rurales: Fincas históricas canarias de piedra volcánica negra y muros anchos blanqueados, eco-lodges de diseño integrados en la lava y casas de campo tradicionales con palmeras. Entorno y actividades: Custodia el Parque Nacional de Timanfaya y el Paisaje Protegido de La Geria. Destaca por las rutas de senderismo entre cráteres y coladas de lava recientes (Ruta de Tremesana), caminatas por el litoral salvaje del Parque Natural de Los Volcanes, y paseos fotográficos únicos por los viñedos tradicionales excavados en ceniza volcánica (lapilli) y protegidos por muros semicirculares de piedra seca.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90629','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales de arquitectura tradicional canaria con patios interiores de madera, apartamentos rústicos de interior rodeados de vegetación subtropical y villas de agroturismo. Entorno y actividades: Ubicado en el "Valle de las Mil Palmeras" (Norte de la isla). Destaca por las rutas de senderismo de ascensión al Volcán de la Corona, caminatas por los vertiginosos acantilados del Bosquecillo que miran al Archipiélago Chinijo, dehesas y senderos botánicos de flora endémica macaronésica y proximidad a los Jameos del Agua y la Cueva de los Verdes (túneles volcánicos). 📂 PROVINCIA: ÁLAVA (País Vasco - Datos Curados).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35029','rural','Oferta de turismo rural','Alojamientos rurales: Casas de campo agrícolas tradicionales vinculadas al agroturismo de interior, pequeños apartamentos de naturaleza y eco-pernoctas rodeadas de malpaís volcánico. Entorno y actividades: Frontera natural del Parque Natural de Los Volcanes. Ofrece la espectacular ruta de senderismo de la Caldera Blanca (el cráter volcánico más ancho de la isla, transitable por el borde superior con vistas espectaculares). Caminatas geológicas de interpretación volcánica, rutas cicloturistas BTT por pistas de tierra negra y cercanía a las playas salvajes del norte. 📂 PROVINCIA: ÁLAVA (País Vasco - Datos Curados).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50037','rural','Oferta de turismo rural','Alojamientos rurales: Caseríos vasco-alaveses de sillería de piedra con entramados de madera, apartamentos rústicos de media montaña con chimenea de leña y hostales orientados al turismo ecológico. Entorno y actividades: Custodia el Parque Natural de Valderejo. Destaca por la emblemática ruta de senderismo del Desfiladero del Río Purón (un angosto y profundo cañón calizo con pasarelas de madera y pozas de agua cristalina). Ofrece avistamiento ornitológico de grandes rapaces (colonia de buitre leonado), dehesas forestales, rutas botánicas entre frondosos pinares silvestres y hayedos, y visitas a cuevas eremíticas paleocristianas talladas en la roca viva.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01031','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles boutique rurales integrados en palacetes renacentistas dentro de una villa amurallada intacta, casas de turismo de interior vinculadas a bodegas subterráneas medievales (calados históricos), y fincas de agroturismo vitivinícola. Entorno y actividades: Capital de la Rioja Alavesa, a las faldas de la Sierra de Cantabria. Ofrece rutas que conectan senderos agrícolas entre interminables mares de viñedos viejos de colina, paseos de observación ornitológica en el Complejo Lagunar de Laguardia (humedales protegidos en zona árida), caminatas de dehesa caliza y senderos que suben a los altos de la sierra calcárea por pasos históricos.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41011','rural','Oferta de turismo rural','Alojamientos rurales: Casonas solariegas castellanas en el casco histórico de las tres culturas, hostales rurales especializados en montañeros y senderistas, y apartamentos rústicos con chimeneas de piedra. Entorno y actividades: "La Villa de las Tres Culturas", a las faldas de la vertiente soriana del Parque Natural del Moncayo. Destaca por la ruta de senderismo del Cañón del Río Val (un desfiladero calizo estrecho con túneles de sauces y cascadas naturales), caminatas botánicas que ascienden al pico de San Miguel (2.314 metros de altitud) entre dehesas altas y hayedos de umbría, rutas invernales de esquí de fondo y micología de boletus.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41007','rural','Oferta de turismo rural','Alojamientos rurales: Casas de piedra tradicionales de montaña con muros anchos aislantes, apartamentos rústicos de pinar e instalaciones unifamiliares con porche de leña en barrios de la sierra alta. Entorno y actividades: Eje de la Sierra del Moncayo soriana occidental y la Sierra de Toranzo. Destaca por la ruta de senderismo de la Mina de la Juana (itinerario que recorre antiguas explotaciones mineras integradas en el bosque), caminatas forestales bajo los encinares de dehesa del entorno de la ermita, paseos por hayedos aislados repletos de líquenes en otoño, recolección micológica y cicloturismo.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42217','rural','Oferta de turismo rural','Alojamientos rurales: Casas de pueblo tradicionales de mampostería oscura caliza junto al cauce fluvial, pequeños alojamientos con encanto a la sombra de su castillo fronterizo. Entorno y actividades: Custodia el espectacular e imponente Nacimiento del Río Queiles (un Monumento Natural donde el agua brota a borbotones a presión desde una colosal gruta kárstica caliza, siendo el segundo manantial con mayor caudal de Europa). Rutas de senderismo de cañón bajo encinares cantábricos, senderos forestales llanos de interpretación fluvial de ribera y observación de aves rapaces de roca. PROVINCIA: MALLORCA (Islas Baleares - Datos Curados).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07023','rural','Oferta de turismo rural','Alojamientos rurales: Antiguas possessions (fincas señoriales mallorquinas de sillería de piedra), agroturismos integrados en huertos tradicionales de cítricos y pequeños hoteles boutique de interior rodeados de olivares milenarios. Entorno y actividades: En el corazón de la Serra de Tramuntana (Patrimonio de la Humanidad por la UNESCO). Eje central para el senderismo de la Ruta de Pedra en Sec (GR-221). Destaca por las espectaculares rutas que ascienden al Barranc de Biniaraix, senderos empedrados tradicionales bajo paredes calizas verticales, caminatas hacia los embalses de Cúber y Gorg Blau bajo el Puig Major, y turismo botánico en valles resguardados.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07063','rural','Oferta de turismo rural','Alojamientos rurales: Fincas rústicas de montaña con olivares integrados, apartamentos de turismo rural con chimenea de piedra caliza y posadas con encanto en callejones empedrados a la sombra de la Cartuja. Entorno y actividades: Serra de Tramuntana central. Sede de la espectacular ruta de senderismo del Camí de s''Arxiduc (itinerario de piedra seca que transita sobre una cresta de roca caliza cortada sobre el mar con vistas verticales brutales). Ofrece paseos por densos bosques de encinas viejas, caminatas hacia el puerto natural y calas de pinar, y observación ornitológica de aves rapaces calcícolas (buitre negro mediterráneo).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07017','rural','Oferta de turismo rural','Alojamientos rurales: Agroturismos de gran porte con picaderos de caballos, casas de turismo de interior con patios empedrados de cal y apartamentos rurales independientes en valles cerrados aislados. Entorno y actividades: Extremo norte de la Serra de Tramuntana. Ofrece rutas de senderismo exigentes de montaña hacia el Puig de Maria o el Cavall Bernat, excursiones que descienden por el espectacular torrente de la Vall d''en Marc, caminatas fotográficas por el Cabo de Formentor entre acantilados salvajes de roca desnuda, y tramos de la GR-221. 📂 PROVINCIA: MENORCA (Islas Baleares - Datos Curados).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07037','rural','Oferta de turismo rural','Alojamientos rurales: Auténticos llocs menorquines (fincas agrícolas blanqueadas tradicionales destinadas a la elaboración artesana de queso de Mahón), casas de campo aisladas en la dehesa mediterránea y eco-hoteles boutique. Entorno y actividades: Centro geográfico y natural de Menorca (Reserva de la Biosfera). Custodia la falda del Monte Toro (el techo de la isla). Conecta directamente con los senderos ecuestres e históricos de largo recorrido del Camí de Cavalls (GR-223). Rutas de senderismo suave por barrancos calizos boscosos de interior como el Barranc de Algendar, paseos botánicos entre matorral aromático y acebuches, y ornitología.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90657','rural','Oferta de turismo rural','Alojamientos rurales: Fincas agro-rurales tradicionales independientes integradas en valles interiores, apartamentos rústicos y alojamientos de naturaleza con huertos ecológicos. Entorno y actividades: Interior indómito menorquín. Sede de rutas de senderismo botánico y fluvial que recorren el cauce profundo de barrancos, caminatas hacia el Castillo de Santa Águeda colgado sobre una muela caliza, senderos del Camí de Cavalls occidentales, y paseos fotográficos de naturaleza salvaje que desembocan en calas vírgenes protegidas rodeadas de pinares. 📂 PROVINCIA: LA CORUÑA (Galicia - Datos Curados).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01017','rural','Oferta de turismo rural','Alojamientos rurales: Pazos gallegos señoriales de granito con portalones heráldicos, casas de aldea tradicionales y apartamentos de turismo rural integrados en sotos boscosos junto al río. Entorno y actividades: Custodia la entrada principal al Parque Natural de las Fragas do Eume (uno de los bosques atlánticos de ribera mejor conservados de Europa, donde los robles conviven con helechos gigantes de reliquia terciaria). Sede de la espectacular ruta de senderismo del cañón del río Eume (Senda dos Encomendeiros hasta el Monasterio medieval de Caaveiro oculto en la espesura forestal), puentes colgantes sobre el río caudaloso, y piragüismo fluvial de interior.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15045','rural','Oferta de turismo rural','Alojamientos rurales: Casonas de labranza gallegas rústicas de mampostería antigua de grano granítico con hórreos gigantes, apartamentos rurales con chimeneas de leña orientados al turismo activo y albergues ganaderos. Entorno y actividades: Cuenca alta del río Xallas y faldas del Monte Pindo. Custodia el espectacular y único paraje de la Fervenza de Ézaro (la única cascada de Europa continental que desemboca directamente en el mar en caída libre sobre paredes de granito liso). Rutas de senderismo de alta dificultad que ascienden al Monte Pindo (el olimpo sagrado celta de los gallegos, un macizo granítico de formas caprichosas esculpidas por la erosión), y senderos ecuestres.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('15065','rural','Oferta de turismo rural','Alojamientos rurales: Antiguas rectorales y conventos de sillería de granito adaptados para pernocta rústica, casas de turismo rural vinculadas al agroturismo hortícola de vega y apartamentos rurales junto al río Sar. Entorno y actividades: Confluencia de los ríos Sar y Ulla, hito central de la variante portuguesa del Camino de Santiago. Ofrece las rutas de senderismo plano fluviales que siguen las riberas bajas del Ulla, paseos botánicos por el Jardín Artístico de Padrón, caminatas agrícolas de interpretación de sus huertas tradicionales de pimientos, cicloturismo familiar y ornitología en estuarios. PROVINCIA: VALENCIA (Comunidad Valenciana Datos Curados).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13014','rural','Oferta de turismo rural','Alojamientos rurales: Complejos de casas rurales de piedra y madera situados a orillas del agua, chalets rústicos independientes con embarcaderos privados y pequeños hoteles boutique de interior con encanto y vistas a las cascadas del valle. Entorno y actividades: En el corazón del Parque Natural de las Lagunas de Ruidera, uno de los oasis de agua dulce más impresionantes del país. Sede de rutas de senderismo plano perimetral que bordean las quince lagunas kársticas interconectadas (como la Laguna del Rey o la Colgada). Destaca por el buceo en agua dulce de máxima visibilidad, rutas guiadas en kayak, piragüismo, senderos de interpretación de formaciones de barreras de toba caliza que crean saltos de agua naturales y cascadas, y paseos ornitológicos.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90824','rural','Oferta de turismo rural','Alojamientos rurales: Cabañas de madera forestales mimetizadas bajo densos encinares, grandes fincas de agroturismo de montería con picaderos de caballos, hostales rurales especializados en senderismo y casas de campo de aislamiento serrano absoluto. Entorno y actividades: Principal nudo de acceso meridional al Parque Nacional de Cabañeros. Alberga el mayor y mejor conservado bosque mediterráneo de Europa, famoso por su paisaje de grandes llanuras fluviales adehesadas conocidas como "la raña" (el Serengeti español). Ofrece espectaculares rutas de senderismo y excursiones guiadas en todoterreno 4x4 entre encinas y alcornoques centenarios, avistamiento masivo de fauna ibérica en libertad (grandes manadas de ciervos, jabalíes, buitre negro y águila imperial), caminatas fluviales por el sendero del río Estena y micología extrema de otoño.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13019','rural','Oferta de turismo rural','Alojamientos rurales: Palacetes de turismo de interior integrados en casonas nobiliarias y antiguos conventos del siglo XVI y XVII de sillería dorada con escudos heráldicos en sus patios de columnas de madera, posadas castellanas reales y apartamentos rústicos familiares de gran porte en el casco histórico (Conjunto Histórico). Entorno y actividades: Capital histórica de la Comarca del Campo de Montiel, entorno literario del Quijote y transición hacia Sierra Morena. Ofrece rutas de senderismo plano de interpretación histórica que siguen cañadas reales ganaderas de largo recorrido, caminatas agrícolas entre dehesas agrarias de encinas centenarias y campos llanos de cereal, rutas cicloturistas llanas de paseo familiar por pistas rurales sin tráfico y paseos arqueológicos hacia el yacimiento prerromano de Jamila.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13042','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles de interior vinculados al termalismo histórico de su célebre balneario medicinal, apartamentos tradicionales de montaña construidos en piedra caliza con chimeneas rústicas de campana y cabañas de madera forestales. Entorno y actividades: En el interior del Parque Natural del Valle de Alcudia y Sierra Madrona (el techo de Ciudad Real alta). Custodia los Abrigos Rupestres de Peña Escrita (la mayor concentración de pinturas rupestres esquemáticas de la península, Patrimonio de la Humanidad por la UNESCO). Ofrece exigentes rutas de senderismo de alta montaña que ascienden hacia el pico de la Bañuela (1.332 metros de altitud) o el Abulagar bajo densos bosques boreales de robles melojos y madroños centenarios, senderos micológicos otoñales extremos (recogida de níscalos) y avistamiento de ciervos (berrea).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90332','rural','Oferta de turismo rural','Alojamientos rurales: Grandes cortijos ganaderos y agrícolas con encanto castellano-manchego, fincas de dehesa extremeño-manchega destinadas al agroturismo, y casas de campo independientes rodeadas de encinares maduros. Entorno y actividades: El municipio de mayor extensión de la región, abarcando gran parte del espectacular e indómito Parque Natural del Valle de Alcudia y Sierra Madrona. Ofrece rutas de senderismo de interpretación ambiental e histórica por la gran dehesa del Valle de Alcudia, caminatas llanas ideales para cicloturismo de paseo familiar de relax por las históricas cañadas reales trashumantes, senderos micológicos de encinar, dehesas de ganado bovino extensivo, y es una zona de máxima nitidez nacional para la observación del cielo nocturno al contar con certificación internacional Starlight de cielos negros limpios.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13005','rural','Oferta de turismo rural','Alojamientos rurales: Casas de campo tradicionales de labranza manchega bajas de tapial y fachadas blancas de cal con antiguas almazaras de aceite recuperadas, posadas de interior rústicas y apartamentos rurales familiares en el llano de la cuenca. Entorno y actividades: Custodia el Parque Nacional de las Tablas de Daimiel. Espectacular y singular ecosistema palustre de tablas fluviales de interior único en Europa, formado por la confluencia de los ríos Guadiana y Cigüela. Ofrece rutas de senderismo plano de alta protección ecológica a través de pasarelas de madera acondicionadas e islas botánicas interiores (Senda del Agua), paseos de observación ornitológica masiva de aves acuáticas migratorias y palustres (flamencos, garzas, somormujos), piragüismo de baja dificultad en las lunas de agua del entorno, y paseos fotográficos. PROVINCIA: LEÓN (Castilla y León - Datos Curados).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49166','rural','Oferta de turismo rural','Alojamientos rurales: Posadas reales de piedra y pizarra en su casco histórico fortificado (Conjunto Histórico), casas rurales tradicionales sanabresas con grandes chimeneas de piedra de leña y apartamentos de montaña con corredores de madera. Entorno y actividades: Nexo de acceso principal al Parque Natural del Lago de Sanabria y Sierras de Segundera y de Porto. Custodia el lago de origen glaciar más grande de la península ibérica. Ofrece espectaculares rutas de senderismo de alta montaña que recorren profundos cañones glaciares (Cañón del Tera, Cañón del Cárdenas), playas fluviales de arena e interior en el lago aptas para el baño y el kayak, senderos micológicos de otoño y dehesas de montaña.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49262','rural','Oferta de turismo rural','Alojamientos rurales: Casonas serranas tradicionales construidas con sillería de piedra arenisca rojiza con solanas de madera, hostales de interior y casas de campo independientes rodeadas de pinares y robledales. Entorno y actividades: En el corazón de la Sierra de la Culebra (Reserva Nacional de Caza). La zona de Europa con mayor densidad y mejor enclave para el avistamiento fotográfico y rastreo guiado del Lobo Ibérico en libertad. Ofrece rutas de senderismo micológico de primer nivel (boletus, níscalos), paseos hacia la playa fluvial de Valparaíso, avistamiento de ciervos (berrea) y dehesas forestales puras bajo cielos negros Starlight. 📂 PROVINCIA: PALENCIA (Castilla y León - Datos Curados).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34056','rural','Oferta de turismo rural','Alojamientos rurales: Casonas solariegas de piedra de cantería con escudos heráldicos, parador nacional de turismo integrado en el bosque de alta montaña, hostales rurales para montañeros y apartamentos de montaña con chimenea. Entorno y actividades: Centro logístico e histórico del Parque Natural de la Montaña Palentina. Destaca por la ruta de senderismo del Roblón de Estalaya (caminata que visita un roble monumental protegido de más de 800 años de antigüedad), senderos de ascensión hacia picos calizos alpinos (Curavacas, Espigüete), paseos fluviales por el curso alto del río Pisuerga, dehesas y senderos micológicos de otoño.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35001','rural','Oferta de turismo rural','Alojamientos rurales: Palacetes de turismo de interior integrados en antiguas casas señoriales, casonas de labranza tradicionales y apartamentos rurales familiares a las orillas del gran embalse. Entorno y actividades: Puerta natural del Románico Palentino y las hoces calizas, bañado por el Embalse de Aguilar. Custodia la ruta de senderismo del espacio protegido del Espacio Natural de Las Tuerces (espectacular laberinto kárstico de figuras de roca caliza esculpidas por la erosión en mitad del páramo). Ofrece caminatas por el cañón de la Horadada, piragüismo y deportes de remo en el embalse, y paseos botánicos por bosques de galería.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34199','rural','Oferta de turismo rural','Alojamientos rurales: Casas de montaña de piedra tradicionales con muros anchos aislantes, apartamentos rústicos pequeños de fin de semana para familias y albergues de naturaleza. Entorno y actividades: Vertiente occidental de la Montaña Palentina, cuenca alta del río Carrión. Custodia el Monumento Natural de las Fuentes Tamáricas (fuentes históricas de la era romana de flujo intermitente). Ofrece rutas de senderismo alpino de alta exigencia hacia el pico Espigüete (colosal pirámide caliza vertical de 2.450 metros), caminatas por el bosque del pinar de Velilla (reliquia de pino silvestre autóctono), senderos micológicos de otoño y lagunas glaciares de montaña (Pozo de las Lomas). PROVINCIA: TENERIFE (Canarias - Datos Curados).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38052','rural','Oferta de turismo rural','Alojamientos rurales: Casonas tradicionales canarias de arquitectura colonial con balconadas de madera de pino tea, pequeños hoteles de montaña rodeados de viñedos de altura y casas rurales con paredes de piedra volcánica vista. Entorno y actividades: El municipio más alto de Canarias (a 1.400 metros de altitud), puerta sur de acceso al Parque Nacional del Teide. Destaca por la ruta de senderismo del Paisaje Lunar (espectaculares formaciones cónicas de ceniza volcánica esculpidas por la erosión). Ofrece ascensiones al Teide, rutas botánicas bajo el majestuoso Pinar de Chasna (con ejemplares monumentales como el Pino Gordo), senderos micológicos en invierno y observación de estrellas Starlight.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38003','rural','Oferta de turismo rural','Alojamientos rurales: Haciendas agrícolas señoriales vinculadas al agroturismo, apartamentos rurales de interior en caseríos antiguos de montaña y eco-lodges aislados enriscados sobre el cañón. Entorno y actividades: En el Parque Rural de Teno, uno de los macizos geológicos más antiguos e indómitos de Tenerife. Alberga el espectacular Caserío de Masca; destaca por la célebre ruta de senderismo del Barranco de Masca (un desfiladero colosal con paredes verticales de roca de más de 400 metros de altura que desciende hasta el océano). Ofrece senderos costero-forestales hacia el Faro de Teno, caminatas entre bosques de laurisilva en las cumbres húmedas y avistamiento de aves marinas.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38023','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales tradicionales en caseríos aislados de montaña, albergues de naturaleza integrados en la espesura forestal y alojamientos rústicos con vistas a los roques de Anaga. Entorno y actividades: Vertiente norte del Parque Rural de Anaga (Reserva de la Biosfera). Custodia el mayor y mejor conservado bosque de Laurisilva prehistórica de la isla (un oasis de humedad atrapado por los vientos alisios que emula la era terciaria). Sede de la espectacular ruta del Sendero de los Sentidos y la Senda del Bosque Encantado (itinerario protegido bajo un túnel vegetal cerrado de brezos, laureles y helechos gigantes). Senderismo exigente que descienda a calas salvajes de arena negra volcánica y ornitología. 📂 PROVINCIA: LA PALMA (Canarias - Datos Curados).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38027','rural','Oferta de turismo rural','Alojamientos rurales: Casitas canarias de cal blanca y cubiertas de teja rústica con techos interiores de madera de tea, fincas de agroturismo rodeadas de almendros y frutales de montaña, y chalets rústicos independientes junto a pinares. Entorno y actividades: Centro geográfico de "La Isla Bonita" y puerta de acceso principal al Parque Nacional de la Caldera de Taburiente. Sede de la mítica ruta de senderismo del Barranco de las Angustias y el interior de la Caldera (colosal depresión volcánica de 8 km de diámetro con cortados rocosos verticales brutales). Destaca por la Senda de los Nacimientos de Agua, caminatas botánicas, rutas micológicas y observación astronómica de primer nivel mundial al contar con los cielos más limpios y protegidos del planeta (Ley del Cielo y Observatorio del Roque de los Muchachos). PROVINCIA: TENERIFE (Canarias - Datos Curados).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38033','rural','Oferta de turismo rural','Alojamientos rurales: Antiguas haciendas coloniales azucareras de sillería y balcones de madera tallada, casas de turismo rural independientes junto a plantaciones de plátanos de interior y eco-alojamientos. Entorno y actividades: En el noreste de la isla. Custodia el espectacular bosque de Los Tilos, uno de los reductos de laurisilva prehistórica (bosque húmedo de reliquia del terciario) más importantes y frondosos del planeta. Sede de la ruta de senderismo de los Nacimientos de Marcos y Cordero (itinerario que cruza túneles excavados en la roca calada por cascadas de agua pura), caminatas bajo helechos gigantes, senderos fluviales y pozas naturales de mar como el Charco Azul. 📂 PROVINCIA: LA GOMERA (Canarias - Datos Curados).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38050','rural','Oferta de turismo rural','Alojamientos rurales: Casas de turismo rural colgadas en terrazas de cultivo escarpadas, caseríos gomeros tradicionales de cal y piedra con techumbres rústicas y alojamientos de ecoturismo en valles profundos aislados. Entorno y actividades: Norte de la isla, abarcando una gran franja del Parque Nacional de Garajonay (Patrimonio de la Humanidad por la UNESCO). Ofrece una experiencia de turismo rural inmersa en la bruma de la laurisilva prehistórica. Destaca por las rutas de senderismo hacia el Monumento Natural del Roque Cano (colosal pitón basáltico vertical), caminatas bajo la fronda de los bosques de niebla de Garajonay, senderos micológicos y paseos fotográficos por cañones volcánicos escarpados. PROVINCIA: PALENCIA - MONTAÑA PALENTINA E INTERIOR (Texto Plano Limpio).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45113','rural','Oferta de turismo rural','Alojamientos rurales: Cortijos toledanos de arquitectura tradicional serrana con anchos muros de piedra y cal, complejos de cabañas forestales de madera mimetizadas en el entorno e instalaciones de campo de aislamiento total. Entorno y actividades: En el interior de la vertiente norte del Parque Nacional de Cabañeros y los Montes de Toledo. Sede de la célebre ruta de senderismo de la Chorrera de los Navalucillos (un espectacular salto de agua natural de montaña de más de 15 metros de caída encajonado en un desfiladero umbrío de la garganta del río Pusa). Ofrece rutas de ascensión al pico Rocigalgo (el techo de la provincia de Toledo con 1.449 metros de altitud), caminatas bajo robledales centenarios y encinares maduros, observación de la berrea del ciervo y grandes aves rapaces (águila imperial).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45125','rural','Oferta de turismo rural','Alojamientos rurales: Parador de turismo nacional emplazado de forma monumental en el colosal castillo medieval de los condes de Oropesa, casonas solariegas de sillería con patios castellanos de columnas de madera y apartamentos rurales de campiña. Entorno y actividades: Comarca de la Campana de Oropesa y transición al Valle del Tiétar bajo. Ofrece rutas que conectan con senderos agrícolas y cañadas reales ganaderas de largo recorrido, caminatas llanas de cicloturismo de dehesa agraria familiar de relax entre encinares centenarios donde pasta el ganado, rutas ecuestres y paseos fotográficos de naturaleza de interior. PROVINCIA: GUIPÚZCOA (País Vasco - Datos Curados).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21014','rural','Oferta de turismo rural','Alojamientos rurales: Caseríos vascos monumentales de sillería de piedra con amplias solanas, hostales rurales especializados en montaña y apartamentos rústicos con vistas a los valles interiores. Entorno y actividades: Puerta de entrada principal al Parque Natural de Aizkorri-Aratz. Destaca por la emblemática ruta de senderismo de ascensión al Pico Aizkorri (un colosal macizo calizo sagrado para el montañismo vasco), caminatas hacia las campas altas de Urbia donde pasta el ganado, senderos micológicos otoñales extremos bajo frondosos hayedos, y la visita guiada de aventura a las colosales Cuevas de Arrikrutz (galerías kársticas con ríos subterráneos activos).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21019','rural','Oferta de turismo rural','Alojamientos rurales: Alojamientos de agroturismo integrados en colinas verdes costeras, caseríos tradicionales rehabilitados rodeados de praderas y apartamentos rurales con vistas al estuario. Entorno y actividades: En el corazón del Geoparque Mundial de la UNESCO de la Costa Vasca. Sede de una de las rutas de senderismo geológico más espectaculares del planeta: la Ruta del Flysch (un sendero litoral que transita sobre colosales acantilados verticales donde la erosión marina ha dejado al descubierto millones de años de historia de la Tierra en finas láminas de roca). Paseos fotográficos por la rasa mareal, kayak en la ría del Urola y senderos botánicos en encinares cantábricos.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90258','rural','Oferta de turismo rural','Alojamientos rurales: Caseríos tradicionales aislados en valles profundos de montaña con lareiras rústicas, apartamentos rurales familiares rodeados de helechos y posadas con encanto de interior. Entorno y actividades: Enclavado en el Parque Natural de Aralar (zona de máxima mitología vasca). Ofrece la espectacular ruta de senderismo del Sendero del Agua o la Senda Mitológica (itinerarios que transitan bajo la umbría de densos y brumosos bosques de hayas centenarios), caminatas de media montaña que ascienden hacia los rasos calcáreos de Aralar, senderos pastoriles donde se elabora el queso de Idiazabal tradicional y cuevas prehistóricas. 📂 PROVINCIA: VIZCAYA (País Vasco - Datos Curados).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90958','rural','Oferta de turismo rural','Alojamientos rurales: Casonas de labranza tradicionales vizcaínas con portalones heráldicos de piedra y vigas de roble vistas, cabañas forestales elevadas mimetizadas en los árboles y apartamentos rústicos con chimeneas de leña. Entorno y actividades: Al pie del Parque Natural de Gorbeia, el mayor pulmón verde de Vizcaya. Sede del acceso principal a la emblemática ruta de senderismo de ascensión a la Cruz del Gorbeia (techo de la provincia con 1.482 metros de altitud) y al mágico Hayedo de Otzarreta (célebre por sus hayas trasmochadas de ramas verticales rodeadas de musgo y el río serpenteante). Senderos micológicos de otoño extremos (boletus), caminatas por humedales protegidos de montaña y dehesas ganaderas altas.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47011','rural','Oferta de turismo rural','Alojamientos rurales: Caseríos marineros de piedra y caliza con vistas a la ría, apartamentos rurales de costa integrados en la dehesa atlántica y eco-lodges de diseño costero-forestal. Entorno y actividades: En el interior de la Reserva de la Biosfera de Urdaibai. Ofrece una combinación excepcional de turismo forestal y estuario protegido. Destaca por la ruta de senderismo que recorre las marismas de Urdaibai (paraíso del turismo ornitológico de aves acuáticas migratorias en el Urdaibai Bird Center), paseos a pie hacia la ermita de San Juan de Gaztelugatxe (enriscada de forma espectacular sobre un islote volcánico salvaje), senderos de encinares cantábricos costeros y kayak de mar.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90261','rural','Oferta de turismo rural','Alojamientos rurales: Grandes caseríos tradicionales unifamiliares con corrales recuperados y huertos ecológicos, apartamentos rústicos de montaña pequeños e instalaciones para turismo activo de interior. Entorno y actividades: Vertiente septentrional del Parque Natural de Gorbeia y el macizo de Itxina. Custodia el espectacular e indómito Biotopo Protegido de Itxina (un colosal laberinto kárstico de rocas calizas afiladas, simas profundas y cuevas rodeadas de un bosque de hayas brumoso). Rutas de senderismo exigentes de montaña que cruzan el ojo natural del Ojo de Atxular, caminatas fluviales por el río Altube, senderos pastoriles ganaderos y rutas micológicas. PROVINCIA: CASTELLÓN (Comunidad Valenciana - Datos Curados).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30009','rural','Oferta de turismo rural','Alojamientos rurales: Grandes hoteles balneario de interior de estética mudéjar vinculados al termalismo histórico, apartamentos rústicos de vega fluvial y casas de campo independientes rodeadas de limoneros y palmeras. Entorno y actividades: Puerta de entrada al paradisíaco Valle de Ricote, el último oasis morisco del río Segura. Destaca por las rutas de senderismo plano de ribera que bordean los meandros del Segura bajo inmensos palmerales, paseos de agroturismo entre aceñas y norias de agua tradicionales de madera, rutas de kayak de interior y piragüismo fluvial de relax en aguas limpias. PROVINCIA: HUELVA (Andalucía - Datos Curados).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41032','rural','Oferta de turismo rural','Alojamientos rurales: Cortijos andaluces señoriales de sillería rústica Morena, antiguos monasterios y cartujas del siglo XV reconvertidos en pernoctas exclusivas de interior, y dehesas de agroturismo ganadero y ecuestre. Entorno y actividades: En pleno Parque Natural de la Sierra Norte de Sevilla (Sierra Morena sevillana). Un paraíso interior dominado por inmensas dehesas de encinas y alcornoques. Ofrece la espectacular ruta de senderismo de las Riberas del Huéznar (bosque de galería fluvial cerrado con cascadas de toba caliza catalogadas como Monumento Natural), paseos por el sendero de las dehesas ganaderas donde pasta el toro bravo, cicloturismo por la Vía Verde de la Sierra Norte y es una reserva de máxima pureza estelar certificada como Reserva Starlight de cielos oscuros negros.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41088','rural','Oferta de turismo rural','Alojamientos rurales: Complejos de cabañas de madera forestales mimetizadas en el encinar, casas rurales de cal de pueblo serrano unifamiliares con chimenea de leña y apartamentos rústicos junto al cauce fluvial. Entorno y actividades: Sierra Norte de Sevilla alta. Custodia el espectacular paraje natural del Monumento Natural de las Cascadas del Huéznar (saltos de agua y pozas de agua helada de montaña ideales para el baño y el descanso veraniego) y el Cerro del Hierro (colosal paisaje kárstica caliza calada por una antigua explotación minera romana que simula un laberinto de agujas de roca). Rutas senderistas de aventura geológica, vías ferratas de montaña para escaladores y senderos micológicos de otoño.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41033','rural','Oferta de turismo rural','Alojamientos rurales: Casonas solariegas andaluzas de gran porte y cal blanca en el barrio de la Morería, hostales rurales especializados en turismo ecuestre de dehesa, y cortijos agrícolas aislados entre olivares de pendiente. Entorno y actividades: Valle del río Galindón, bajo la silueta de su castillo almorávide. Ofrece rutas de senderismo hacia el paraje de la encina de los perros, caminatas de interpretación botánica por sotos de castaños centenarios (el castañar de Constantina es un oasis húmedo singular en la provincia), senderos micológicos micológicos otoñales (setas de cardo, níscalos), y paseos a caballo por cañadas reales ganaderas. PROVINCIA: LLEIDA (Cataluña - Datos Curados).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46112','rural','Oferta de turismo rural','Alojamientos rurales: Casas de pueblo tradicionales de cal blanca adaptadas con patios rústicos, apartamentos turísticos optimizados para escaladores y senderistas mundiales, y hostales de montaña. Entorno y actividades: Ubicado de forma espectacular en el cañón calizo de la Hoz del Río Turia (Comarca de Los Serranos). Sede de la célebre y fotogénica ruta de senderismo de los Puentes Colgantes de Chulilla (itinerario que transita por el fondo del desfiladero cruzando colosales pasarelas suspendidas a gran altura sobre el río Turia). Es una de las grandes mecas nacionales de la escalada deportiva en roca caliza vertical, ofrece baños de agua dulce en el Charco Azul, senderos geológicos y rutas micológicas.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46106','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales integradas en su histórico barrio morisco y judío (Conjunto Histórico), antiguos molinos harineros de agua rehabilitados a orillas del agua y posadas rústicas de interior con chimeneas de leña. Entorno y actividades: Comarca de Los Serranos alta, flanqueada por la Sierra de Javalambre meridional. Sede de la espectacular ruta de senderismo de la Ruta del Agua de Chelva (un sendero plano e ideal para familias que combina túneles excavados en la roca viva, playas fluviales naturales de agua cristalina aptas para el baño veraniego como el Playón, y canales de riego árabes). Caminatas históricas hacia el Acueducto Romano de Peña Cortada, cicloturismo BTT y dehesas forestales bajo cielos oscuros Starlight. 📂 PROVINCIA: ÁVILA (Castilla y León - Datos Curados).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46072','rural','Oferta de turismo rural','Alojamientos rurales: Hoteles boutique rurales integrados en casonas solariegas señoriales de piedra caliza dentro de un casco urbano medieval excavado en la roca viva, posadas de interior rústicas y apartamentos rurales familiares. Entorno y actividades: Entrada norte al Parque Natural de la Sierra de Mariola, comarca de La Vall d''Albaida. Custodia las impresionantes Covetes dels Moros (colosal complejo de cuevas eremíticas y almacenes excavados de forma kárstica en mitad de un acantilado vertical, transitables a pie). Ofrece rutas de senderismo de media montaña que exploran bosques mediterráneos aromáticos (tomillo, romero, salvia), paseos fluviales por el nacimiento del río Clariano (Pou Clar) y cicloturismo de carretera. 📂 PROVINCIA: ALICANTE (Comunidad Valenciana - Datos Curados).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03054','rural','Oferta de turismo rural','Alojamientos rurales: Casas de labranza tradicionales de la montaña alicantina con muros anchos aislantes, apartamentos rústicos forestales pegados al pinar y masías de agroturismo aisladas entre olivares y almendros de colina. Entorno y actividades: Comarca de la Marina Alta interior, Valle de Jalón alto. Sede de una de las formaciones geológicas y paisajísticas más espectaculares de la provincia: Es Arcs (un Monumento Natural formado por colosales arcos de roca caliza naturales esculpidos por la erosión en mitad del monte). Rutas de senderismo exigentes de montaña hacia la Peña Alta, paseos arqueológicos hacia el Santuario del Pla de Petracos (pinturas rupestres prehistóricas, Patrimonio de la Humanidad por la UNESCO), senderos botánicos y micología de otoño.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03136','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales unifamiliares distribuidas en los ocho pequeños núcleos o pueblos rurales de piedra compactos que forman el valle (como Benialí o Alpatró), apartamentos rústicos con chimeneas de leña y fincas de agroturismo frutal de montaña. Entorno y actividades: El valle de los cerezos de la montaña de Alicante. Célebre a nivel nacional por el espectáculo botánico primaveral de la floración masiva del cerezo y sus dehesas agrícolas tradicionales en terrazas de piedra seca (Patrimonio de la Humanidad). Rutas de senderismo hacia la Foradada (colosal agujero natural en la cresta de la roca caliza de la montaña por donde pasa la luz del sol), caminatas micológicas, rutas cicloturistas de carretera de gran pendiente y turismo gastronómico-rural. PROVINCIA: MÁLAGA (Andalucía - Datos Curados).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90654','rural','Oferta de turismo rural','Alojamientos rurales: Celdas y dependencias históricas del Santuario de Lluc reconvertidas para la pernocta rústica, hostales de montaña para senderistas y refugios de la red de piedra seca. Entorno y actividades: El municipio de alta montaña por excelencia de las islas, ubicado en la Tramuntana norte. Sede de la espectacular y exigente ruta de senderismo del Torrent de Pareis (un colosal y profundo cañón kárstico de paredes calcáreas de más de 200 metros que muere en Sa Calobra). Ofrece ascensiones al Puig de Massanella, caminatas por encinares centenarios cerrados, escalada y senderos fluviales de montaña. 📂 PROVINCIA: MENORCA (Islas Baleares - Datos Curados).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32042','rural','Oferta de turismo rural','Alojamientos rurales: Casas de turismo rural típicas del interior de montaña, apartamentos rústicos de piedra y madera, e instalaciones balnearias vinculadas a surgencias de agua caliente. Entorno y actividades: Puerta de entrada oficial al Parque Natural Baixa Limia-Serra do Xurés (Reserva de la Biosfera transfronteriza con Portugal). Destaca por las pozas y termas naturales al aire libre de agua caliente y totalmente gratuitas de Río Caldo. Ofrece rutas de senderismo arqueológico siguiendo la Vía Nova (antigua calzada romana repleta de miliarios entre los bosques), senderos hacia la cascada de la Corga da Fecha, lobos y caballos salvajes en libertad en las cumbres.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45144','rural','Oferta de turismo rural','Alojamientos rurales: Casas de montaña de piedra tradicionales con gruesos muros aislantes, hostales rurales orientados al excursionismo y chalets rústicos de montaña independientes con chimenea de leña rodeados de naturaleza. Entorno y actividades: En el corazón de la Sierra de San Vicente (el pulmón verde del norte de Toledo). Destaca por las rutas de senderismo hacia el pico de Cruces, caminatas botánicas bajo los espectaculares y frondosos bosques de castaños centenarios (el castañar de El Real es único en la provincia), senderos micológicos micológicos otoñales (recogida de setas y castañas), paseos hacia las ruinas del convento del Piélago y dehesas forestales puras.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45153','rural','Oferta de turismo rural','Alojamientos rurales: Cabañas de madera forestales mimetizadas bajo densos encinares, casas rurales de piedra tradicionales serranas unifamiliares con porches y alojamientos de montaña orientados al turismo activo. Entorno y actividades: En pleno macizo de los Montes de Toledo altos, a más de 900 metros de altitud. Rutas de senderismo de media y alta montaña que exploran bosques mediterráneos aromáticos de encinas, quejigos y madroños centenarios, caminatas fluviales por el sendero del arroyo de la Dehesa con manantiales limpios de montaña, senderos micológicos otoñales extremos, avistamiento de ciervos (berrea) y rutas cicloturistas de montaña (BTT).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45075','rural','Oferta de turismo rural','Alojamientos rurales: Casas de campo de interior unifamiliares independientes con amplios porches de roca caliza, y pequeños apartamentos rurales rústicos de fin de semana en un valle resguardado de montaña. Entorno y actividades: Valle interior de los Montes de Toledo, lindando con el Parque Nacional de Cabañeros nororiental. Ofrece las rutas de senderismo arqueológico e histórico hacia el yacimiento arqueológico medieval del Malamoneda (con su torre fortificada, castillo enterrado en la naturaleza y necrópolis excavada en la roca viva), caminatas geológicas interpretativas por los barrancos de cuarcita, y observación astronómica de cielos negros. PROVINCIA: ZAMORA (Castilla y León - Datos Curados).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49085','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales de piedra de mampostería tradicional integradas en el entorno natural, cabañas forestales de madera junto al río y apartamentos turísticos rurales orientados al turismo activo familiar. Entorno y actividades: Integrado plenamente en el Parque Natural del Lago de Sanabria. Bañado por el río Tera joven. Sede de rutas de senderismo suave perimetral que bordean el lago y conectan con pequeñas pozas y playas fluviales (Playa de los Enanos, Playa Custa Llago). Ofrece senderos botánicos bajo densos robledales y castañares húmedos, paseos en piragua, cicloturismo de montaña y rutas de micología de pinar.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49214','rural','Oferta de turismo rural','Alojamientos rurales: Casas de campo agrícolas tradicionales bajas de tapial y piedra de interior, apartamentos rústicos con chimeneas y dehesas de agroturismo ganadero. Entorno y actividades: Piedemonte oriental de la Sierra de la Culebra, Camino de Santiago de la Plata (Camino Sanabrés). Ofrece rutas de senderismo plano de interpretación ambiental entre encinares centenarios y brezales, caminatas que se adentran en las lomas forestales linderas para el avistamiento de fauna ibérica silvestre (ciervo, corzo, lobo), cicloturismo de paseo familiar y observación de estrellas con cielos negros limpios. PROVINCIA: BADAJOZ (Extremadura - Datos Curados).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06013','rural','Oferta de turismo rural','Alojamientos rurales: Cortijos extremeños tradicionales restaurados con anchos muros de cal, dehesas ganaderas destinadas al agroturismo, complejos de cabañas de madera de interior y apartamentos rústicos a las faldas de su castillo fortificado medieval. Entorno y actividades: En pleno corazón de la Reserva de la Biosfera de La Siberia Extremeña. Flanqueado por la Reserva Nacional de Caza de Cíjara. Ofrece espectaculares rutas de senderismo y avistamiento ornitológico por los farallones de cuarcita y riscos del embalse de Cíjar, caminatas entre dehesas maduras de encinas y alcornoques, rutas micológicas otoñales, observación de la berrea del ciervo y observación astronómica nocturna bajo cielos negros certificados (Starlight).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06019','rural','Oferta de turismo rural','Alojamientos rurales: Palacetes de turismo de interior integrados en casonas nobiliarias señoriales con influencia lusoextremeña, hostales rurales con encanto en el casco amurallado gótico e históricas fincas agrícolas de dehesa. Entorno y actividades: Comarca de Llanos de Olivenza, lindando con la ribera del Guadiana y las aguas transfronterizas del Gran Lago de Alqueva. Ofrece la ruta de senderismo de los Alquevares (itinerarios que recorren dehesas ganaderas y campos llanos de cereal que miran al embalse), paseos fluviales por el embarcadero de Villarreal con la práctica de deportes náuticos sin motor (kayak, piragüismo, vela de interior), senderos ecuestres y cicloturismo de paseo familiar.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06010','rural','Oferta de turismo rural','Alojamientos rurales: Casonas solariegas bajas de dehesa de cal blanca unifamiliares con patios extremeños tradicionales llenos de fuentes y azulejos, apartamentos rústicos de montaña integrados en su castillo templario que aloja una plaza de toros interior, y fincas ganaderas dedicadas a la cría tradicional del cerdo ibérico de bellota. Entorno y actividades: Enclavado en las estribaciones de la Sierra Suroeste húmeda (Sierra Morena pacense). Meca del agroturismo ibérico; destaca por las rutas de interpretación ambiental por sus interminables e inmensos dehesas de encinas y alcornoques centenarios donde pasta el ganado en libertad. Rutas de senderismo plano de baja dificultad por antiguos caminos ganaderos, caminatas hacia los valles de olivos de pendiente y senderos micológicos de otoño.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06097','rural','Oferta de turismo rural','Alojamientos rurales: Complejos de casas rurales y apartamentos situados a orillas del agua, chalets de campo rústicos independientes con barbacoa y porches de roca caliza, y hostales de interior orientados al turismo náutico familiar. Entorno y actividades: Bañado por el colosal Embalse de Orellana. Sede de la Playa de Orellana ("Costa Dulce"), la primera playa fluvial de interior de España en conseguir el galardón internacional de Bandera Azul por la pureza de sus aguas cristalinas. Ofrece rutas de senderismo plano perimetral homologado (Senda del embalse), observación ornitológica de primer nivel en el humedal de la Zona ZEPA (aves acuáticas y palustres migratorias), windsurf, piragüismo y pesca deportiva limpia.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06016','rural','Oferta de turismo rural','Alojamientos rurales: Hostales rurales especializados en turismo de paso por la Vía de la Plata, casas de labranza tradicionales de montaña baja con chimeneas de leña, y cortijos ganaderos aislados en dehesas forestales. Entorno y actividades: Puerto de las Marismas, en pleno paso de la histórica Vía de la Plata y de la Sierra de Tentudía. Ofrece rutas de senderismo e interpretación ambiental e histórica que ascienden hacia el Monasterio de Tentudía (el punto más alto de la provincia a 1.100 metros de altitud), caminatas por dehesas ganaderas maduras bajo robles melojos y encinas viejas, senderos micológicos de otoño y turismo gastronómico de secaderos tradicionales. PROVINCIA: ZARAGOZA - ZONA MONCAYO E INTERIOR (Texto Plano Limpio).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30034','rural','Oferta de turismo rural','Alojamientos rurales: Casonas solariegas tradicionales moriscas con patios andalusíes y huertos integrados, apartamentos rústicos de colina aislados en el valle y casas de cal con porche de leña. Entorno y actividades: El municipio que da nombre al Valle de Ricote, encajonado de forma espectacular entre la Sierra de Ricote y el río Segura. Ofrece la ruta de senderismo de los Miradores del Valle, caminatas que ascienden hacia el pico de la Almudema entre pinares de pino carrasco y monte bajo aromático, senderos de interpretación de los antiguos sistemas de riego árabes y paseos fotográficos de naturaleza interior.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30011','rural','Oferta de turismo rural','Alojamientos rurales: Casas de pueblo tradicionales con fachadas de colores de alquiler íntegro a las faldas de la peña de su castillo, apartamentos rústicos de ribera y alojamientos orientados al turismo activo fluvial. Entorno y actividades: Asentado de forma monumental sobre un meandro del río Segura, flanqueado por el Embalse de Ojos. Destaca por el sendero fluvial que recorre la pasarela colgante sobre el río, descenso de ríos en kayak, piragüismo y rafting de relax, caminatas hacia el mirador del Alto de Bayna y paseos ecológicos entre cañaverales y dehesas frutales.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30031','rural','Oferta de turismo rural','Alojamientos rurales: Pequeñas casas de campo de labranza tradicionales independientes de interior con huerto ecológico de cítricos, y apartamentos rurales rústicos junto a acequias vivas de agua. Entorno y actividades: Custodia el Paraje Natural de las Norias de Ojos y el Embalse de Ojos. Sede de un espectacular recorrido de senderismo plano de baja dificultad (Ruta de las Norias) que visita colosales norias hidráulicas tradicionales de madera y hierro en activo que elevan el agua del Segura. Caminatas botánicas entre palmerales, dehesas agrícolas de huertos moriscos y observación ornitológica en tablas de agua. PROVINCIA: TENERIFE (Canarias - Datos Curados).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34027','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales de piedra integradas en antiguas dependencias de colonias mineras rehabilitadas para pernocta rústica, hostales de montaña e instalaciones familiares. Entorno y actividades: Vertiente oriental de la Montaña Palentina, comarca del valle de Santullán. Destaca por el espectacular e imponente soto del Hayedo de la Pedrosa y de Cillamayor. Ofrece rutas de senderismo e interpretación histórica minera (Senda del carbón), caminatas bajo túneles vegetales umbríos de hayas y robles caducifolios, senderos micológicos otoñales extremos, rutas cicloturistas y observación de fauna cantábrica (territorio de paso de oso pardo). PROVINCIA: ALICANTE (Comunidad Valenciana Datos Curados).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03057','rural','Oferta de turismo rural','Alojamientos rurales: Casas rurales de montaña de mampostería tradicional, apartamentos rústicos con chimenea de leña a gran altitud y alojamientos de turismo activo. Entorno y actividades: Situado en la cabecera del Valle de Guadalest, a las faldas de la Sierra de Aitana (el techo de Alicante). Ofrece exigentes rutas de senderismo alpino hacia la cumbre de Aitana (1.558 metros) y las Simas de Partagat, barranquismo técnico e hidrospeed en el barranco de Mela, senderos bajo bosques de encinas y pinos laricios, y recolección de setas en otoño. PROVINCIA: GRANADA (Andalucía - Datos Curados).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24004','rural','Oferta de turismo rural','Desfiladero norte de Sierra Morena y cascadas de agua del paraje de la Cimbarra.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23019','rural','Oferta de turismo rural','Parque de Sierra Mágina occidental, dehesas y garganta caliza de Puerta Arenas.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23065','rural','Oferta de turismo rural','Complejo recreativo fluvial de las piscinas naturales de Amurjo y pinares de umbría.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24016','rural','Oferta de turismo rural','Pequeñas dehesas ganaderas de la Sierra de Segura baja y dehesas forestales linderas.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18045','rural','Oferta de turismo rural','Casas cueva en el altiplano y riberas del río Guardal.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18070','rural','Oferta de turismo rural','Cañón del río Aguas Blancas, senderos de dehesas mediterráneas y huertas de cal.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90430','rural','Oferta de turismo rural','Ruta fluvial etnográfica de los Molinos y Arroyos en el Poniente granadino.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18168','rural','Oferta de turismo rural','Entorno forestal del embalse, pinares silvestres de repoblación viejos y senderos de sierra.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18176','rural','Oferta de turismo rural','Proyecto etnográfico alpujarreño de brujería.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18132','rural','Oferta de turismo rural','Ruta de las Pasarelas sobre el río Velillos, trincheras históricas y pinturas rupestres.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90038','rural','Oferta de turismo rural','Turismo rural de aislamiento en la vertiente sur de la Sierra de Lújar costera.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18123','rural','Oferta de turismo rural','Acceso norte de alta montaña al idílico paraje del Dehesa del Camarate (bosque encantado).','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90437','rural','Oferta de turismo rural','Valle del Genal profundo, dehesas forestales de castaños y turismo de aislamiento.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29040','rural','Oferta de turismo rural','Falda norte de la Sierra de Alcaparaín, dehesas mediterráneas y huertos tradicionales de cal.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90434','rural','Oferta de turismo rural','El pueblo más alto de la Axarquía, rodeado de infinitos campos de cerezos de pendiente.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29033','rural','Oferta de turismo rural','Acceso principal al vertiginoso puente colgante de El Saltillo sobre el cañón.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29061','rural','Oferta de turismo rural','Manantiales y surgencias de agua limpia del río Verde bajo la Sierra Blanca caliza.','inventario_turismo_rural_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29036','rural','Oferta de turismo rural','Aguas termales azufradas medicinales de interior y palacetes burgueses tradicionales.','inventario_turismo_rural_pdf');
